app.post('/api/me/mutation', authMiddleware, async (req, res) => {
  try {
    const id = req.user.user_id || req.user.id;
    const b = req.body || {};
    const cur = (await pool.query('SELECT name, wohnung, stweg, phone, strasse, plz, ort FROM users WHERE id = $1', [id])).rows[0] || {};
    const f = {
      name: b.name != null ? String(b.name).trim().slice(0, 200) : (cur.name || ''),
      phone: b.phone != null ? (String(b.phone).trim().slice(0, 60) || null) : cur.phone,
      strasse: b.strasse != null ? (String(b.strasse).trim().slice(0, 200) || null) : cur.strasse,
      plz: b.plz != null ? (String(b.plz).trim().slice(0, 20) || null) : cur.plz,
      ort: b.ort != null ? (String(b.ort).trim().slice(0, 120) || null) : cur.ort,
    };
    if (!f.name) return res.status(400).json({ error: 'Name erforderlich' });
    const labels = { name: 'Name', phone: 'Telefon', strasse: 'Strasse', plz: 'PLZ', ort: 'Ort' };
    const changes = [];
    for (const k of Object.keys(labels)) {
      const oldV = String(cur[k] || ''), newV = String(f[k] || '');
      if (oldV !== newV) changes.push(`${labels[k]}: "${oldV || '–'}" → "${newV || '–'}"`);
    }
    await pool.query(
      'UPDATE users SET name=$1, phone=$2, strasse=$3, plz=$4, ort=$5, updated_at=NOW() WHERE id=$6',
      [f.name, f.phone, f.strasse, f.plz, f.ort, id]);
    if (changes.length) {
      const wohnLabel = cur.wohnung ? ` (Whg ${cur.wohnung})` : '';
      const line = `${f.name}${wohnLabel}: ${changes.join('; ')}`;
      recordObjektChange(cur.stweg, line, req.user.email).catch(() => {});
    }
    res.json({ ok: true, changed: changes });
  } catch (e) { console.error('[me/mutation POST]', e); res.status(500).json({ error: 'Fehler beim Speichern' }); }
});

// PUT /api/me/whatsapp-optin — Toggle WhatsApp-Opt-In am Personen-Datensatz
// Body: { enabled: bool }
// Liefert Status zurück: { ok, enabled, phone, reason? }
app.put('/api/me/whatsapp-optin', authMiddleware, async (req, res) => {
  const email = (req.user.email || '').toLowerCase();
  if (!email) return res.status(400).json({ error: 'Keine E-Mail' });
  const enabled = !!req.body?.enabled;
  try {
    const person = await pool.query(
      `SELECT id, name, telefon, mobile, telefone, whatsapp_opt_in
         FROM personen WHERE LOWER(email) = $1 LIMIT 1`,
      [email]
    );
    if (!person.rows[0]) {
      return res.status(404).json({
        error: 'Kein Personen-Eintrag für diese E-Mail gefunden',
        hint: 'Bitte zuerst Telefonnummer in der Objektverwaltung hinterlegen lassen.',
      });
    }
    const p = person.rows[0];
    // Pick a usable phone: mobile -> telefon -> telefone[0].nummer
    let phone = p.mobile || p.telefon || null;
    if (!phone && Array.isArray(p.telefone) && p.telefone.length > 0) {
      phone = p.telefone[0]?.nummer || null;
    }
    if (enabled && !phone) {
      return res.status(400).json({
        error: 'Keine Telefonnummer hinterlegt',
        hint: 'WhatsApp-Benachrichtigungen benötigen eine Telefonnummer im Profil.',
      });
    }
    await pool.query(
      `UPDATE personen SET whatsapp_opt_in = $1, updated_at = NOW() WHERE id = $2`,
      [enabled, p.id]
    );
    res.json({ ok: true, enabled, phone });
  } catch (err) {
    console.error('[whatsapp-optin] error:', err.message);
    res.status(500).json({ error: 'Fehler beim Speichern' });
  }
});

// WiFi info for authenticated users (PPSK from UniFi)
const UNIFI_API_KEY = process.env.UNIFI_API_KEY || ''; // aus /root/.env (env_file); KEIN hardcoded Fallback
const UNIFI_HOST = process.env.UNIFI_HOST || 'https://100.64.2.1';

app.get('/api/wifi', authMiddleware, async (req, res) => {
  try {
    // Get network configs (ID → name/vlan mapping)
    const netResp = await fetch(`${UNIFI_HOST}/proxy/network/api/s/default/rest/networkconf`, {
      headers: { 'X-API-Key': UNIFI_API_KEY },
      signal: AbortSignal.timeout(5000),
    });
    const nets = (await netResp.json()).data || [];
    const netMap = {};
    for (const n of nets) {
      netMap[n._id] = { name: n.name, vlan: n.vlan || null, subnet: n.ip_subnet || null };
    }

    // Get WLAN config with PPSKs
    const wlanResp = await fetch(`${UNIFI_HOST}/proxy/network/api/s/default/rest/wlanconf`, {
      headers: { 'X-API-Key': UNIFI_API_KEY },
      signal: AbortSignal.timeout(5000),
    });
    const wlans = (await wlanResp.json()).data || [];
    const rosenweg = wlans.find(w => w.name === 'Rosenweg' && w.enabled);
    if (!rosenweg) return res.status(404).json({ error: 'WLAN nicht gefunden' });

    // Extract house numbers from Authentik groups (e.g. "r9-bewohner", "r14-eigentuemer")
    // bewohner groups take priority over eigentuemer
    const groups = req.user.groups || [];
    const bewohnerHaeuser = new Set();
    const eigentuemerHaeuser = new Set();
    for (const g of groups) {
      const m = g.match(/^r(\d+)-(bewohner|eigentuemer)$/i);
      if (m) {
        if (m[2].toLowerCase() === 'bewohner') bewohnerHaeuser.add(parseInt(m[1]));
        else eigentuemerHaeuser.add(parseInt(m[1]));
      }
    }
    // Only show houses where user is bewohner; eigentuemer without bewohner see nothing
    const hausNummern = bewohnerHaeuser;

    // Plus: Häuser aus den zugewiesenen Wohnungen ableiten (Wohnung oder
    // Hobbyraum in irgendeinem Haus). So sieht jemand mit Wohnung RW9 +
    // Hobbyraum RW2 auch das RW2-Clients-WLAN, nicht nur RW9.
    const userEmailForHaus = (req.user.email || '').toLowerCase();
    let userWohnungen = [];
    try {
      userWohnungen = await getUserVlanOptions(userEmailForHaus);
      for (const opt of userWohnungen) {
        if (opt.kind === 'wohnung' || opt.kind === 'hobbyraum') {
          // VLAN-Schema: <HausNr>*10+9 → HausNr = (vlan-9)/10
          const haus = opt.vlan ? Math.round((opt.vlan - 9) / 10) : null;
          if (haus && haus >= 1 && haus <= 18) hausNummern.add(haus);
        }
      }
    } catch {}

    // Fallback: extract from strasse field
    if (hausNummern.size === 0) {
      const userId = req.user.user_id || req.user.id;
      const userRow = await pool.query('SELECT strasse FROM users WHERE id = $1', [userId]);
      const strasse = userRow.rows[0]?.strasse || '';
      const hausMatch = strasse.match(/rosenweg\s+(\d+)/i);
      if (hausMatch) hausNummern.add(parseInt(hausMatch[1]));
    }

    // Find PPSKs for all user's houses (still nur falls vorhanden — nicht jedes
    // Haus muss eine eigene PPSK-Konfiguration haben).
    const userWlans = [];
    if (rosenweg.private_preshared_keys_enabled) {
      for (const hausNr of hausNummern) {
        const targetNet = `RW${hausNr}-Clients`;
        for (const ppsk of rosenweg.private_preshared_keys || []) {
          const net = netMap[ppsk.networkconf_id];
          if (net && net.name === targetNet) {
            userWlans.push({
              hausNr,
              password: ppsk.password,
              network: net.name,
              vlan: net.vlan,
              subnet: net.subnet,
              rolle: bewohnerHaeuser.has(hausNr) ? 'bewohner' : 'eigentuemer',
            });
            break;
          }
        }
      }

      // RK-Clients-WLAN nur für reine Parkplatz-User (kein wohnung/hobbyraum
      // bezogen). Wer auch eine Wohnung oder Hobbyraum hat, sieht stattdessen
      // sein normales Haus-WLAN — die brauchen RK-Clients nicht.
      const kinds = new Set(userWohnungen.map(o => o.kind));
      const showRk = kinds.has('parkplatz') && !kinds.has('wohnung') && !kinds.has('hobbyraum');
      if (showRk) {
        for (const ppsk of rosenweg.private_preshared_keys || []) {
          const net = netMap[ppsk.networkconf_id];
          if (net && net.name === 'RK-Clients') {
            userWlans.push({
              hausNr: null,
              isRkClients: true,
              password: ppsk.password,
              network: net.name,
              vlan: net.vlan,
              subnet: net.subnet,
              rolle: 'parkplatz',
            });
            break;
          }
        }
      }

      // Plus alle user-VLANs aus isp_vlan_requests wo der User Antragsteller
      // oder Mitnutzer ist UND with_wlan=true UND status=deployed.
      const email = (req.user.email || '').toLowerCase();
      const myVlans = await pool.query(`
        SELECT vlan_id, gewuenschter_name, subnet_v4, with_wlan, wlan_password,
               unifi_network_id, antragsteller_email,
               LOWER(antragsteller_email) = $1 AS is_owner
          FROM isp_vlan_requests
         WHERE status = 'deployed'
           AND with_wlan = true
           AND wlan_password IS NOT NULL
           AND (LOWER(antragsteller_email) = $1
                OR $1 = ANY(COALESCE(mitnutzer_emails, ARRAY[]::TEXT[])))
      `, [email]);
      for (const row of myVlans.rows) {
        const net = row.unifi_network_id ? netMap[row.unifi_network_id] : null;
        userWlans.push({
          hausNr: null,
          isUserVlan: true,
          password: row.wlan_password,
          network: net?.name || row.gewuenschter_name || `vlan-${row.vlan_id}`,
          vlan: row.vlan_id,
          subnet: row.subnet_v4,
          rolle: row.is_owner ? 'antragsteller' : 'mitnutzer',
          ownerEmail: row.is_owner ? null : row.antragsteller_email,
        });
      }
    }

    // Build all PPSKs for admins
    let allPpsks = null;
    if (req.user.isAdmin) {
      allPpsks = (rosenweg.private_preshared_keys || []).map(ppsk => {
        const net = netMap[ppsk.networkconf_id] || {};
        return { network: net.name, vlan: net.vlan, password: ppsk.password };
      });
    }

    res.json({
      ssid: 'Rosenweg',
      wlans: userWlans,
      guest: { ssid: 'Rosenweg-Guest', password: null, security: 'open' },
      allPpsks,
    });
  } catch (err) {
    console.error('WiFi info error:', err.message);
    res.status(500).json({ error: 'WiFi-Daten konnten nicht geladen werden' });
  }
});

// ─── TV7 (Init7 IPTV) ────────────────────────────────────────────────
//
// Architektur (Stand 2026-06-11):
//   Browser → /api/tv/channels       (API, Authentik-Session)
//   Browser → /api/tv/stream/<id>    (API, Authentik-Session)
//             ↓ pipe MPEG-TS
//          tv7-streamer (LXC 250, 100.64.9.23:3000)
//             ↓ spawn ffmpeg
//          api.tv.init7.net (HLS, AC-3 audio)
//
// Warum eigener LXC: ffmpeg-Transcode (AC-3 → AAC) ist CPU-intensiv und
// gehört nicht in den rosenweg_api-Container.
//
// udpxy für Multicast laeuft in LXC 109 (100.64.9.200:4022) — aktuell
// blockiert die UDM-Firewall den Init7-Multicast-Inflow, deshalb HLS-Pfad.
const TV7_PLAYLIST_URL = 'https://api.init7.net/tvchannels.m3u?rp=true';
const UDPXY_HOST = process.env.UDPXY_HOST || 'http://100.64.9.24:4022';
const TV7_STREAMER_URL = process.env.TV7_STREAMER_URL || 'http://100.64.9.23:3000';
// Public-Pfad den der Browser für den Stream anspricht. Default ist ein
// relativer Pfad — die nginx der ISP-Seite proxyt /tv-stream/* direkt zum
// LXC 250, kein API-Hop. Wenn ein voller URL gesetzt ist (z.B. via CF
// Tunnel auf tv.rosenweg9.ch), wird der genommen.
const TV7_PUBLIC_URL = process.env.TV7_PUBLIC_URL || '/tv-stream';
const TV7_HMAC_SECRET = process.env.TV7_HMAC_SECRET || '';
const TV7_TOKEN_TTL = 3600; // 1 hour

let tv7ChannelsCache = null;
let tv7CacheTime = 0;

// Multicast-only-Sender (kein HTTP-channel-id) bekommen eine stabile hex+bindestrich-
// ID aus der Gruppe (233.50.230.57 -> e9-32-e6-39) — passt durch die id-Regex und
// IDENTISCH zur Logik im tv7-streamer (mcastId), damit /stream/<id> dort aufgeht.
function mcastIdFromGroup(group) {
  return group.split('.').map(o => parseInt(o, 10).toString(16).padStart(2, '0')).join('-');
}

function parseTV7Playlist(text) {
  const out = [];
  const lines = (text || '').split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    if (!lines[i].startsWith('#EXTINF')) continue;
    const url = (lines[i + 1] || '').trim();
    if (!url || url.startsWith('#')) continue;
    out.push({
      logo: (lines[i].match(/tvg-logo="([^"]*)"/) || [])[1] || '',
      tvg: (lines[i].match(/tvg-name="([^"]*)"/) || [])[1] || '',
      group: (lines[i].match(/group-title="([^"]*)"/) || [])[1] || '',
      name: ((lines[i].match(/,\s*(.+)$/) || [])[1] || '').trim(),
      url,
    });
  }
  return out;
}

// Alle 242 Sender aus der Multicast-Liste, gemerged mit HTTP-channel-ids (fuer den
// H.264-Pfad). Spiegelt getChannels() im tv7-streamer (gleiche IDs).
async function fetchTV7Channels() {
  if (tv7ChannelsCache && Date.now() - tv7CacheTime < 3600000) return tv7ChannelsCache;
  const [httpResp, mcResp] = await Promise.all([
    fetch('https://api.init7.net/tvchannels.m3u?rp=true', { signal: AbortSignal.timeout(10000) }),
    fetch('https://api.init7.net/tvchannels.m3u', { signal: AbortSignal.timeout(10000) }),
  ]);
  const httpEntries = parseTV7Playlist(await httpResp.text());
  const mcEntries = parseTV7Playlist(await mcResp.text());
  const httpMap = {};
  for (const e of httpEntries) {
    const id = (e.url.match(/channel=([a-f0-9-]+)/i) || [])[1];
    if (id) httpMap[e.tvg] = id;
  }
  const channels = [];
  for (const e of mcEntries) {
    const u = e.url.match(/udp:\/\/@?([\d.]+):(\d+)/i);
    if (!u) continue;
    const httpId = httpMap[e.tvg] || null;
    channels.push({
      id: httpId || mcastIdFromGroup(u[1]),
      name: e.name || e.tvg || 'Unknown',
      logo: e.logo,
      group: e.group,
      hevc: true,
      h264: !!httpId,
    });
  }
  tv7ChannelsCache = channels;
  tv7CacheTime = Date.now();
  return channels;
}

app.get('/api/tv/channels', authMiddleware, async (req, res) => {
  try {
    const channels = await fetchTV7Channels();
    res.json(channels);
  } catch (err) {
    console.error('TV7 channels error:', err.message);
    res.status(500).json({ error: 'TV7-Kanäle konnten nicht geladen werden' });
  }
});

// Browser holt sich hier nur den Token + die public Stream-URL — keine
// MPEG-TS-Bytes mehr durch die API. Player verbindet sich direkt mit dem
// LXC via CF Tunnel.
// Multicast-Playlist (alle Sender als udpxy-HTTP-URLs, cross-VLAN) fuer native
// Player. Wird hier (statt im Streamer) ausgeliefert, weil die ISP-nginx den
// Streamer im RK-Clients-VLAN nicht erreicht, die API ueber das Overlay aber schon.
// Kein Auth — sind nur udpxy-URLs, abspielbar nur im Hausnetz.
app.get('/api/tv/playlist.m3u', async (req, res) => {
  try {
    const udpxy = process.env.UDPXY_BASE || 'http://100.64.9.24:4022';
    const r = await fetch('https://api.init7.net/tvchannels.m3u', {
      signal: AbortSignal.timeout(8000),
    });
    if (!r.ok) throw new Error('init7 HTTP ' + r.status);
    let body = await r.text();
    // EPG-Referenz (Apps laden xmltv automatisch) + tvg-id (=tvg-name) fuers Mapping
    body = body.replace(/^#EXTM3U.*/m, '#EXTM3U url-tvg="https://tv.rosenweg4303.ch/epg.xml" x-tvg-url="https://tv.rosenweg4303.ch/epg.xml"');
    body = body.replace(/(#EXTINF:[^\n]*?)tvg-name="([^"]+)"/g, (m, pre, name) => m.includes('tvg-id=') ? m : `${pre}tvg-id="${name}" tvg-name="${name}"`);
    // Live-Kanaele: Dauer 0 -> -1 (sonst behandeln viele Player den Kanal als
    // 0-Sekunden-Clip und spielen ihn nicht, z.B. TiviMate).
    body = body.replace(/^#EXTINF:0([ ,])/gm, '#EXTINF:-1$1');
    // udp://@<gruppe>:<port> -> http://<udpxy>/udp/<gruppe>:<port>
    body = body.replace(/^udp:\/\/@?([\d.]+):(\d+).*$/gm, (_m, g, p) => `${udpxy}/udp/${g}:${p}`);
    res.set('Content-Type', 'audio/x-mpegurl; charset=utf-8');
    res.set('Cache-Control', 'public, max-age=1800');
    res.send(body);
  } catch (e) {
    res.status(502).json({ error: e.message });
  }
});

// ─── TV7 EPG (XMLTV) ─────────────────────────────────────────────────
// Init7-EPG-API (api.tv.init7.net/api/epg/) ist zeitsortiert + paginiert.
// Wir holen nur den Zukunfts-Tail (now-3h .. Ende) und bauen XMLTV.
// channel id = canonical_name (= tvg-name in der Playlist). Cache 6h.
let _tv7EpgCache = null;
const TV7_EPG_TTL = 6 * 3600 * 1000;
function tv7XmlEsc(s) {
  return String(s == null ? '' : s).replace(/[<>&'"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' }[c]));
}
function tv7XmltvTime(iso) {
  const d = new Date(iso); const p = n => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())} +0000`;
}
async function buildTV7Epg() {
  const BASE = 'https://api.tv.init7.net/api/epg/';
  const head = await (await fetch(`${BASE}?limit=1`, { signal: AbortSignal.timeout(15000) })).json();
  const total = head.count || 0;
  const minTs = Date.now() - 3 * 3600 * 1000; // ab 3h vor jetzt
  const LIMIT = 20000;
  let offset = Math.max(0, total - 90000); // Zukunfts-Tail (~letzte ~7 Tage)
  const channels = new Map();
  const programmes = [];
  while (offset < total) {
    const page = await (await fetch(`${BASE}?limit=${LIMIT}&offset=${offset}`, { signal: AbortSignal.timeout(30000) })).json();
    for (const r of (page.results || [])) {
      if (new Date(r.timeslot.lower).getTime() < minTs) continue;
      const ch = r.channel || {}; const id = ch.canonical_name;
      if (!id) continue;
      if (!channels.has(id)) channels.set(id, { name: ch.name || id, logo: ch.logo || '' });
      programmes.push({ id, start: r.timeslot.lower, stop: r.timeslot.upper, title: r.title, sub: r.sub_title, desc: r.desc });
    }
    offset += LIMIT;
  }
  let xml = '<?xml version="1.0" encoding="UTF-8"?>\n<tv generator-info-name="rosenweg-tv">\n';
  for (const [id, c] of channels) {
    xml += `  <channel id="${tv7XmlEsc(id)}"><display-name>${tv7XmlEsc(c.name)}</display-name>${c.logo ? `<icon src="${tv7XmlEsc(c.logo)}"/>` : ''}</channel>\n`;
  }
  for (const p of programmes) {
    xml += `  <programme start="${tv7XmltvTime(p.start)}" stop="${tv7XmltvTime(p.stop)}" channel="${tv7XmlEsc(p.id)}">`;
    xml += `<title>${tv7XmlEsc(p.title)}</title>`;
    if (p.sub) xml += `<sub-title>${tv7XmlEsc(p.sub)}</sub-title>`;
    if (p.desc) xml += `<desc>${tv7XmlEsc(p.desc)}</desc>`;
    xml += `</programme>\n`;
  }
  xml += '</tv>\n';
  return { xml, channels: channels.size, programmes: programmes.length };
}
app.get('/api/tv/epg.xml', async (req, res) => {
  try {
    if (!_tv7EpgCache || (Date.now() - _tv7EpgCache.ts) > TV7_EPG_TTL) {
      const built = await buildTV7Epg();
      _tv7EpgCache = { xml: built.xml, ts: Date.now() };
      console.log(`[TV7-EPG] gebaut: ${built.channels} Kanaele, ${built.programmes} Sendungen`);
    }
    res.set('Content-Type', 'application/xml; charset=utf-8');
    res.set('Cache-Control', 'public, max-age=3600');
    res.send(_tv7EpgCache.xml);
  } catch (e) {
    if (_tv7EpgCache) { res.set('Content-Type', 'application/xml; charset=utf-8'); return res.send(_tv7EpgCache.xml); }
    console.error('[TV7-EPG] error:', e.message);
    res.status(502).json({ error: e.message });
  }
});

app.get('/api/tv/stream-url/:channelId', authMiddleware, (req, res) => {
  const id = req.params.channelId;
  if (!/^[a-f0-9-]+$/i.test(id)) return res.status(400).json({ error: 'Invalid channel id' });
  if (!TV7_HMAC_SECRET) return res.status(500).json({ error: 'TV7 streamer secret nicht konfiguriert' });
  const token = createTv7StreamerToken(req.user.id || req.user.user_id || 0);
  // Pfad-Variante (default /tv-stream): nginx rewrite haengt /<id> direkt
  // an, also Endpunkt ist `${TV7_PUBLIC_URL}/<id>?token=...`.
  // Full-URL-Variante (z.B. https://tv.rosenweg9.ch): LXC erwartet
  // `/stream/<id>?token=...`.
  const isFullUrl = /^https?:\/\//i.test(TV7_PUBLIC_URL);
  const url = isFullUrl
    ? `${TV7_PUBLIC_URL}/stream/${id}?token=${encodeURIComponent(token)}`
    : `${TV7_PUBLIC_URL}/${id}?token=${encodeURIComponent(token)}`;
  res.json({ url, expires_in: TV7_TOKEN_TTL });
});

// HMAC-Token kompatibel mit tv7-streamer/server.js verifyToken().
// Format: base64url(payload).hex16(sig)   payload = {user, exp}
function createTv7StreamerToken(userId) {
  if (!TV7_HMAC_SECRET) throw new Error('TV7_HMAC_SECRET nicht konfiguriert');
  const payloadObj = { user: userId, exp: Math.floor(Date.now() / 1000) + TV7_TOKEN_TTL };
  const payload = Buffer.from(JSON.stringify(payloadObj)).toString('base64url');
  const sig = crypto.createHmac('sha256', TV7_HMAC_SECRET).update(payload).digest('hex').slice(0, 16);
  return `${payload}.${sig}`;
}

// Stream-Endpoint: Browser holt sich hier den MPEG-TS via API,
// API proxyt durch zum tv7-streamer im LXC. Doppel-Hop ist akzeptabel
// (~12 Mbps pro Zuschauer), spart aber CORS/DNS-Komplexitaet im Browser.
app.get('/api/tv/stream/:channelId', (req, res, next) => {
  if (!req.headers.authorization && req.query.token) {
    req.headers.authorization = `Bearer ${req.query.token}`;
  }
  next();
}, authMiddleware, async (req, res) => {
  const id = req.params.channelId;
  if (!/^[a-f0-9-]+$/i.test(id)) return res.status(400).json({ error: 'Invalid channel id' });
  if (!TV7_HMAC_SECRET) return res.status(500).json({ error: 'TV7 streamer secret nicht konfiguriert' });
  const token = createTv7StreamerToken(req.user.id || req.user.user_id || 0);
  const streamUrl = `${TV7_STREAMER_URL}/stream/${id}?token=${encodeURIComponent(token)}`;
  // Connection-Timeout nur für die initialen Headers — danach soll der Stream
  // beliebig lange laufen. AbortSignal.timeout() wuerde auch den Body killen.
  const ctrl = new AbortController();
  const connTimer = setTimeout(() => ctrl.abort(), 10000);
  let upstream;
  try {
    upstream = await fetch(streamUrl, { signal: ctrl.signal });
  } catch (err) {
    clearTimeout(connTimer);
    console.error('TV7 stream fetch failed:', err.message);
    if (!res.headersSent) res.status(502).json({ error: 'Streamer nicht erreichbar' });
    return;
  }
  clearTimeout(connTimer);
  if (!upstream.ok) {
    console.error('TV7 streamer status:', upstream.status);
    return res.status(502).json({ error: 'Streamer nicht erreichbar' });
  }
  res.setHeader('Content-Type', upstream.headers.get('content-type') || 'video/MP2T');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Access-Control-Allow-Origin', '*');
  const reader = upstream.body.getReader();
  req.on('close', () => { try { reader.cancel(); } catch {} });
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (!res.write(Buffer.from(value))) await new Promise(r => res.once('drain', r));
    }
  } catch (err) {
    // Client hat abgebrochen — normal bei Channel-Wechsel
    if (err.code !== 'ABORT_ERR' && err.name !== 'AbortError') {
      console.error('TV7 stream pipe error:', err.message);
    }
  }
  try { res.end(); } catch {}
});

// ─── TV7 Extern (udpxy-Playlist fuer Ferien/Reisen, token-geschuetzt) ─────────
// udpxy relayt den Multicast als HTTP (alle 242 Sender, kein Transcode). Die nginx
// auf isp.rosenweg4303.ch proxyt /tv-udp/<grp>:<port> via auth_request an
// /api/tv/extern/validate und dann an udpxy. Token = DB-Eintrag (verlaengerbar/
// widerrufbar im Interface), KEIN stateless HMAC.
const TV_EXTERN_BASE = process.env.TV_EXTERN_BASE || 'https://isp.rosenweg4303.ch';
const TV_EXTERN_TTL_DAYS = 30;
async function ensureTvExternTable() {
  await pool.query(`CREATE TABLE IF NOT EXISTS tv_extern_tokens (
    id SERIAL PRIMARY KEY,
    token TEXT UNIQUE NOT NULL,
    user_email TEXT NOT NULL,
    label TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    last_used_at TIMESTAMPTZ,
    revoked BOOLEAN DEFAULT FALSE)`);
  await pool.query('CREATE INDEX IF NOT EXISTS idx_tv_extern_token ON tv_extern_tokens(token)');
}
setTimeout(() => ensureTvExternTable().catch(e => console.warn('[tv-extern] init:', e.message)), 12000);

async function tvExternValidate(token) {
  if (!token) return false;
  const r = await pool.query('SELECT id FROM tv_extern_tokens WHERE token = $1 AND revoked = FALSE AND expires_at > NOW() LIMIT 1', [String(token)]);
  if (!r.rows[0]) return false;
  pool.query('UPDATE tv_extern_tokens SET last_used_at = NOW() WHERE id = $1', [r.rows[0].id]).catch(() => {});
  return true;
}

// nginx auth_request-Ziel: schnell 200/403 (kein Auth — der Token IST die Auth).
app.get('/api/tv/extern/validate', async (req, res) => {
  try { res.status((await tvExternValidate(req.query.token)) ? 200 : 403).end(); }
  catch { res.status(403).end(); }
});

// Token erstellen
app.post('/api/tv/extern/token', authMiddleware, async (req, res) => {
  try {
    const email = (req.user.email || '').toLowerCase();
    const label = String(req.body?.label || 'Ferien').slice(0, 80);
    const token = crypto.randomBytes(18).toString('base64url');
    const exp = new Date(Date.now() + TV_EXTERN_TTL_DAYS * 86400000);
    await pool.query('INSERT INTO tv_extern_tokens (token, user_email, label, expires_at) VALUES ($1,$2,$3,$4)', [token, email, label, exp]);
    res.json({ ok: true, token, m3u_url: `${TV_EXTERN_BASE}/api/tv/extern.m3u?token=${token}`, expires_at: exp });
  } catch (e) { console.error('[tv-extern-create]', e); res.status(500).json({ error: 'Fehler' }); }
});

// Eigene Tokens auflisten
app.get('/api/tv/extern/tokens', authMiddleware, async (req, res) => {
  try {
    const email = (req.user.email || '').toLowerCase();
    const r = await pool.query(
      `SELECT id, token, label, created_at, expires_at, last_used_at, revoked, (expires_at < NOW()) AS expired
         FROM tv_extern_tokens WHERE LOWER(user_email) = $1 ORDER BY created_at DESC`, [email]);
    res.json({ tokens: r.rows, base: TV_EXTERN_BASE });
  } catch (e) { res.status(500).json({ error: 'Fehler' }); }
});

// Verlaengern (+30 Tage ab jetzt, hebt revoke auf)
app.post('/api/tv/extern/token/:id/extend', authMiddleware, async (req, res) => {
  try {
    const email = (req.user.email || '').toLowerCase();
    const exp = new Date(Date.now() + TV_EXTERN_TTL_DAYS * 86400000);
    const r = await pool.query('UPDATE tv_extern_tokens SET expires_at = $1, revoked = FALSE WHERE id = $2 AND LOWER(user_email) = $3 RETURNING expires_at',
      [exp, parseInt(req.params.id, 10), email]);
    if (!r.rows[0]) return res.status(404).json({ error: 'Nicht gefunden' });
    res.json({ ok: true, expires_at: r.rows[0].expires_at });
  } catch (e) { res.status(500).json({ error: 'Fehler' }); }
});

// Widerrufen/Loeschen
app.delete('/api/tv/extern/token/:id', authMiddleware, async (req, res) => {
  try {
    const email = (req.user.email || '').toLowerCase();
    await pool.query('DELETE FROM tv_extern_tokens WHERE id = $1 AND LOWER(user_email) = $2', [parseInt(req.params.id, 10), email]);
    res.json({ ok: true });
  } catch (e) { res.status(500).json({ error: 'Fehler' }); }
});

// Tokenisierte Playlist: alle Sender als udpxy-Proxy-URLs auf isp (extern erreichbar).
app.get('/api/tv/extern.m3u', async (req, res) => {
  try {
    const token = String(req.query.token || '');
    if (!(await tvExternValidate(token))) return res.status(403).type('text/plain').send('# ungueltiger oder abgelaufener Token');
    const r = await fetch('https://api.init7.net/tvchannels.m3u', { signal: AbortSignal.timeout(8000) });
    if (!r.ok) throw new Error('init7 HTTP ' + r.status);
    let body = await r.text();
    body = body.replace(/^#EXTM3U.*/m, '#EXTM3U url-tvg="https://tv.rosenweg4303.ch/epg.xml" x-tvg-url="https://tv.rosenweg4303.ch/epg.xml"');
    body = body.replace(/(#EXTINF:[^\n]*?)tvg-name="([^"]+)"/g, (m, pre, name) => m.includes('tvg-id=') ? m : `${pre}tvg-id="${name}" tvg-name="${name}"`);
    body = body.replace(/^#EXTINF:0([ ,])/gm, '#EXTINF:-1$1');
    // udp://@<grp>:<port> -> <BASE>/tv-udp/<grp>:<port>?token=<token>
    body = body.replace(/udp:\/\/@?([\d.]+):(\d+)/gi, (m, grp, port) => `${TV_EXTERN_BASE}/api/tv/extern/stream?token=${encodeURIComponent(token)}&ch=${grp}:${port}`);
    res.setHeader('Content-Type', 'application/vnd.apple.mpegurl; charset=utf-8');
    res.send(body);
  } catch (e) { console.error('[tv-extern-m3u]', e); res.status(500).type('text/plain').send('# Fehler'); }
});

// Stream-Einstieg: Token validieren -> via X-Accel-Redirect an nginx delegieren,
// das den udpxy-Multicast intern relayt (kein MPEG-TS durch die API). Zuverlaessiger
// als nginx auth_request (Query-Subrequest-Tuecken).
app.get('/api/tv/extern/stream', async (req, res) => {
  try {
    const token = String(req.query.token || '');
    const ch = String(req.query.ch || '');
    if (!/^[\d.]+:\d+$/.test(ch)) return res.status(400).end();
    if (!(await tvExternValidate(token))) return res.status(403).end();
    res.setHeader('X-Accel-Redirect', `/tv-udp-internal/${ch}`);
    res.setHeader('Content-Type', 'video/MP2T');
    res.end();
  } catch (e) { console.error('[tv-extern-stream]', e); if (!res.headersSent) res.status(500).end(); }
});

