// List all Verteiler
app.get('/api/verteiler', authMiddleware, adminOnly, async (req, res) => {
  try {
    const result = await pool.query(
      `SELECT id, stweg, name, email_address, members, active,
              reply_to, subject_prefix, group_name, group_names, created_at,
              whatsapp_group_id, whatsapp_group_name, external_allowed,
              jsonb_array_length(COALESCE(members, '[]'::jsonb)) as member_count
       FROM email_verteiler ORDER BY stweg, name`
    );
    // For group-based verteiler, resolve actual member count.
    // War ~22s: jede Authentik-Gruppe loeste 2 Full-List-Calls (/core/groups,
    // /core/users) aus -> N x 2 Authentik-Calls. Jetzt: die teuren Listen genau
    // EINMAL pro Request holen, Authentik-Gruppen in-memory aufloesen; jede
    // distinkte Gruppe nur einmal (Memo). verwaltung:-Gruppen sind lokale
    // DB-Queries (schnell) und laufen parallel.
    const rows = result.rows;
    const needsAuthentik = rows.some(v => {
      const gns = v.group_names?.length ? v.group_names : (v.group_name ? [v.group_name] : []);
      return gns.some(gn => !gn.startsWith('verwaltung:'));
    });
    let authData = null;
    if (needsAuthentik) {
      try { authData = await fetchAuthentikGroupsUsers(); }
      catch { authData = { allGroups: [], allUsers: [] }; }
    }
    const groupCache = new Map();
    const resolveOnce = (gn) => {
      if (!groupCache.has(gn)) {
        groupCache.set(gn, gn.startsWith('verwaltung:')
          ? resolveVerwaltungsGroup(gn).catch(() => [])
          : Promise.resolve(authData ? resolveGroupEmailsFromData(gn, authData.allGroups, authData.allUsers) : []));
      }
      return groupCache.get(gn);
    };
    await Promise.all(rows.map(async (v) => {
      const groupNames = v.group_names?.length ? v.group_names : (v.group_name ? [v.group_name] : []);
      if (groupNames.length === 0) return;
      const lists = await Promise.all(groupNames.map(resolveOnce));
      const allEmails = new Set();
      for (const emails of lists) {
        // Filter out base drucker addresses without +tag (kein Empfänger zugeordnet)
        emails.filter(e => !/^druckerr(9|13)@/.test(e)).forEach(e => allEmails.add(e));
      }
      v.member_count = allEmails.size;
      v.resolved_emails = [...allEmails];
    }));
    res.json({ verteiler: rows });
  } catch (err) {
    res.status(500).json({ error: 'Fehler beim Laden der Verteiler' });
  }
});

// Get single Verteiler
// GET /api/verteiler/mailcow-gate — Config fuer das rspamd-Pull-Script auf CT 240.
// MUSS vor '/api/verteiler/:id' stehen, sonst matcht :id="mailcow-gate" (→ 401).
// Liefert gated Aliase (external_allowed=false) + erlaubte Absender (alle Mailcow-Domains
// + aktive Verwaltungs-Domains als Domains, Objektverwaltung als Einzel-Adressen).
app.get('/api/verteiler/mailcow-gate', requireTrackerSecret, async (req, res) => {
  try {
    const { rows } = await pool.query(
      `SELECT email_address FROM email_verteiler WHERE active = true AND external_allowed = false`
    );
    const gated_aliases = rows
      .map(r => String(r.email_address || '').toLowerCase())
      .filter(a => a.endsWith(`@${VERTEILER_DOMAIN}`));
    let mailcowDomains = [];
    try {
      const d = await mailcowApi('GET', '/get/domain/all');
      mailcowDomains = (Array.isArray(d) ? d : [])
        .map(x => String(x.domain_name || x.domain || '').toLowerCase()).filter(Boolean);
    } catch (e) { console.warn('[mailcow-gate] domain/all:', e.message); }
    const vq = await pool.query(
      `SELECT DISTINCT LOWER(SPLIT_PART(addr, '@', 2)) AS domain FROM (
         SELECT v.email AS addr FROM verwaltungen v
          WHERE v.aktiv = true AND (v.vertrag_von IS NULL OR v.vertrag_von <= CURRENT_DATE)
            AND (v.vertrag_bis IS NULL OR v.vertrag_bis >= CURRENT_DATE) AND v.email IS NOT NULL AND v.email <> ''
         UNION ALL
         SELECT k.email AS addr FROM verwaltungs_kontakte k JOIN verwaltungen v ON v.id = k.verwaltung_id
          WHERE v.aktiv = true AND (v.vertrag_von IS NULL OR v.vertrag_von <= CURRENT_DATE)
            AND (v.vertrag_bis IS NULL OR v.vertrag_bis >= CURRENT_DATE) AND k.email IS NOT NULL AND k.email <> ''
       ) s WHERE addr LIKE '%@%'`
    );
    const verwaltungDomains = vq.rows.map(r => r.domain).filter(Boolean);
    const allowed_domains = [...new Set([...mailcowDomains, ...verwaltungDomains])].sort();
    const eq = await pool.query(
      `SELECT DISTINCT LOWER(email) AS email FROM (
         SELECT email FROM personen WHERE email IS NOT NULL AND email <> ''
         UNION ALL
         SELECT email FROM wohnungen_kontakte WHERE email IS NOT NULL AND email <> ''
       ) s WHERE email LIKE '%@%'`
    );
    const allowed_emails = eq.rows.map(r => r.email).filter(Boolean).sort();
    res.json({ gated_aliases: gated_aliases.sort(), allowed_domains, allowed_emails, generated_at: new Date().toISOString() });
  } catch (err) {
    console.error('[mailcow-gate]', err.message);
    res.status(500).json({ error: 'Fehler' });
  }
});

