// mosquitto lehnt Usernames mit +/# ("dangerous username", MQTT-Wildcards) ab und
// macht dann KEINEN ACL-Check. E-Mails koennen +-Adressierung haben -> sicheren
// MQTT-Username ableiten. Die echte E-Mail bleibt im Token (fuer den Zaehler-Check).
function mqttSafeUsername(email) {
  return String(email || '').toLowerCase().replace(/[+#]/g, '_');
}

// go-auth kann keine Custom-Header senden -> Shared-Secret als URI-Query ?k=
function mqttBrokerGuard(req, res, next) {
  if (!MQTT_AUTH_SECRET || req.query.k !== MQTT_AUTH_SECRET) return res.status(403).end();
  next();
}
async function mqttUserByUsername(username) {
  const r = await pool.query(
    `SELECT email, groups_json, is_technik FROM mqtt_tokens
       WHERE username = $1 AND expires_at > NOW()
       ORDER BY expires_at DESC LIMIT 1`,
    [String(username || '')]
  );
  return r.rows[0] || null;
}

// Web-Interface holt sich ein kurzlebiges MQTT-Token (12h). username = sicher.
app.post('/api/mqtt/token', authMiddleware, async (req, res) => {
  try {
    const groups = req.user.groups || [];
    const isTech = !!req.user.isAdmin || isTechnik(groups);
    const email = String(req.user.email).toLowerCase();
    const username = mqttSafeUsername(email);
    const token = 'rwmqtt_' + crypto.randomBytes(24).toString('hex');
    const hash = crypto.createHash('sha256').update(token).digest('hex');
    await pool.query(
      `INSERT INTO mqtt_tokens (token_hash, username, email, groups_json, is_technik, expires_at)
         VALUES ($1, $2, $3, $4, $5, NOW() + interval '12 hours')`,
      [hash, username, email, JSON.stringify(groups), isTech]
    );
    pool.query(`DELETE FROM mqtt_tokens WHERE expires_at < NOW()`).catch(() => {});
    res.json({ username, password: token, is_technik: isTech, prefix: 'energy' });
  } catch (err) {
    console.error('[mqtt] token error:', err.message);
    res.status(500).json({ error: 'Token-Fehler' });
  }
});

// mosquitto-go-auth getuser: Token gegen mqtt_tokens pruefen (200=ok / 403=nein).
// Service-User-Lookup + MQTT-Topic-Match (filter mit +/# vs topic).
async function mqttServiceUserByUsername(username) {
  const r = await pool.query(
    `SELECT username, password_hash, can_write, topic_filter FROM mqtt_service_users WHERE username = $1`,
    [String(username || '')]);
  return r.rows[0] || null;
}
function mqttTopicMatch(filter, topic) {
  const f = String(filter || '').split('/'), t = String(topic || '').split('/');
  for (let i = 0; i < f.length; i++) {
    if (f[i] === '#') return true;        // matcht Rest inkl. Parent-Level
    if (i >= t.length) return false;
    if (f[i] === '+') continue;           // matcht genau ein Level
    if (f[i] !== t[i]) return false;
  }
  return f.length === t.length;
}

// ACL mit mehreren Patterns (Komma-getrennt) + Deny-Patterns ("!pattern", z.B. Datenschutz:
// Indoor-Topics vom oeffentlichen Read-User ausschliessen). Rueckwaerts-kompatibel:
// ein einzelnes Pattern verhaelt sich exakt wie mqttTopicMatch.
function mqttAclAllows(filter, topic) {
  const parts = String(filter || '').split(',').map(s => s.trim()).filter(Boolean);
  let allowed = false;
  for (const p of parts) {
    if (p[0] === '!') { if (mqttTopicMatch(p.slice(1), topic)) return false; } // Deny gewinnt
    else if (mqttTopicMatch(p, topic)) allowed = true;
  }
  return allowed;
}

// ── Messenger (chat.rosenweg4303.ch) MQTT-Auth — ADDITIV zur Energie-Auth ──
// Der Messenger stellt per-User HS256-JWTs aus (message-store signiert mit
// MQTT_JWT_SECRET). Leitet der zentrale CT105-Broker einen Connect/ACL hierher,
// erkennen wir diese JWTs (username/password = das JWT) und autorisieren anhand
// der sub_topics/pub_topics-Claims. Die Energie-Auth darunter bleibt unverändert
// — Messenger-JWTs greifen nur vorher kurz.
const MSG_MQTT_JWT_SECRET = process.env.MQTT_JWT_SECRET || '';
function messengerJwtClaims(token) {
  try {
    if (!MSG_MQTT_JWT_SECRET || typeof token !== 'string') return null;
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    const expected = crypto.createHmac('sha256', MSG_MQTT_JWT_SECRET).update(parts[0] + '.' + parts[1]).digest('base64url');
    const sig = Buffer.from(parts[2]); const exp = Buffer.from(expected);
    if (sig.length !== exp.length || !crypto.timingSafeEqual(sig, exp)) return null;
    const claims = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
    if (claims.exp && Date.now() / 1000 > claims.exp) return null;
    return claims;
  } catch { return null; }
}
function msgTopicAllowed(prefixes, topic) {
  if (!Array.isArray(prefixes)) return false;
  const t = String(topic || '');
  return prefixes.some((p) => p === '#' || t === p || t === p + '/msg' || t.startsWith(p + '/'));
}

app.post('/api/mqtt/getuser', mqttBrokerGuard, async (req, res) => {
  try {
    const { username, password } = req.body || {};
    // Messenger-JWT (chat.) → gültige Signatur genügt.
    if (messengerJwtClaims(username) || messengerJwtClaims(password)) return res.status(200).end();
    if (!password) return res.status(403).end();
    const hash = crypto.createHash('sha256').update(password).digest('hex');
    const r = await pool.query(
      `SELECT 1 FROM mqtt_tokens WHERE token_hash = $1 AND username = $2 AND expires_at > NOW()`,
      [hash, String(username || '')]
    );
    if (r.rows.length) return res.status(200).end();
    // Service-User (persistentes Passwort, nur im Broker)
    const s = await mqttServiceUserByUsername(username);
    if (s && s.password_hash === hash) return res.status(200).end();
    return res.status(403).end();
  } catch (err) { console.error('[mqtt] getuser:', err.message); return res.status(500).end(); }
});

// superuser: technik darf alles.
app.post('/api/mqtt/superuser', mqttBrokerGuard, async (req, res) => {
  try {
    const { username, password } = req.body || {};
    // Messenger: nur das Backend-Token (backend:true) ist Superuser; per-User nein.
    const mj = messengerJwtClaims(username) || messengerJwtClaims(password);
    if (mj) return res.status(mj.backend === true ? 200 : 403).end();
    const u = await mqttUserByUsername(username);
    return res.status(u && u.is_technik ? 200 : 403).end();
  } catch (err) { console.error('[mqtt] superuser:', err.message); return res.status(500).end(); }
});

// aclcheck: Menschen nur lesen; Topic energy/<haus>/<bereich> -> Zaehler
// <haus>-<bereich>, gegen die Collector-Zugriffsliste (echte E-Mail) pruefen.
app.post('/api/mqtt/aclcheck', mqttBrokerGuard, async (req, res) => {
  try {
    const { username, password, topic, acc } = req.body || {};
    // Messenger-JWT → Topic gegen sub_topics/pub_topics-Claims (acc 1/4=read/sub,
    // 2=write, 3=readwrite). Backend-Token darf alles.
    const mj = messengerJwtClaims(username) || messengerJwtClaims(password);
    if (mj) {
      if (mj.backend === true) return res.status(200).end();
      const a = Number(acc);
      let ok;
      if (a === 2) ok = msgTopicAllowed(mj.pub_topics, topic);
      else if (a === 3) ok = msgTopicAllowed(mj.pub_topics, topic) && msgTopicAllowed(mj.sub_topics, topic);
      else ok = msgTopicAllowed(mj.sub_topics, topic);
      return res.status(ok ? 200 : 403).end();
    }
    // Service-User (nur Broker, technische Anwendungen): ACL = topic_filter + can_write
    const svc = await mqttServiceUserByUsername(username);
    if (svc) {
      if (Number(acc) === 2 && !svc.can_write) return res.status(403).end();
      return res.status(mqttAclAllows(svc.topic_filter, topic) ? 200 : 403).end();
    }
    const u = await mqttUserByUsername(username);
    if (!u) return res.status(403).end();
    if (u.is_technik) return res.status(200).end();             // technik sieht/schreibt alles
    const write = Number(acc) === 2;
    const groups = (() => { try { return JSON.parse(u.groups_json || '[]'); } catch { return []; } })();
    const groupsLc = groups.map(g => String(g).toLowerCase());
    // 1. Generische Topic-Regeln (beliebige Topics, Gruppen-basiert, Read/Write).
    const rules = (await pool.query('SELECT topic_filter, group_name, can_read, can_write FROM mqtt_topic_rules')).rows;
    for (const rule of rules) {
      if (!groupsLc.includes(String(rule.group_name).toLowerCase())) continue;
      if (!mqttTopicMatch(rule.topic_filter, topic)) continue;
      if (write ? rule.can_write : rule.can_read) return res.status(200).end();
    }
    // 2. energy/-Zaehler: Menschen nur LESEN (ueber meter_groups/meter_users).
    if (write) return res.status(403).end();                    // Schreiben nur per Topic-Regel oder Service-User
    if (topic === 'energy/collector/status') return res.status(200).end();
    const m = /^energy\/([^/]+)\/([^/]+)/.exec(String(topic || ''));
    if (!m) return res.status(403).end();
    const meterId = `${m[1]}-${m[2]}`;
    const url = `${ENERGY_COLLECTOR_URL}/api/energy/user/${encodeURIComponent(u.email)}/meters?groups=${encodeURIComponent(groups.join(','))}`;
    const resp = await fetch(url, { signal: AbortSignal.timeout(5000) });
    if (!resp.ok) return res.status(403).end();
    const meters = await resp.json();
    const allowed = Array.isArray(meters) && meters.some(x => x.id === meterId);
    return res.status(allowed ? 200 : 403).end();
  } catch (err) { console.error('[mqtt] aclcheck:', err.message); return res.status(500).end(); }
});

// ─── MQTT-Verwaltung + Publish (Technik) fuer die Web-UI ────────────
function requireMqttTechnik(req, res, next) {
  const groups = req.user?.groups || [];
  if (req.user?.isAdmin || groups.some(g => String(g).toLowerCase() === 'technik')) return next();
  return res.status(403).json({ error: 'Nur fuer Technik' });
}

// Lazy MQTT-Write-Client (Broker-User 'collector', darf energy/# schreiben).
let _apiMqttClient = null;
function apiMqttPublishClient() {
  if (_apiMqttClient) return _apiMqttClient;
  const url = process.env.MQTT_URL;
  if (!url) return null;
  const mqttLib = require('mqtt');
  _apiMqttClient = mqttLib.connect(url, {
    username: process.env.MQTT_USER || 'collector',
    password: process.env.MQTT_PASS || '',
    reconnectPeriod: 5000,
    clientId: 'rwapi_pub_' + crypto.randomBytes(4).toString('hex'),
  });
  _apiMqttClient.on('error', (e) => console.error('[mqtt-pub]', e.message));
  return _apiMqttClient;
}

