// Edit (To/CC/Subject/Body) — nur solange pending.
// C2-Fix: Bei jeder inhaltlichen Änderung werden alle bisherigen Approvals
// invalidiert, damit das 4-Augen-Prinzip nicht durch nachtraegliches Editieren
// umgangen werden kann.
app.put('/api/verwaltung-mail-queue/:id', authMiddleware, requireTechnikOrPraesident, async (req, res) => {
  const client = await pool.connect();
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isFinite(id)) return res.status(400).json({ error: 'Ungueltige ID' });
    await client.query('BEGIN');
    const cur = await client.query('SELECT * FROM verwaltung_mail_queue WHERE id = $1 FOR UPDATE', [id]);
    if (cur.rows.length === 0) {
      await client.query('ROLLBACK');
      return res.status(404).json({ error: 'Nicht gefunden' });
    }
    const row = cur.rows[0];
    if (row.status !== 'pending') {
      await client.query('ROLLBACK');
      return res.status(409).json({ error: `Editieren nur bei Status 'pending' möglich (aktuell: ${row.status})` });
    }
    // Beim ersten Edit Original-Snapshot speichern
    let snapshot = row.original_snapshot;
    if (!snapshot) {
      snapshot = {
        mail_to: row.mail_to, mail_cc: row.mail_cc, mail_reply_to: row.mail_reply_to,
        subject: row.subject, body_text: row.body_text,
      };
    }
    const b = req.body || {};
    const updates = [];
    const params = [];
    const push = (col, val) => { params.push(val); updates.push(`${col} = $${params.length}`); };
    // Prüfen ob inhaltliche Änderung vorliegt (für Approval-Reset)
    let contentChanged = false;
    const isDifferent = (a, b) => (a == null ? '' : String(a)) !== (b == null ? '' : String(b));
    if (b.mail_to !== undefined) {
      const v = String(b.mail_to).slice(0, 2000);
      if (isDifferent(v, row.mail_to)) contentChanged = true;
      push('mail_to', v);
    }
    if (b.mail_cc !== undefined) {
      const v = b.mail_cc ? String(b.mail_cc).slice(0, 2000) : null;
      if (isDifferent(v, row.mail_cc)) contentChanged = true;
      push('mail_cc', v);
    }
    if (b.mail_reply_to !== undefined) {
      const v = b.mail_reply_to ? String(b.mail_reply_to).slice(0, 255) : null;
      if (isDifferent(v, row.mail_reply_to)) contentChanged = true;
      push('mail_reply_to', v);
    }
    if (b.subject !== undefined) {
      const v = String(b.subject).slice(0, 500);
      if (isDifferent(v, row.subject)) contentChanged = true;
      push('subject', v);
    }
    if (b.body_text !== undefined) {
      const v = String(b.body_text).slice(0, 100000);
      if (isDifferent(v, row.body_text)) contentChanged = true;
      push('body_text', v);
    }
    if (updates.length === 0) {
      await client.query('ROLLBACK');
      return res.status(400).json({ error: 'Keine Änderungen' });
    }
    push('original_snapshot', JSON.stringify(snapshot));
    push('edited_by', req.user.email);
    push('edited_at', new Date());
    params.push(id);
    const r = await client.query(
      `UPDATE verwaltung_mail_queue SET ${updates.join(', ')} WHERE id = $${params.length} RETURNING *`,
      params,
    );
    let invalidatedApprovals = 0;
    if (contentChanged) {
      const del = await client.query('DELETE FROM mail_approval_log WHERE queue_id = $1 RETURNING id', [id]);
      invalidatedApprovals = del.rowCount;
    }
    await client.query('COMMIT');
    res.json({ ...r.rows[0], _invalidated_approvals: invalidatedApprovals });
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    console.error('Mail-Queue edit error:', err);
    res.status(500).json({ error: 'Fehler beim Speichern' });
  } finally {
    client.release();
  }
});

// Freigeben (Multi-Approver-fähig). Bei 4-Augen-Prinzip braucht's
// >= min_approvers verschiedene User aus required_groups. Erst dann Versand.
// H3-Fix: Race-Safe durch SELECT ... FOR UPDATE auf queue-Row im selben
// Transaktionsblock. Status-Wechsel auf 'freigegeben' atomar mit COUNT.
app.post('/api/verwaltung-mail-queue/:id/freigeben', authMiddleware, async (req, res) => {
  const client = await pool.connect();
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isFinite(id)) return res.status(400).json({ error: 'Ungueltige ID' });
    await client.query('BEGIN');
    // Lock die queue-Row → andere parallele Freigaben warten
    const cur = await client.query('SELECT * FROM verwaltung_mail_queue WHERE id = $1 FOR UPDATE', [id]);
    if (cur.rows.length === 0) { await client.query('ROLLBACK'); return res.status(404).json({ error: 'Nicht gefunden' }); }
    if (cur.rows[0].status !== 'pending') {
      await client.query('ROLLBACK');
      return res.status(409).json({ error: `Status ist '${cur.rows[0].status}', erwartet 'pending'` });
    }
    const rule = await getApprovalRuleForQueueItem(cur.rows[0]);
    if (!userHasAnyGroup(req.user, rule.required_groups)) {
      await client.query('ROLLBACK');
      return res.status(403).json({ error: `Freigabe erfordert eine der Gruppen: ${rule.required_groups}` });
    }
    // Approval logen (UNIQUE constraint verhindert Doppel-Freigabe vom gleichen User)
    try {
      await client.query(
        `INSERT INTO mail_approval_log (queue_id, approver_email) VALUES ($1, $2)`,
        [id, req.user.email],
      );
    } catch (e) {
      await client.query('ROLLBACK');
      if (String(e.code) === '23505') {
        return res.status(409).json({ error: 'Du hast bereits freigegeben — für ' + rule.min_approvers + '-Augen-Prinzip braucht es weitere Approver' });
      }
      throw e;
    }
    const cnt = await client.query('SELECT COUNT(*) AS n FROM mail_approval_log WHERE queue_id = $1', [id]);
    const approvalsSoFar = parseInt(cnt.rows[0].n, 10);
    if (approvalsSoFar < rule.min_approvers) {
      await client.query('COMMIT');
      return res.json({
        success: true, sent: false, awaiting_more_approvers: true,
        approvals: approvalsSoFar, required: rule.min_approvers,
        required_groups: rule.required_groups,
      });
    }
    // Genug Approver → status freigegeben innerhalb der Transaktion (atomic mit COUNT)
    await client.query(
      `UPDATE verwaltung_mail_queue SET status = 'freigegeben', freigegeben_von = $1, freigegeben_am = NOW() WHERE id = $2`,
      [req.user.email, id],
    );
    await client.query('COMMIT');
    // Mail-Versand erst NACH COMMIT (sendVerwaltungMailFromQueue nutzt eigene Connection)
    try {
      await sendVerwaltungMailFromQueue(id, req.user.email);
      res.json({ success: true, sent: true, approvals: approvalsSoFar, required: rule.min_approvers });
    } catch (sendErr) {
      console.error(`[mail-queue ${id}] Send error:`, sendErr);
      res.status(500).json({ success: false, error: 'Freigegeben, aber Versand schlug fehl: ' + sendErr.message });
    }
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    console.error('Mail-Queue freigeben error:', err);
    res.status(500).json({ error: err.message });
  } finally {
    client.release();
  }
});

// Ablehnen mit Grund
app.post('/api/verwaltung-mail-queue/:id/ablehnen', authMiddleware, requireTechnikOrPraesident, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isFinite(id)) return res.status(400).json({ error: 'Ungueltige ID' });
    const grund = String(req.body?.grund || '').slice(0, 1000);
    if (!grund.trim()) return res.status(400).json({ error: 'Grund erforderlich' });
    const cur = await pool.query('SELECT status, source_type, source_id, subject FROM verwaltung_mail_queue WHERE id = $1', [id]);
    if (cur.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    if (cur.rows[0].status !== 'pending') {
      return res.status(409).json({ error: `Status ist '${cur.rows[0].status}', erwartet 'pending'` });
    }
    await pool.query(
      `UPDATE verwaltung_mail_queue
          SET status = 'abgelehnt', abgelehnt_von = $1, abgelehnt_am = NOW(), abgelehnt_grund = $2
        WHERE id = $3`,
      [req.user.email, grund, id],
    );
    // Optional: bei source=auslage-auszahlung den Ausschuss informieren damit die Auslage neu bewertet werden kann
    try {
      const row = cur.rows[0];
      if (row.source_type.startsWith('auslage-auszahlung') && row.source_id) {
        const aR = await pool.query('SELECT user_email, user_name, bearbeitet_von FROM auslagen WHERE id = $1', [row.source_id]);
        if (aR.rows.length > 0) {
          const a = aR.rows[0];
          const cc = [a.user_email, a.bearbeitet_von].filter(v => v).join(', ');
          await sendTemplated('verwaltung-mail-abgelehnt', {
            abgelehnt_von: req.user.email, grund,
            betreff_kurz: row.subject.slice(0, 80), site_url: SITE_URL,
          }, {
            from: MAIL_FROM,
            to: a.bearbeitet_von || a.user_email,
            cc,
            subject: `Auszahlungs-Mail abgelehnt: ${row.subject.slice(0, 80)}`,
            text:
              `Die Auszahlungs-Mail an die Verwaltung wurde von ${req.user.email} abgelehnt.\n\n`
              + `Grund: ${grund}\n\n`
              + `Auslage: ${SITE_URL}/auslagen.html\n`
              + `Mail-Queue: ${SITE_URL}/verwaltung-mail-outbox.html`,
          });
          // WhatsApp an Eigentümer + Freigeber
          pushWhatsappBroadcast({
            emails: [a.user_email, a.bearbeitet_von].filter(v => v),
            sourceType: 'verwaltung-mail-abgelehnt', sourceId: row.source_id,
            body: `❌ *Auszahlungs-Mail abgelehnt* von ${req.user.email}\nAuslage: ${row.subject.slice(0, 80)}\n\n_Grund:_ ${grund}\n\n${SITE_URL}/auslagen.html`,
          }).catch(() => {});
        }
      }
    } catch (mailErr) {
      console.warn('[mail-queue] Ablehn-Notification fehlgeschlagen:', mailErr.message);
    }
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Attachment-Download zur Vorschau
app.get('/api/verwaltung-mail-queue/:id/attachment/:idx', authMiddleware, requireTechnikOrPraesident, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const idx = parseInt(req.params.idx, 10);
    if (!Number.isFinite(id) || !Number.isFinite(idx)) return res.status(400).end();
    // M7: separate Attachments-Tabelle, mit Fallback auf Legacy-JSONB
    let att = null;
    const sep = await pool.query(
      `SELECT filename, docs_path, content_base64 FROM verwaltung_mail_attachments
        WHERE queue_id = $1 ORDER BY sort_order, id OFFSET $2 LIMIT 1`,
      [id, idx],
    );
    if (sep.rows.length > 0) {
      att = sep.rows[0];
    } else {
      const r = await pool.query('SELECT attachments FROM verwaltung_mail_queue WHERE id = $1', [id]);
      if (r.rows.length === 0) return res.status(404).end();
      att = (r.rows[0].attachments || [])[idx];
    }
    if (!att) return res.status(404).end();
    // L4-Bonus: Safe filename + Null-Byte-Filter
    const safeFilename = (att.filename || 'beleg').replace(/[^A-Za-z0-9._-]/g, '_').replace(/\.+/g, '.').slice(0, 200) || 'beleg';
    res.setHeader('Content-Disposition', `inline; filename="${safeFilename}"`);
    if (att.content_base64) {
      res.send(Buffer.from(att.content_base64, 'base64'));
      return;
    }
    if (att.docs_path) {
      const full = pathModule.join(DOCS_PATH, att.docs_path);
      if (!full.startsWith(pathModule.resolve(DOCS_PATH) + '/')) return res.status(400).end();
      return res.sendFile(full, (err) => { if (err && !res.headersSent) res.status(404).end(); });
    }
    res.status(404).end();
  } catch (err) {
    res.status(500).end();
  }
});

// ─── PBX / Voicemail Integration ─────────────────────────────────────
// Asterisk-AGI laedt aufgenommene Voicemails hier hoch. Wir transkribieren
// via OpenRouter (Whisper-1), erstellen mit Claude eine kurze Zusammenfassung
// und mailen Audio + Transkript + Summary an Technik+Präsident.
//
// Authentifizierung: gleiches Pattern wie WhatsApp-Bot — Shared-Secret im
// X-PBX-Secret-Header, der mit PBX_SHARED_SECRET env var matched.

const PBX_SHARED_SECRET = process.env.PBX_SHARED_SECRET || '';

function requirePbxSecret(req, res, next) {
  if (!PBX_SHARED_SECRET) return res.status(503).json({ error: 'PBX_SHARED_SECRET nicht konfiguriert' });
  const provided = req.headers['x-pbx-secret'];
  if (provided !== PBX_SHARED_SECRET) return res.status(401).json({ error: 'Unauthorized' });
  next();
}

async function transcribeWhisper(audioBuf, mimeType = 'audio/wav') {
  // OpenRouter unterstuetzt Whisper-large-v3 über den /audio/transcriptions endpoint.
  // Falls OPENROUTER_API_KEY fehlt → leerer Transkript als Fallback.
  const apiKey = process.env.OPENROUTER_API_KEY;
  if (!apiKey) return { text: '', error: 'OPENROUTER_API_KEY nicht gesetzt' };
  // OpenRouter's audio-transcriptions endpoint rejects undici-FormData boundary.
  // Workaround: nutze direkt OpenAI-Whisper kompatible Groq-API (kostenlos,
  // schneller, whisper-large-v3). Wenn GROQ_API_KEY fehlt → leerer Transkript.
  const groqKey = process.env.GROQ_API_KEY;
  const endpoint = groqKey
    ? { url: 'https://api.groq.com/openai/v1/audio/transcriptions', key: groqKey, model: 'whisper-large-v3' }
    : { url: 'https://openrouter.ai/api/v1/audio/transcriptions', key: apiKey, model: 'openai/whisper-1' };
  const form = new FormData();
  form.append('file', new Blob([audioBuf], { type: mimeType }), 'voicemail.wav');
  form.append('model', endpoint.model);
  form.append('language', 'de');
  try {
    const r = await fetch(endpoint.url, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${endpoint.key}`,
        // OpenRouter verlangt HTTP-Referer/X-Title für Attribution
        ...(endpoint.url.includes('openrouter') ? { 'HTTP-Referer': 'https://www.rosenweg4303.ch', 'X-Title': 'Rosenweg PBX' } : {}),
      },
      body: form,
    });
    if (!r.ok) return { text: '', error: `Whisper ${r.status}: ${await r.text().catch(() => '')}` };
    const data = await r.json();
    return { text: data.text || '', error: null };
  } catch (e) { return { text: '', error: e.message }; }
}

// Formatiert eine Verteiler-Email für WhatsApp-Gruppen-Mirror:
// - kompakter Titel (Subject)
// - 2-4 Bullet-Points mit Kernaussage
// - Action-Items wenn erkennbar
// - WhatsApp-Markdown (*fett* _kursiv_)
// Fallback: gestripptes Plain-Text wenn OpenRouter nicht verfuegbar
async function reformatEmailForWhatsapp({ subject, senderName, body, attachmentCount }) {
  const fallback = () => {
    const clipped = (body || '').slice(0, 1200);
    const attHint = attachmentCount > 0 ? `\n\n📎 ${attachmentCount} Anhang${attachmentCount > 1 ? 'e' : ''} per Email.` : '';
    return `📧 *${subject}*\nvon: ${senderName}\n\n${clipped}${attHint}`;
  };
  const apiKey = process.env.OPENROUTER_API_KEY;
  if (!apiKey || !body) return fallback();
  try {
    const r = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'anthropic/claude-haiku-4.5',
        max_tokens: 1400,
        messages: [
          {
            role: 'system',
            content: `Du formatierst Emails für einen WhatsApp-Gruppen-Mirror der Rosenweg-STWEG.
Liefere eine WhatsApp-gerechte, AUSFUEHRLICHE Zusammenfassung in genau diesem Format:
📧 *<Titel mit max 70 Zeichen, evtl. gekuerzt>*
_von: <Absender>_

📝 *Worum geht's:*
<2-3 Sätze Kontext: was ist der Anlass, wer ist betroffen, worauf bezieht sich die Mail>

🔑 *Die wichtigsten Punkte:*
• <Bullet 1 — konkret, mit Zahlen/Daten/Namen wenn vorhanden, max 180 Zeichen>
• <Bullet 2>
• <Bullet 3>
• <weitere Bullets nach Bedarf, insgesamt 4-8 Stück>

<Wenn Termine/Fristen erwaehnt: 📅 *Termine:* <Auflistung Datum/Frist>>
<Wenn Geldbetraege erwaehnt: 💰 *Betraege:* <Liste mit Posten + CHF>>
<Wenn klare Aktion verlangt: 👉 *Was ist zu tun:* <konkret, 1-2 Sätze, wer/was/wann>>

Regeln:
- WhatsApp-Markdown (*fett*, _kursiv_, kein Markdown-#)
- Maximal 3500 Zeichen Total — lieber ausführlich als zu knapp
- Alle inhaltlich relevanten Details aus der Mail übernehmen (Zahlen, Daten, Namen, Beschlüsse, Begründungen)
- Keine Floskeln, keine Gruessformeln, keine Signatur, keine Footer/Disclaimer, keine HTML-Reste
- Bei laengeren Mails: lieber 6-8 Bullets als alles in 3 zu quetschen
- Auf Deutsch (Schweizer Hochdeutsch, kein ß)`,
          },
          {
            role: 'user',
            content: `Absender: ${senderName}\nSubject: ${subject}\nAnhaenge: ${attachmentCount}\n\nEmail-Body:\n${body.slice(0, 8000)}`,
          },
        ],
      }),
      signal: AbortSignal.timeout(15000),
    });
    if (!r.ok) return fallback();
    const data = await r.json();
    const txt = data.choices?.[0]?.message?.content?.trim();
    if (!txt || txt.length < 20) return fallback();
    // Anhang-Hint anhängen falls nicht schon drin
    if (attachmentCount > 0 && !/📎/.test(txt)) {
      return txt + `\n\n📎 ${attachmentCount} Anhang${attachmentCount > 1 ? 'e' : ''} per Email.`;
    }
    return txt;
  } catch (err) {
    console.warn('[Verteiler-AI] Reformat fehlgeschlagen:', err.message);
    return fallback();
  }
}

// Analysiert eine Voicemail-Transkription: Zusammenfassung + Defekt-Klassifikation
async function analyzeVoicemail(transcript, callerId) {
  const apiKey = process.env.OPENROUTER_API_KEY;
  const empty = { summary: '', urgency: null, action: '', is_defekt: false, defekt_stweg: null, defekt_beschreibung: '' };
  if (!apiKey || !transcript) return empty;
  try {
    const r = await fetch('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: 'anthropic/claude-haiku-4.5',
        max_tokens: 500,
        response_format: { type: 'json_object' },
        messages: [
          {
            role: 'system',
            content: `Du analysierst Anrufbeantworter-Nachrichten der Rosenweg-STWEG (Schweizer Stockwerkeigentum, 8 STWEGs, Hausnummern 1/2/4/5/6/8/9/10/12/13/14/16/17/18). Antworte STRIKT als JSON mit folgenden Feldern:
{
  "summary": string,              // 1-2 Sätze Kern-Anliegen, knapp, ohne Floskeln
  "urgency": "niedrig" | "mittel" | "hoch",
  "action": string,               // 1 Satz vorgeschlagene nächste Handlung
  "is_defekt": boolean,           // true wenn ein Schaden/Defekt/Reparaturbedarf gemeldet wird
  "defekt_stweg": number | null,  // STWEG-Nummer 1-8 (wenn ein Haus oder eine Hausnummer genannt wird), sonst null
  "defekt_beschreibung": string   // saubere Defektbeschreibung (1-3 Sätze) falls is_defekt, sonst ""
}
STWEG-Mapping: Rosenweg 17/18 = STWEG 1, RW13/14/16 = STWEG 2, RW9/10/12 = STWEG 3, RW5/6/8 = STWEG 4, RW1/2/4 = STWEG 5, ...`,
          },
          { role: 'user', content: `Anrufer: ${callerId}\nTranskript:\n${transcript}` },
        ],
      }),
    });
    if (!r.ok) return empty;
    const data = await r.json();
    const raw = data.choices?.[0]?.message?.content || '{}';
    try {
      const j = JSON.parse(raw);
      return {
        summary: j.summary || '',
        urgency: j.urgency || null,
        action: j.action || '',
        is_defekt: !!j.is_defekt,
        defekt_stweg: Number.isInteger(j.defekt_stweg) && j.defekt_stweg >= 1 && j.defekt_stweg <= 8 ? j.defekt_stweg : null,
        defekt_beschreibung: j.defekt_beschreibung || '',
      };
    } catch { return empty; }
  } catch { return empty; }
}

// resolveTechnikWhatsappGroupId -> lib/whatsapp.js

app.post('/api/pbx/voicemail', requirePbxSecret, async (req, res) => {
  try {
    const audioBuf = req.body;
    if (!Buffer.isBuffer(audioBuf) || audioBuf.length < 1024) {
      return res.status(400).json({ error: 'Audio-Body fehlt oder zu klein' });
    }
    const callerId = String(req.headers['x-caller-id'] || 'unbekannt').slice(0, 50);
    const uniqueid = String(req.headers['x-unique-id'] || Date.now()).slice(0, 60);
    console.log(`[pbx-voicemail] empfangen: caller=${callerId} uid=${uniqueid} size=${audioBuf.length}`);

    // Transkription + KI-Analyse (Zusammenfassung + Defekt-Klassifikation)
    const { text: transcript, error: whErr } = await transcribeWhisper(audioBuf);
    if (whErr) console.warn('[pbx-voicemail] Whisper-Fehler:', whErr);
    const analysis = await analyzeVoicemail(transcript, callerId);

    // Auto-Reklamation wenn KI einen Defekt erkennt
    let reklamationId = null;
    if (analysis.is_defekt && analysis.defekt_beschreibung) {
      try {
        // Anrufer-Person via Telefon-Nummer matchen (normalisiert)
        const normCaller = normalizePhone(callerId);
        let personId = null;
        if (normCaller) {
          const pr = await pool.query(
            `SELECT id FROM personen
              WHERE telefon = $1
                 OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(telefone,'[]'::jsonb)) t WHERE t = $1)
              LIMIT 1`,
            [normCaller],
          );
          if (pr.rows[0]) personId = pr.rows[0].id;
        }
        const ins = await pool.query(
          `INSERT INTO reklamationen (person_id, stweg, beschreibung, eingang_kanal)
           VALUES ($1, $2, $3, 'pbx-voicemail') RETURNING id`,
          [personId, analysis.defekt_stweg, analysis.defekt_beschreibung.slice(0, 2000)],
        );
        reklamationId = ins.rows[0].id;
        console.log(`[pbx-voicemail] Reklamation #${reklamationId} auto-erstellt (stweg=${analysis.defekt_stweg}, person=${personId})`);
      } catch (rekErr) {
        console.warn('[pbx-voicemail] Auto-Reklamation Fehler:', rekErr.message);
      }
    }

    // WhatsApp-Group "Rosenweg Technik": Audio + Transkript + Zusammenfassung + ggf. Reklamation-Link
    try {
      const groupId = await resolveTechnikWhatsappGroupId();
      if (groupId) {
        const summaryLine = analysis.summary ? `*Zusammenfassung:* ${analysis.summary}` : null;
        const urgLine = analysis.urgency ? `*Dringlichkeit:* ${analysis.urgency}` : null;
        const actLine = analysis.action ? `*Nächster Schritt:* ${analysis.action}` : null;
        const rekLine = reklamationId
          ? `✅ *Auto-Reklamation #${reklamationId} erstellt* (STWEG ${analysis.defekt_stweg || '—'})\n${SITE_URL}/reklamationen.html#${reklamationId}`
          : null;
        const waBody = [
          `📞 *Voicemail* von ${callerId}`,
          `🕒 ${new Date().toLocaleString('de-CH')}`,
          summaryLine,
          urgLine,
          actLine,
          rekLine,
          transcript ? `*Transkript:*\n${transcript}` : null,
        ].filter(Boolean).join('\n\n').slice(0, 3500);
        // 1. Text-Nachricht mit Zusammenfassung + ggf. Reklamation
        await queueWhatsappMessage({
          chatId: groupId,
          phone: groupId,
          body: waBody,
          sourceType: 'pbx-voicemail',
          sourceId: reklamationId || null,
        });
        // 2. Audio als separate Sprachnachricht (Play-Button im WA-UI)
        await queueWhatsappMessage({
          chatId: groupId,
          phone: groupId,
          body: '',
          attachments: [{
            mimetype: 'audio/wav',
            data_base64: audioBuf.toString('base64'),
            filename: `voicemail-${callerId}-${uniqueid}.wav`,
          }],
          sourceType: 'pbx-voicemail',
          sourceId: reklamationId || null,
        });
        console.log(`[pbx-voicemail] WA an Gruppe ${groupId} gequeued`);
      } else {
        console.warn('[pbx-voicemail] WA-Group "Rosenweg Technik" nicht gefunden — Voicemail bleibt in DB');
      }
    } catch (waErr) {
      console.warn('[pbx-voicemail] WA-Send-Fehler:', waErr.message);
    }

    res.json({
      ok: true,
      transcript_len: transcript.length,
      summary_present: !!analysis.summary,
      defekt: analysis.is_defekt,
      reklamation_id: reklamationId,
    });
  } catch (err) {
    console.error('[pbx-voicemail] error:', err);
    res.status(500).json({ error: err.message });
  }
});

// ── Anruf-Meldung OHNE Voicemail ───────────────────────────────────────
// Der Dialplan-Hangup-Handler (pbx_call_notify.py) meldet hierher, wenn ein
// Anruf den Anrufbeantworter erreicht hat, aber KEINE Nachricht hinterlassen
// wurde (Anrufer legte waehrend/nach der Ansage auf). Liefert eine kurze
// Technik-WhatsApp, damit der Anruf trotzdem sichtbar ist.
app.post('/api/pbx/call-notify', requirePbxSecret, async (req, res) => {
  try {
    const callerId = (req.body?.caller || 'Unbekannt').toString();
    const uniqueid = (req.body?.uniqueid || '').toString();
    const reason = (req.body?.reason || 'no-message').toString();
    console.log(`[pbx-call-notify] caller=${callerId} uid=${uniqueid} reason=${reason}`);
    const groupId = await resolveTechnikWhatsappGroupId();
    if (!groupId) {
      console.warn('[pbx-call-notify] WA-Group "Rosenweg Technik" nicht gefunden');
      return res.json({ ok: false, reason: 'no-group' });
    }
    const reasonLine = reason === 'missed'
      ? 'Nicht angenommen'
      : 'Aufgelegt, ohne eine Nachricht zu hinterlassen';
    const waBody = [
      `📞 *Anruf* von ${callerId}`,
      `🕒 ${new Date().toLocaleString('de-CH')}`,
      `ℹ️ ${reasonLine}`,
    ].join('\n');
    await queueWhatsappMessage({ chatId: groupId, phone: groupId, body: waBody, sourceType: 'pbx-call' });
    console.log(`[pbx-call-notify] WA an Gruppe ${groupId} gequeued`);
    res.json({ ok: true });
  } catch (err) {
    console.error('[pbx-call-notify] error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// ── Voicemail-Auto-Reklamation (Webhook von der autarken PBX-API) ──────
// Die PBX-API (CT 220) transkribiert + analysiert die Voicemail selbst und
// ruft hier nur noch fuer die Rosenweg-spezifische Reklamation an (personen-
// Lookup + reklamationen leben in der Haupt-DB). Body: { caller_id, uniqueid,
// transcript, analysis:{ is_defekt, defekt_stweg, defekt_beschreibung, ... } }.
// Liefert { reklamation_id } zurueck, damit die PBX den Link in die WhatsApp setzt.
app.post('/api/pbx/voicemail-reklamation', requirePbxSecret, async (req, res) => {
  try {
    const callerId = String(req.body?.caller_id || 'unbekannt').slice(0, 50);
    const analysis = req.body?.analysis || {};
    if (!analysis.is_defekt || !analysis.defekt_beschreibung) {
      return res.json({ ok: true, reklamation_id: null, reason: 'kein Defekt erkannt' });
    }
    const normCaller = normalizePhone(callerId);
    let personId = null;
    if (normCaller) {
      const pr = await pool.query(
        `SELECT id FROM personen
          WHERE telefon = $1
             OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(telefone,'[]'::jsonb)) t WHERE t = $1)
          LIMIT 1`,
        [normCaller],
      );
      if (pr.rows[0]) personId = pr.rows[0].id;
    }
    const ins = await pool.query(
      `INSERT INTO reklamationen (person_id, stweg, beschreibung, eingang_kanal)
       VALUES ($1, $2, $3, 'pbx-voicemail') RETURNING id`,
      [personId, analysis.defekt_stweg || null, String(analysis.defekt_beschreibung).slice(0, 2000)],
    );
    const reklamationId = ins.rows[0].id;
    console.log(`[pbx-voicemail-reklamation] #${reklamationId} erstellt (stweg=${analysis.defekt_stweg}, person=${personId})`);
    res.json({ ok: true, reklamation_id: reklamationId, person_id: personId });
  } catch (err) {
    console.error('[pbx-voicemail-reklamation] error:', err.message);
    res.status(500).json({ error: err.message });
  }
});

// ── Caller-Name-Lookup (CNAM) fuer eingehende Anrufe ───────────────────
// Die PBX (AGI pbx_cnam.py) fragt hier mit der Anrufer-Nummer an und bekommt
// einen Anzeigenamen: zuerst aus dem Rosenweg-Telefonbuch (personen/handwerker/
// verwaltungen), sonst via search.ch (Schweizer Verzeichnis, SEARCH_CH_API_KEY).
async function searchChReverse(number) {
  const key = process.env.SEARCH_CH_API_KEY;
  if (!key || !number) return null;
  try {
    const r = await fetch(`https://tel.search.ch/api/?key=${encodeURIComponent(key)}&was=${encodeURIComponent(number)}&maxnum=1`,
      { signal: AbortSignal.timeout(5000) });
    if (!r.ok) return null;
    const xml = await r.text();
    const m = xml.match(/<entry>[\s\S]*?<title[^>]*>([^<]+)<\/title>/i);
    return m ? m[1].replace(/\s+/g, ' ').trim() : null;
  } catch { return null; }
}

app.get('/api/pbx/cnam/:number', requirePbxSecret, async (req, res) => {
  try {
    const raw = String(req.params.number || '').trim();
    const norm = normalizePhone(raw);
    const last9 = (norm || raw).replace(/\D/g, '').slice(-9);
    if (last9.length < 6) return res.json({ name: null });

    // 1) Personen (Bewohner/Eigentuemer)
    const person = await findPersonByPhone(raw);
    if (person) {
      const name = [person.vorname, person.nachname].filter(Boolean).join(' ').trim();
      if (name) return res.json({ name, source: 'telefonbuch' });
    }
    // 2) Handwerker + Verwaltungen (Match auf die letzten 9 Ziffern -> robust gg. +41/0)
    const hv = await pool.query(
      `SELECT firma AS name FROM handwerker
         WHERE RIGHT(regexp_replace(COALESCE(telefon,''),'\\D','','g'),9) = $1
            OR RIGHT(regexp_replace(COALESCE(mobile,''),'\\D','','g'),9) = $1
       UNION ALL
       SELECT firma_name AS name FROM verwaltungen
         WHERE RIGHT(regexp_replace(COALESCE(telefon,''),'\\D','','g'),9) = $1
       LIMIT 1`, [last9]);
    if (hv.rows[0]?.name) return res.json({ name: hv.rows[0].name, source: 'telefonbuch' });

    // 3) search.ch
    const sc = await searchChReverse(norm || raw);
    if (sc) return res.json({ name: sc, source: 'search.ch' });

    res.json({ name: null });
  } catch (err) {
    console.error('[pbx-cnam]', err.message);
    res.json({ name: null });
  }
});

