// Bewohner-Uebersicht: Reklamationen der eigenen STWEG(s) + uebergreifende (stweg NULL),
// sanitisiert (KEIN Melder-Name/-Email — Transparenz-Board, kein Datenleck).
app.get('/api/reklamationen/uebersicht', authMiddleware, async (req, res) => {
  try {
    const stwegs = [...getUserStwegs(req.user.groups || [])];
    const params = [];
    let cond = 'r.stweg IS NULL';
    if (stwegs.length) { params.push(stwegs); cond = `(r.stweg = ANY($${params.length}::int[]) OR r.stweg IS NULL)`; }
    const r = await pool.query(
      `SELECT r.id, r.kategorie, r.beschreibung, r.status, r.stweg, r.created_at, r.erledigt_am,
              (r.handwerker_id IS NOT NULL OR r.zugewiesen_an IS NOT NULL) AS in_bearbeitung
         FROM reklamationen r
        WHERE ${cond}
        ORDER BY (r.status IN ('erledigt','abgewiesen')) ASC, r.created_at DESC
        LIMIT 200`,
      params);
    res.json({ reklamationen: r.rows, stwegs });
  } catch (e) { console.error('[reklamationen-uebersicht]', e); res.status(500).json({ error: 'Fehler' }); }
});
const reklaWebRate = new Map(); // key -> [timestamps]
app.post('/api/reklamationen', authMiddleware, async (req, res) => {
  try {
    const email = String(req.user?.email || '').toLowerCase();
    const b = req.body || {};
    const beschreibung = String(b.beschreibung || '').trim().slice(0, 4000);
    if (!beschreibung) return res.status(400).json({ error: 'Beschreibung erforderlich' });
    const kategorie = ['aufzug', 'heizung', 'wasser', 'tuer', 'reinigung', 'licht', 'strom', 'netzwerk', 'salz', 'sonstige'].includes(b.kategorie) ? b.kategorie : 'sonstige';
    const stweg = Number.isFinite(parseInt(b.stweg, 10)) ? parseInt(b.stweg, 10) : null;
    const pr = await pool.query('SELECT id FROM personen WHERE LOWER(email) = $1 LIMIT 1', [email]);
    const personId = pr.rows[0]?.id || null;
    // Rate-Limit: max 5 Meldungen / 10 Min pro Person
    const key = personId || email; const now = Date.now();
    const arr = (reklaWebRate.get(key) || []).filter(t => now - t < 600000);
    if (arr.length >= 5) return res.status(429).json({ error: 'Zu viele Meldungen — bitte später erneut.' });
    arr.push(now); reklaWebRate.set(key, arr);
    // Optionales Foto -> DOCS-Volume
    let bildPfad = null;
    if (b.foto_base64) {
      try {
        const m = String(b.foto_base64).match(/^data:image\/(\w+);base64,(.+)$/s);
        const ext = (m ? m[1] : 'jpg').toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 4) || 'jpg';
        const buf = Buffer.from(m ? m[2] : b.foto_base64, 'base64');
        if (buf.length > 0 && buf.length <= 8 * 1024 * 1024) {
          const folder = stweg ? ('stweg' + stweg) : 'allgemein';
          const dir = pathModule.join(DOCS_PATH, folder, 'reklamationen');
          await fs.mkdir(dir, { recursive: true });
          const fname = `rekl-${Date.now()}-${crypto.randomBytes(4).toString('hex')}.${ext}`;
          await fs.writeFile(pathModule.join(dir, fname), buf);
          bildPfad = pathModule.join(folder, 'reklamationen', fname);
        }
      } catch (e) { console.error('[reklamation-foto]', e.message); }
    }
    const standort = b.standort ? String(b.standort).trim().slice(0, 200) : null;
    const r = await pool.query(
      `INSERT INTO reklamationen (person_id, stweg, kategorie, beschreibung, bild_pfad, standort, eingang_kanal, status)
       VALUES ($1,$2,$3,$4,$5,$6,'web','offen') RETURNING id, kategorie, beschreibung, status, created_at`,
      [personId, stweg, kategorie, beschreibung, bildPfad, standort]);
    logReklEvent(r.rows[0].id, email, 'Erstellt (Web-Formular)' + (standort ? ` · 📍 ${standort}` : '')).catch(() => {});
    autoAssignReklamation(r.rows[0].id).catch((e) => console.warn('[reklamation-auto-assign]', e.message));
    notifyMelderEroeffnet(r.rows[0].id, email, beschreibung).catch((e) => console.warn('[reklamation-eroeffnet-notify]', e.message));
    // Web-Push an die Technik (neue Meldung -> Cockpit)
    getTechnikEmails().then((emails) => webpushLib.sendToEmails(emails, {
      title: 'Neue Reparatur-Meldung', body: `${kategorie}: ${beschreibung.slice(0, 80)}`,
      url: 'https://pwa.rosenweg4303.ch/technik/', tag: `rekl-${r.rows[0].id}`,
    })).catch(() => {});
    // WhatsApp an die Technik-Gruppe (neue Meldung) — die API meldet selbst.
    notifyTechnik(`🔧 *Neue Reparatur-Meldung* #${r.rows[0].id}\nKategorie: ${kategorie}${stweg ? ` · STWEG ${stweg}` : ''}${standort ? `\n📍 ${standort}` : ''}\n${beschreibung.slice(0, 200)}\n\n→ pwa.rosenweg4303.ch/technik/`, 'reklamation-neu').catch(() => {});
    res.json({ ok: true, reklamation: r.rows[0] });
  } catch (e) { console.error('[reklamation-web-post]', e); res.status(500).json({ error: 'Fehler' }); }
});

