// Berechtigungs-Helper: nur technik/praesident sind voll-admin auf ISP.
function ispIsAdmin(req) {
  const g = req.user?.groups || [];
  return isTechnik(g) || isPraesident(g) || req.user?.isAdmin;
}

// Hilfsfunktion: hat user die Wohnung X als Eigentümer/Mieter/Bewohner?
async function userOwnsWohnung(email, wohnungId) {
  if (!email || !wohnungId) return false;
  const r = await pool.query(
    `SELECT 1 FROM wohnungen_kontakte k
       JOIN personen p ON p.id = k.person_id
      WHERE k.wohnung_id = $1 AND LOWER(p.email) = LOWER($2)
        AND k.archiviert_am IS NULL LIMIT 1`,
    [wohnungId, email],
  );
  return r.rows.length > 0;
}

// === Hostname-Auto-Approval-Logik ===
// Hostnames die wie Rosenweg-Eigene aussehen brauchen Admin-Prüfung,
// damit niemand z.B. 'rosenweg4303.com' oder 'r12.rosenweg.ch' anlegt
// und damit Bewohner faked.
function hostNeedsAdminApproval(hostname) {
  const h = (hostname || '').toLowerCase();
  if (h.includes('rosenweg')) return 'enthaelt "rosenweg"';
  // r-prefix: rNN. (wie r9., r17., ...) wäre Verwechslung mit STWEG-Konvention
  if (/^r\d+\./.test(h)) return 'r<Nummer>. Pattern reserviert (Hausnummern)';
  if (h.endsWith('.rosenweg4303.ch') || h.endsWith('.rosenweg9.ch')) return 'unsere Domain';
  return null;
}

function ispResolveTarget() {
  return {
    public_ipv4: process.env.ROSENWEG_PUBLIC_IPV4 || null,
    public_ipv6: process.env.ROSENWEG_PUBLIC_IPV6 || null,
    cname_target: process.env.ROSENWEG_DNS_CNAME_TARGET || 'public.rosenweg4303.ch',
  };
}

// DNS-Check: prüft ob hostname's A/AAAA/CNAME auf uns zeigt
async function ispCheckDns(hostname) {
  const target = ispResolveTarget();
  const dns = (await import('node:dns/promises')).default;
  const out = { hostname, target, a: null, aaaa: null, cname: null, matches: false, error: null };
  try { out.a = await dns.resolve4(hostname).catch(() => null); } catch {}
  try { out.aaaa = await dns.resolve6(hostname).catch(() => null); } catch {}
  try { out.cname = await dns.resolveCname(hostname).catch(() => null); } catch {}
  if (target.public_ipv4 && Array.isArray(out.a) && out.a.includes(target.public_ipv4)) out.matches = true;
  if (target.public_ipv6 && Array.isArray(out.aaaa) && out.aaaa.includes(target.public_ipv6)) out.matches = true;
  if (Array.isArray(out.cname) && out.cname.some(c => c.toLowerCase().replace(/\.$/, '') === target.cname_target.toLowerCase())) out.matches = true;
  return out;
}

// Auto-Approval-Entscheidung bei Erfassung
async function ispDecideApproval(hostname) {
  const adminReason = hostNeedsAdminApproval(hostname);
  if (adminReason) return { approval_status: 'pending_admin', approval_reason: adminReason, active: false };
  // Sofort DNS prüfen
  const dnsCheck = await ispCheckDns(hostname).catch(() => null);
  if (dnsCheck && dnsCheck.matches) {
    return { approval_status: 'approved', approval_reason: 'Auto-Approval: DNS zeigt auf uns', active: true,
             dns_verified_at: new Date(), last_dns_check_at: new Date() };
  }
  return { approval_status: 'pending_dns', approval_reason: 'DNS zeigt noch nicht auf uns', active: false,
           last_dns_check_at: new Date() };
}

// Endpoint: DNS-Info (zeigt Customer was er konfigurieren muss)
// ─── NOC Dashboard ─────────────────────────────────────────────────────
// Aggregierte Echtzeit-Metriken für das ISP-Admin-NOC-Cockpit.
// Admin-only — die Daten umfassen Quota-Stand, Top-Sender und Gesamt-
// Volumen über alle Sender-Domains.
// Public-NOC: Wallboard/Kiosk-Modus via Token-Param (?token=). Token wird im
// ENV NOC_PUBLIC_TOKEN gesetzt. Nur lesend. Internal-Forward an die admin
// Handler ueber app._router.handle nach dem Stack der erforderlichen Middlware.
const NOC_PUBLIC_TOKEN = process.env.NOC_PUBLIC_TOKEN || '';
// Token-Check, default-deny: ohne NOC_PUBLIC_OPEN=1 muss ein gueltiger Token
// kommen, sonst 403. Fail-safe nach docker-stack-deploy-Env-Wipe (siehe
// CLAUDE.md: stack deploy expandet ungesetzte Vars zu leerstring, was vorher
// die Endpoints weltweit oeffnete). Read-only Aggregat-Metriken — kein PII,
// aber auch nicht freiwillig an die Oeffentlichkeit.
function checkNocToken(req, res) {
  if (process.env.NOC_PUBLIC_OPEN === '1') return true;
  if (!NOC_PUBLIC_TOKEN) {
    res.status(503).json({ error: 'NOC-Public-Endpoint nicht konfiguriert (NOC_PUBLIC_TOKEN fehlt)' });
    return false;
  }
  const t = req.query.token || req.headers['x-noc-token'];
  if (t !== NOC_PUBLIC_TOKEN) { res.status(403).json({ error: 'Token ungueltig' }); return false; }
  return true;
}

// Public-Variante: alle Daten read-only, Token-gegated.
app.get('/api/isp/noc/public/dashboard', async (req, res) => {
  if (!checkNocToken(req, res)) return;
  return nocDashboardHandler(req, res);
});

// Oeffentliche Status-Zusammenfassung fuer die ISP-Startseite: 3 Rollup-Booleans aus
// den server-seitigen NOC-Checks (pve-LXC-Status + Frontend-/health) — KEINE fragilen
// Browser-Fetches/Cert-Abhaengigkeiten, KEINE Topologie geleakt. 15s-Cache.
let _ispSummary = null, _ispSummaryT = 0;
app.get('/api/isp/status-summary', async (req, res) => {
  try {
    if (_ispSummary && Date.now() - _ispSummaryT < 15000) return res.json(_ispSummary);
    const byId = {};
    try {
      const pve = await pveAPI('GET', '/cluster/resources?type=vm');
      for (const x of (Array.isArray(pve) ? pve : [])) if (x.type === 'lxc') byId[x.vmid] = x;
    } catch {}
    const up = (id) => byId[id]?.status === 'running';
    const health = async (ip) => { try { const r = await fetch(`http://${ip}/health`, { signal: AbortSignal.timeout(2500) }); return r.ok; } catch { return false; } };
    const [www, isp] = await Promise.all([health('100.64.2.41'), health('100.64.2.42')]);
    const out = {
      mail: up(240) && up(230),         // mailcow (CT240) + PMG (CT230)
      web: up(114) && up(104) && www,   // Authentik + Nextcloud + www-LXC
      internet: up(245) && isp,         // Edge (CT245) + isp-LXC
      ts: Date.now(),
    };
    _ispSummary = out; _ispSummaryT = Date.now();
    res.json(out);
  } catch (e) { res.json({ mail: true, web: true, internet: true, error: e.message }); }
});
