// UniFi: Port-Konfiguration (Port-Security MAC, Native-VLAN, Port-Profile)
// auf einem Switch-Port aendern oder zuruecksetzen.
async function unifiSetPortConfig(switchName, portIdx, { mac, vlan, portProfileId } = {}) {
  if (!switchName || !portIdx) return { skipped: 'no_switch_or_port' };
  const idx = parseInt(portIdx, 10);
  if (!Number.isInteger(idx) || idx < 1) throw new Error('port_idx ungueltig');
  const [d, n] = await Promise.all([unifiGet('stat/device'), unifiGet('rest/networkconf').catch(() => ({ data: [] }))]);
  const sw = (d.data || []).find(x => x.type === 'usw' && x.name === switchName);
  if (!sw) throw new Error(`Switch "${switchName}" nicht in UniFi gefunden`);
  const overrides = Array.isArray(sw.port_overrides) ? sw.port_overrides.map(o => ({ ...o })) : [];
  let entry = overrides.find(o => o.port_idx === idx);
  if (!entry) { entry = { port_idx: idx }; overrides.push(entry); }

  // MAC-Bindung (Port-Security)
  if (mac && /^[0-9a-f]{2}(:[0-9a-f]{2}){5}$/i.test(mac)) {
    entry.port_security_enabled = true;
    entry.port_security_mac_address = [mac.toLowerCase()];
  } else {
    entry.port_security_enabled = false;
    entry.port_security_mac_address = [];
  }

  // 802.1X auf ISP-Ports NIE erzwingen: es gibt keinen RADIUS-Server, ein geerbtes
  // dot1x_ctrl=auto blockiert den Port komplett (unauthorized) — trotz gesetzter
  // MAC-Port-Security. force_authorized = normal weiterleiten; die MAC-Allowlist
  // (oben) ist die eigentliche Absicherung. Gilt auch beim Entfernen (mac leer),
  // damit der Port sauber wieder freigegeben wird.
  entry.dot1x_ctrl = 'force_authorized';

  // VLAN / Port-Profile sind alternativ: Profile gewinnt wenn beides gesetzt.
  if (portProfileId) {
    entry.portconf_id = portProfileId;
    delete entry.native_networkconf_id;
  } else if (vlan) {
    const net = (n.data || []).find(x => Number(x.vlan) === Number(vlan));
    if (net) entry.native_networkconf_id = net._id;
    delete entry.portconf_id;
  } else {
    delete entry.portconf_id;
    delete entry.native_networkconf_id;
  }

  await unifiCall('PUT', `rest/device/${sw._id}`, { port_overrides: overrides });
  return { ok: true, switch: switchName, port: idx, mac: mac || null, vlan: vlan || null, portProfileId: portProfileId || null };
}

// UniFi: Static-DHCP-Reservation fuer eine MAC. UniFi-User-Record patchen.
async function unifiSetStaticDhcp(mac, fixedIp, networkconfId) {
  if (!mac || !/^[0-9a-f]{2}(:[0-9a-f]{2}){5}$/i.test(mac)) return { skipped: 'mac_invalid' };
  const macLower = mac.toLowerCase();
  // User-Record existiert evtl. schon — sonst anlegen
  const list = await unifiGet(`rest/user?mac=${macLower}`).catch(() => null);
  const found = list?.data?.find(u => u.mac === macLower);
  const body = fixedIp
    ? { mac: macLower, use_fixedip: true, fixed_ip: fixedIp, ...(networkconfId ? { network_id: networkconfId } : {}) }
    : { mac: macLower, use_fixedip: false };
  if (found) {
    await unifiCall('PUT', `rest/user/${found._id}`, body);
  } else if (fixedIp) {
    await unifiCall('POST', 'rest/user', body);
  }
  return { ok: true, mac: macLower, fixed_ip: fixedIp || null };
}

// Hilfs-Wrapper: vergleicht alten + neuen Sub-Eintrag und propagiert Aenderungen
// an UniFi. Liefert pro Schritt OK/Error zurueck damit der Handler entscheiden
// kann ob status='aktiv' wirklich gerechtfertigt ist.
async function syncSubscriberToUnifi(oldRow, newRow) {
  const result = { ok: true, steps: [], errors: [] };
  try {
    const oldSw = oldRow?.switch_name; const oldPort = oldRow?.switch_port;
    const newSw = newRow?.switch_name; const newPort = newRow?.switch_port;
    const newMac = newRow?.mac_dot1x;
    const newVlan = newRow?.vlan;
    const newProfile = newRow?.port_profile_id;
    const newFixedIp = newRow?.fixed_ip;

    if (oldSw && oldPort && (oldSw !== newSw || String(oldPort) !== String(newPort))) {
      try { await unifiSetPortConfig(oldSw, oldPort, {}); result.steps.push('clear_old_port'); }
      catch (e) { result.errors.push({ step: 'clear_old_port', error: e.message }); }
    }
    if (newSw && newPort) {
      try {
        await unifiSetPortConfig(newSw, newPort, { mac: newMac, vlan: newVlan, portProfileId: newProfile });
        result.steps.push('port_config');
      } catch (e) { result.errors.push({ step: 'port_config', error: e.message }); }
    }

    if (oldRow?.mac_dot1x && oldRow.mac_dot1x !== newMac) {
      try { await unifiSetStaticDhcp(oldRow.mac_dot1x, null, null); result.steps.push('clear_old_dhcp'); }
      catch (e) { result.errors.push({ step: 'clear_old_dhcp', error: e.message }); }
    }
    if (newMac && newFixedIp) {
      let networkconfId = null;
      try {
        const n = await unifiGet('rest/networkconf');
        const net = (n.data || []).find(x => Number(x.vlan) === Number(newVlan));
        if (net) networkconfId = net._id;
      } catch {}
      try { await unifiSetStaticDhcp(newMac, newFixedIp, networkconfId); result.steps.push('dhcp_reservation'); }
      catch (e) { result.errors.push({ step: 'dhcp_reservation', error: e.message }); }
    } else if (newMac && !newFixedIp && oldRow?.fixed_ip) {
      try { await unifiSetStaticDhcp(newMac, null, null); result.steps.push('clear_old_dhcp_keep_user'); }
      catch (e) { /* nicht-kritisch */ }
    }
  } catch (e) {
    result.errors.push({ step: 'sync', error: e.message });
  }
  result.ok = result.errors.length === 0;
  return result;
}

// === Subscribers (Wohnungs-Anschluesse) ===
// Live-Status eines Anschlusses aus UniFi: Gerät dran? richtige MAC am Port? richtige IP?
// 802.1X-blockiert? Spiegelt die Soll-Konfig (switch/port/mac_dot1x/fixed_ip) gegen die
// echten UniFi-Daten (stat/device Port + stat/sta Clients).
function ispSubscriberLive(sub, devices, clients) {
  if (!sub.switch_name || !sub.switch_port) return { checked: false, state: 'unconfigured' };
  const wantSw = String(sub.switch_name || '').trim();
  const sw = (devices || []).find(d => String(d.name || '').trim() === wantSw && Array.isArray(d.port_table));
  if (!sw) return { checked: true, state: 'switch_not_found' };
  const port = sw.port_table.find(p => String(p.port_idx) === String(sub.switch_port));
  if (!port) return { checked: true, state: 'port_not_found' };
  const expMac = String(sub.mac_dot1x || '').toLowerCase();
  const expIp = sub.fixed_ip || null;
  const swMac = String(sw.mac || '').toLowerCase();
  const onPort = (clients || []).filter(c => String(c.sw_mac || '').toLowerCase() === swMac && String(c.sw_port) === String(sub.switch_port));
  const learned = (port.mac_table || []).map(m => String(m.mac || '').toLowerCase()).filter(Boolean);
  const expClient = expMac ? (clients || []).find(c => String(c.mac || '').toLowerCase() === expMac) : null;
  const portUp = !!port.up;
  const connectedMac = (onPort[0] && String(onPort[0].mac).toLowerCase()) || learned[0] || null;
  const devicePresent = portUp && (onPort.length > 0 || learned.length > 0);
  const macOk = expMac ? (onPort.some(c => String(c.mac || '').toLowerCase() === expMac) || learned.includes(expMac)) : null;
  const ipActual = (expClient && expClient.ip) || (onPort[0] && onPort[0].ip) || null;
  const ipOk = expIp ? (ipActual === expIp) : null;
  const macFilter = !!port.port_security_enabled && (port.port_security_mac_address || []).map(x => String(x).toLowerCase()).includes(expMac);
  let state;
  if (String(port.dot1x_ctrl) === 'auto') state = 'blocked_dot1x';   // 802.1X ohne RADIUS -> Port tot
  else if (!devicePresent) state = 'no_device';
  else if (expMac && macOk === false) state = 'wrong_mac';
  else if (expMac && macOk && expIp && ipOk === false) state = 'ip_mismatch';
  else if (macOk !== false && !ipActual) state = 'no_ip';
  else state = 'ok';
  return { checked: true, state, port_up: portUp, device_present: devicePresent,
           connected_mac: connectedMac, mac_ok: macOk, ip_actual: ipActual, ip_ok: ipOk,
           mac_filter: macFilter, dot1x_ctrl: port.dot1x_ctrl || null };
}

app.get('/api/isp/subscribers', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Technik/Präsident' });
    const r = await pool.query(
      `SELECT s.*, w.bezeichnung AS wohnung_bezeichnung, w.stweg
         FROM isp_subscribers s
         LEFT JOIN wohnungen w ON w.id = s.wohnung_id
        ORDER BY w.stweg, w.bezeichnung`,
    );
    const subs = r.rows;
    // Live-Status best-effort aus UniFi (Port/MAC/IP gegen Soll). Faellt UniFi aus -> ohne live.
    if (subs.some(s => s.switch_name && s.switch_port)) {
      try {
        const [dev, sta] = await Promise.all([unifiGet('stat/device', 5000), unifiGet('stat/sta', 5000)]);
        const devices = dev.data || [], clients = sta.data || [];
        for (const s of subs) s.live = ispSubscriberLive(s, devices, clients);
      } catch (e) { console.warn('[isp] live-status:', e.message); }
    }
    res.json({ subscribers: subs });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

