// === VPN-Konten ===
//
// VPN-Backend: kleiner Steuerdienst `wg-control` auf der vpn-wg-LXC
// (CT 113, 100.64.2.34:3001). Erzeugt Peer-Keypair, hängt ihn in wg0 ein,
// macht per-Peer-NAT in das Heim-VLAN des Users und liefert die
// fertige Client-.conf + QR-Code zurück.
const WG_CONTROL_URL   = process.env.WG_CONTROL_URL   || 'http://100.64.2.34:3001';
const WG_CONTROL_TOKEN = process.env.WG_CONTROL_TOKEN || '';

async function wgControl(method, path, body) {
  const r = await fetch(WG_CONTROL_URL + path, {
    method,
    headers: {
      'Authorization': 'Bearer ' + WG_CONTROL_TOKEN,
      ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
    },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  if (!r.ok) {
    const txt = await r.text().catch(() => '');
    const e = new Error(`wg-control ${method} ${path} -> ${r.status}: ${txt}`);
    e.status = r.status >= 500 ? 502 : r.status;
    throw e;
  }
  return r;
}

// Rosenweg-Nr → VLAN (synchron mit /opt/wg-control/server.js)
const VPN_RW_TO_VLAN = {1:19,2:29,4:49,5:59,6:69,8:89,9:99,10:109,12:129,13:139,14:149,16:169,17:179,18:189};
function vpnRwFromBezeichnung(bez) {
  if (!bez) return null;
  let m = bez.match(/^RW(\d+)/i);
  if (m) return parseInt(m[1], 10);
  m = bez.match(/^(\d+)[\.\-]/);
  if (m) return parseInt(m[1], 10);
  m = bez.match(/^(\d{2})(\d{2})$/);
  if (m) { const rw = parseInt(m[1], 10); if (rw >= 10 && rw <= 18) return rw; }
  return null;
}
// Klassifiziert einen Wohnungs-Eintrag in Kategorie + VLAN.
// Reihenfolge bei Default-Pick: wohnung (0) -> hobbyraum (1) -> parkplatz (2)
function classifyVpnEntry(bezeichnung) {
  const b = bezeichnung || '';
  // Hobbyraum: explizit oder mit Hausnummer-Prefix
  if (/hobbyraum/i.test(b)) {
    const rw = vpnRwFromBezeichnung(b);
    return { kind: 'hobbyraum', kindOrder: 1, vlan: (rw && VPN_RW_TO_VLAN[rw]) || null };
  }
  // Parkplatz: P\d+
  if (/^P\d+/i.test(b)) return { kind: 'parkplatz', kindOrder: 2, vlan: 9 };
  // Wohnung: alles mit erkennbarer Hausnummer
  const rw = vpnRwFromBezeichnung(b);
  if (rw && VPN_RW_TO_VLAN[rw]) return { kind: 'wohnung', kindOrder: 0, vlan: VPN_RW_TO_VLAN[rw] };
  return { kind: 'unbekannt', kindOrder: 9, vlan: null };
}

async function getUserVlanOptions(email) {
  if (!email) return [];
  const r = await pool.query(
    `SELECT w.id AS wohnung_id, w.bezeichnung, w.stweg
       FROM wohnungen_kontakte wk
       JOIN wohnungen w ON w.id = wk.wohnung_id
       JOIN personen p  ON p.id = wk.person_id
      WHERE wk.archiviert_am IS NULL
        AND ( LOWER(p.email) = LOWER($1)
              OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(COALESCE(p.emails,'[]'::jsonb)) e
                          WHERE LOWER(e) = LOWER($1)) )`,
    [email],
  );
  const opts = r.rows
    .map(row => ({ ...row, ...classifyVpnEntry(row.bezeichnung) }))
    .filter(o => o.vlan);
  // Dedup: gleiche (kind, vlan, wohnung_id)
  const seen = new Set();
  const dedup = opts.filter(o => {
    const k = `${o.kind}:${o.vlan}:${o.wohnung_id}`;
    if (seen.has(k)) return false; seen.add(k); return true;
  });
  dedup.sort((a, b) => a.kindOrder - b.kindOrder || (a.bezeichnung || '').localeCompare(b.bezeichnung || ''));
  return dedup;
}

async function resolveHomeVlanForEmail(email) {
  const opts = await getUserVlanOptions(email);
  return opts.length > 0 ? opts[0].vlan : null;
}

app.get('/api/isp/vpn-accounts', authMiddleware, async (req, res) => {
  try {
    const admin = ispIsAdmin(req);
    const email = (req.user.email || '').toLowerCase();
    const r = admin
      ? await pool.query('SELECT * FROM isp_vpn_accounts ORDER BY active DESC, user_email, backend')
      : await pool.query('SELECT * FROM isp_vpn_accounts WHERE LOWER(user_email) = $1 ORDER BY active DESC, backend', [email]);
    let rows = r.rows;
    // last_connect_at wird in der DB nie gefüllt — Live-Handshake aus wg-control überlagern
    if (WG_CONTROL_TOKEN && rows.length) {
      try {
        const wr = await wgControl('GET', '/peers');
        const body = await wr.json();
        const peers = Array.isArray(body) ? body : (body.peers || []);
        const hsMap = new Map();
        for (const p of peers) {
          const hs = p.latest_handshake || null;
          if (p.public_key) hsMap.set('pk:' + p.public_key, hs);
          if (p.id != null) hsMap.set('id:' + String(p.id), hs);
          if (p.name) hsMap.set('nm:' + p.name, hs);
        }
        rows = rows.map(v => {
          const hs = (v.public_key && hsMap.get('pk:' + v.public_key))
            || (v.username && hsMap.get('id:' + String(v.username)))
            || (v.username && hsMap.get('nm:' + v.username)) || null;
          return hs ? { ...v, last_connect_at: hs } : v;
        });
      } catch {}
    }
    res.json({ vpn_accounts: rows, is_admin: admin });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

