// === VLAN-Requests ===
// Mitnutzer-Emails normalisieren: lowercase, getrimmt, dedupe, ohne Antragsteller, basic Format-Check.
function normalizeMitnutzerEmails(input, antragstellerEmail) {
  if (!input) return [];
  const arr = Array.isArray(input)
    ? input
    : String(input).split(/[,;\s]+/);
  const ant = (antragstellerEmail || '').toLowerCase().trim();
  const out = new Set();
  for (const raw of arr) {
    const e = String(raw || '').toLowerCase().trim();
    if (!e || e === ant) continue;
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) continue;
    out.add(e);
  }
  return Array.from(out);
}

app.get('/api/isp/vlan-requests', authMiddleware, async (req, res) => {
  try {
    const admin = ispIsAdmin(req);
    const email = (req.user.email || '').toLowerCase();
    const r = admin
      ? await pool.query(`SELECT v.*, w.bezeichnung AS wohnung_bezeichnung, w.stweg,
                                  cr.client_vlan_id AS router_client_vlan_id, cr.bezeichnung AS router_bezeichnung,
                                  cr.lxc_id AS router_lxc_id
                           FROM isp_vlan_requests v
                           LEFT JOIN wohnungen w ON w.id = v.wohnung_id
                           LEFT JOIN isp_client_vlan_routers cr ON cr.id = v.assigned_router_id
                           ORDER BY CASE v.status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 WHEN 'deployed' THEN 2 ELSE 3 END, v.created_at DESC`)
      : await pool.query(`SELECT v.*, w.bezeichnung AS wohnung_bezeichnung, w.stweg,
                                  cr.client_vlan_id AS router_client_vlan_id, cr.bezeichnung AS router_bezeichnung
                           FROM isp_vlan_requests v
                           LEFT JOIN wohnungen w ON w.id = v.wohnung_id
                           LEFT JOIN isp_client_vlan_routers cr ON cr.id = v.assigned_router_id
                           WHERE LOWER(v.antragsteller_email) = $1
                              OR $1 = ANY(COALESCE(v.mitnutzer_emails, ARRAY[]::TEXT[]))
                           ORDER BY v.created_at DESC`, [email]);
    const rows = r.rows.map(v => ({
      ...v,
      is_owner: (v.antragsteller_email || '').toLowerCase() === email,
      is_mitnutzer: (v.mitnutzer_emails || []).map(x => String(x).toLowerCase()).includes(email),
    }));
    res.json({ vlan_requests: rows, is_admin: admin });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

app.post('/api/isp/vlan-requests', authMiddleware, async (req, res) => {
  try {
    const b = req.body || {};
    if (!b.zweck) return res.status(400).json({ error: 'zweck Pflicht (wofür wird das VLAN gebraucht)' });
    // User-Wahl validieren: wohnung_id muss zu eigenen Einheiten gehören (Admin darf alles)
    let wohnungId = b.wohnung_id || null;
    if (wohnungId && !ispIsAdmin(req)) {
      const ownOpts = await getUserVlanOptions(req.user.email);
      if (!ownOpts.some(o => o.wohnung_id === parseInt(wohnungId, 10))) {
        return res.status(403).json({ error: 'Dieses Objekt gehört nicht zu deinen zugewiesenen Einheiten' });
      }
    }
    const mitnutzer = normalizeMitnutzerEmails(b.mitnutzer_emails, req.user.email);
    const r = await pool.query(
      `INSERT INTO isp_vlan_requests (antragsteller_email, wohnung_id, zweck, gewuenschter_name,
                                       gewuenschte_groesse, geraete_anzahl, internet_zugriff, andere_vlans_zugriff,
                                       mitnutzer_emails, kind, with_wlan)
       VALUES ($1,$2,$3,$4,$5,$6,COALESCE($7,true),COALESCE($8,false),$9,
               COALESCE($10,'vlan'),COALESCE($11,false)) RETURNING *`,
      [req.user.email, wohnungId, b.zweck, b.gewuenschter_name || null,
       b.gewuenschte_groesse || null, b.geraete_anzahl || null, b.internet_zugriff, b.andere_vlans_zugriff,
       mitnutzer, b.kind || null, b.with_wlan],
    );
    const created = r.rows[0];
    const kindLabel = created.kind === 'subnet' ? 'Subnet/eigenes IP-Netz' : 'VLAN';
    // User-controlled Felder vor dem WA-Push clampen + Markdown-Marker
    // (`*`, `_`, ` ``` `) entschaerfen, sonst kann ein Antragsteller die
    // Technik-Group-Nachricht beliebig formatieren / kapern.
    const clamp = (s, n = 200) => String(s || '').replace(/[*_`~]/g, '').slice(0, n);
    notifyTechnik(
      `🆕 *Neuer ${kindLabel}-Antrag* (pending)\n` +
      `${clamp(created.gewuenschter_name, 80) || '(unbenannt)'} — von ${clamp(req.user.email, 120)}\n` +
      `Zweck: ${clamp(created.zweck, 300)}` +
      (created.with_wlan ? `\nmit WLAN-SSID gewuenscht` : '') +
      `\n${SITE_URL}/isp-admin.html#vlan`,
      'vlan-request',
    ).catch(e => console.warn('[vlan-request notify]', e.message));
    res.json(created);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

app.put('/api/isp/vlan-requests/:id', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const existing = await pool.query('SELECT * FROM isp_vlan_requests WHERE id = $1', [id]);
    if (existing.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = existing.rows[0];
    const admin = ispIsAdmin(req);
    const email = (req.user.email || '').toLowerCase();
    const isOwner = (v.antragsteller_email || '').toLowerCase() === email;
    const isMitnutzer = (v.mitnutzer_emails || []).map(x => String(x).toLowerCase()).includes(email);
    if (!admin && !isOwner && !isMitnutzer) return res.status(403).json({ error: 'Nur Antragsteller, Mitnutzer oder Admin' });
    // Mitnutzer-Felder dürfen nur Owner editieren; ansonsten User-Felder während pending
    const b = req.body || {};
    const updates = []; const params = [];
    const push = (col, val) => { params.push(val); updates.push(`${col} = $${params.length}`); };
    const userFields = ['zweck','gewuenschter_name','gewuenschte_groesse','geraete_anzahl','internet_zugriff','andere_vlans_zugriff','kind','with_wlan'];
    const ownerOnlyFields = ['mitnutzer_emails'];
    const adminFields = ['status','vlan_id','subnet_v4','ablehnung_grund','notizen_technik','deployed_at',
                         'wlan_password','dhcp_range_from','dhcp_range_to','dhcp_gateway','unifi_network_id',
                         'assigned_router_id'];
    const allowed = admin ? [...userFields, ...ownerOnlyFields, ...adminFields]
                          : (isOwner ? [...userFields, ...ownerOnlyFields] : []);
    if (!admin && v.status !== 'pending') return res.status(400).json({ error: 'Nur in Status pending editierbar' });
    if (!admin && !isOwner && allowed.length === 0) return res.status(403).json({ error: 'Mitnutzer können Antrag nur zurückziehen, nicht editieren' });
    // VLAN-ID-Uniqueness prüfen, bevor wir UPDATE bauen.
    if (b.vlan_id !== undefined && b.vlan_id !== null && b.vlan_id !== '' && b.vlan_id !== v.vlan_id) {
      const dup = await pool.query(
        "SELECT id FROM isp_vlan_requests WHERE vlan_id = $1 AND id <> $2 AND status IN ('approved','deployed')",
        [b.vlan_id, id]);
      if (dup.rows.length > 0) {
        return res.status(409).json({ error: `VLAN-ID ${b.vlan_id} ist bereits an Antrag #${dup.rows[0].id} vergeben` });
      }
      // Optional: gegen UniFi-Live-Check (vermeidet Konflikt mit von Hand angelegten Netzen).
      // Nicht-blockierend bei Fehler — UniFi-API kann mal down sein.
      try {
        const uw = await unifiGet('rest/networkconf', 3500);
        const used = (uw.data || []).some(n => Number(n.vlan) === Number(b.vlan_id));
        if (used) return res.status(409).json({ error: `VLAN-ID ${b.vlan_id} ist bereits in UniFi konfiguriert` });
      } catch {}
    }
    for (const col of allowed) if (b[col] !== undefined) {
      if (col === 'mitnutzer_emails') {
        push(col, normalizeMitnutzerEmails(b[col], v.antragsteller_email));
      } else {
        push(col, b[col] === '' ? null : b[col]);
      }
    }
    if (updates.length === 0) return res.status(400).json({ error: 'Keine Änderungen' });
    push('updated_at', new Date());
    params.push(id);
    const r = await pool.query(`UPDATE isp_vlan_requests SET ${updates.join(', ')} WHERE id = $${params.length} RETURNING *`, params);
    const updated = r.rows[0];

    // Auto-Deploy: wenn admin gerade status -> approved gesetzt hat, Antrag ist
    // 'subnet'-kind und hat alle Felder, fahren wir die Provisionierung direkt
    // an. Bei kind='vlan' nicht (da gibt's nichts zu provisionieren) und auch
    // nicht wenn der Antrag schon deployed war.
    let provisioning = null;
    const becameApproved = admin && b.status === 'approved' && v.status !== 'approved' && v.status !== 'deployed';
    const isSubnet = (updated.kind || 'vlan') === 'subnet';
    const hasRequiredFields = updated.vlan_id && updated.subnet_v4 && updated.dhcp_gateway && updated.dhcp_range_from && updated.dhcp_range_to && updated.assigned_router_id;
    if (becameApproved && isSubnet && hasRequiredFields) {
      try {
        provisioning = await runProvisioning(id);
      } catch (e) { provisioning = { ok: false, errors: [{ step: 'auto_provision', error: e.message }] }; }
      // Aktualisierte Row nochmal lesen (status könnte jetzt 'deployed' sein)
      const final = await pool.query('SELECT * FROM isp_vlan_requests WHERE id = $1', [id]);
      return res.json({ ...final.rows[0], provisioning });
    }
    res.json(updated);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Vorschlag für nächste freie VLAN-ID nach Schema <HausNr><NN>
// Schema: docs/unifi.md — RW9 Bewohner -> 9XX (z.B. 911), RW18 -> 18XX (z.B. 1803)
app.get('/api/isp/vlan-requests/:id/suggest', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const id = parseInt(req.params.id, 10);
    const e = await pool.query('SELECT * FROM isp_vlan_requests WHERE id = $1', [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = e.rows[0];
    // 1. Wenn Antragsteller eine wohnung_id explizit angegeben hat, diese verwenden
    let home = null;
    if (v.wohnung_id) {
      const wq = await pool.query('SELECT id AS wohnung_id, bezeichnung, stweg FROM wohnungen WHERE id = $1', [v.wohnung_id]);
      if (wq.rows.length > 0) {
        home = { ...wq.rows[0], ...classifyVpnEntry(wq.rows[0].bezeichnung) };
      }
    }
    // 2. Fallback: erste verfuegbare User-Wohnung (Wohnung > Hobbyraum > Parkplatz)
    if (!home) {
      const opts = await getUserVlanOptions(v.antragsteller_email);
      home = opts.find(o => o.kind === 'wohnung') || opts[0];
    }
    if (!home) return res.status(400).json({ error: 'Antragsteller hat keine zugewiesene Haus-Einheit' });
    const hausNr = vpnRwFromBezeichnung(home.bezeichnung);
    if (!hausNr) return res.status(400).json({ error: `Haus-Nummer aus "${home.bezeichnung}" nicht ermittelbar` });
    // Verwendete VLAN-IDs aus DB (approved + deployed) UND aus UniFi (live).
    // Wer im UniFi-Controller von Hand ein VLAN angelegt hat, soll uns nicht
    // dieselbe ID vorgeschlagen bekommen.
    const used = await pool.query(
      "SELECT vlan_id FROM isp_vlan_requests WHERE vlan_id IS NOT NULL AND status IN ('approved','deployed')"
    );
    const usedSet = new Set(used.rows.map(r => r.vlan_id));
    let unifiUsed = [];
    try {
      const uw = await unifiGet('rest/networkconf', 3500);
      unifiUsed = (uw.data || []).map(n => Number(n.vlan)).filter(Number.isFinite);
      for (const v of unifiUsed) usedSet.add(v);
    } catch {}
    // Iteriere <Haus>01 .. <Haus>99 (z.B. 901..999 für RW9, 1801..1899 für RW18)
    const hausStr = String(hausNr);
    for (let seq = 1; seq <= 99; seq++) {
      const candidate = parseInt(hausStr + String(seq).padStart(2, '0'), 10);
      if (!usedSet.has(candidate)) {
        return res.json({
          haus: hausNr,
          haus_bezeichnung: home.bezeichnung,
          suggested_vlan_id: candidate,
          reasoning: `Schema <HausNr><NN>: nächste freie ID für RW${hausNr} = ${candidate}`,
          unifi_used_count: unifiUsed.length,
        });
      }
    }
    res.status(409).json({ error: `Keine freie VLAN-ID im RW${hausNr}-Bereich (alle 01-99 belegt)` });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

app.delete('/api/isp/vlan-requests/:id', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const ex = await pool.query(`
      SELECT v.*, cr.client_vlan_id AS router_client_vlan_id, cr.lxc_id AS router_lxc_id,
             cr.bezeichnung AS router_bezeichnung
        FROM isp_vlan_requests v
        LEFT JOIN isp_client_vlan_routers cr ON cr.id = v.assigned_router_id
        WHERE v.id = $1`, [id]);
    if (ex.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = ex.rows[0];
    const admin = ispIsAdmin(req);
    const email = (req.user.email || '').toLowerCase();
    const isOwner = (v.antragsteller_email || '').toLowerCase() === email;
    const isMitnutzer = (v.mitnutzer_emails || []).map(x => String(x).toLowerCase()).includes(email);
    if (!admin && !isOwner && !isMitnutzer) return res.status(403).json({ error: 'Nur Antragsteller, Mitnutzer oder Admin' });

    // Wenn der Antrag schon provisioniert war (approved/deployed mit
    // unifi_network_id), erst aufräumen: Router-LXC API + Trunks + PPSK +
    // UniFi-Network. Sonst lassen wir Leaks zurück.
    let deprovisioning = null;
    const wasProvisioned = (v.status === 'approved' || v.status === 'deployed') && (v.unifi_network_id || v.vlan_id);
    if (wasProvisioned) {
      const router = v.assigned_router_id ? {
        lxc_id: v.router_lxc_id, client_vlan_id: v.router_client_vlan_id, bezeichnung: v.router_bezeichnung,
      } : null;
      try {
        deprovisioning = await runDeprovisioning(v, router);
      } catch (e) {
        deprovisioning = { ok: false, errors: [{ step: 'deprovision', error: e.message }] };
      }
    }

    await pool.query('DELETE FROM isp_vlan_requests WHERE id = $1', [id]);
    res.json({ ok: true, deprovisioning });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// === Phase 3: Auto-Provisioning (UniFi + Router-LXC + PPSK) ===

// CIDR-Helper: subnet "10.0.50.0/28" -> { mask: 28, mask_octets: "255.255.255.240", broadcast: "10.0.50.15" }
function parseCidr(cidr) {
  if (!cidr || typeof cidr !== 'string' || !cidr.includes('/')) return null;
  const [ip, m] = cidr.split('/');
  const mask = parseInt(m, 10);
  if (!Number.isInteger(mask) || mask < 8 || mask > 32) return null;
  const parts = ip.split('.').map(Number);
  if (parts.length !== 4 || parts.some(n => !Number.isInteger(n) || n < 0 || n > 255)) return null;
  const ipNum = (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3];
  const maskNum = mask === 0 ? 0 : ((~0) << (32 - mask)) >>> 0;
  const netNum = (ipNum & maskNum) >>> 0;
  const bcNum = (netNum | (~maskNum >>> 0)) >>> 0;
  const toIp = n => [(n >>> 24) & 0xff, (n >>> 16) & 0xff, (n >>> 8) & 0xff, n & 0xff].join('.');
  const mo = toIp(maskNum);
  return { mask, mask_octets: mo, network: toIp(netNum), broadcast: toIp(bcNum), first_host: toIp(netNum + 1), last_host: toIp(bcNum - 1) };
}

// Subnet-Groesse vom User-Wunsch parsen: "/28" oder "28" -> 28. Default 28.
// Akzeptiert /24 - /30 (16-4 IPs); /30 ist Minimum für P2P, sinnvoll ab /29.
function parseRequestedMask(s) {
  if (s == null || String(s).trim() === '') return 28;
  const m = /^\/?(\d+)$/.exec(String(s).trim());
  if (!m) return 28;
  const v = parseInt(m[1], 10);
  if (!Number.isInteger(v) || v < 24 || v > 30) return 28;
  return v;
}

// Allokiert den nächsten freien Subnet-Block der vom User gewuenschten Groesse
// aus dem Pool, ohne Konflikte mit anderen User-Subnets desselben Router-LXC.
async function allocateUserSubnet(routerId, requestedMask, excludeRequestId = null) {
  const rr = await pool.query('SELECT user_vlan_subnet_pool FROM isp_client_vlan_routers WHERE id = $1', [routerId]);
  if (rr.rows.length === 0) throw new Error('Router-LXC nicht gefunden');
  const poolCidr = String(rr.rows[0].user_vlan_subnet_pool || '');
  const poolP = parseCidr(poolCidr);
  if (!poolP) throw new Error('user_vlan_subnet_pool ungueltig: ' + poolCidr);
  if (poolP.mask >= requestedMask) throw new Error(`Pool /${poolP.mask} kann kein /${requestedMask} liefern`);

  const used = await pool.query(`
    SELECT v.id, v.subnet_v4
      FROM isp_vlan_requests v
     WHERE v.assigned_router_id = $1
       AND v.subnet_v4 IS NOT NULL
       AND v.status IN ('approved','deployed')
       ${excludeRequestId ? 'AND v.id <> $2' : ''}
  `, excludeRequestId ? [routerId, excludeRequestId] : [routerId]);

  const ipToNum = ip => ip.split('.').reduce((n, o) => (n << 8) + (+o), 0) >>> 0;
  const numToIp = n => [(n >>> 24) & 0xff, (n >>> 16) & 0xff, (n >>> 8) & 0xff, n & 0xff].join('.');
  const inUse = used.rows.map(r => {
    const p = parseCidr(String(r.subnet_v4));
    if (!p) return null;
    return { start: ipToNum(p.network), end: ipToNum(p.broadcast) };
  }).filter(Boolean);

  const poolStart = ipToNum(poolP.network);
  const poolEnd = ipToNum(poolP.broadcast);
  const blockSize = 1 << (32 - requestedMask);

  // First-fit ab Pool-Start, aligned auf blockSize (Pool ist groesser → automatisch aligned).
  for (let candidate = poolStart; candidate + blockSize - 1 <= poolEnd; candidate += blockSize) {
    const cEnd = candidate + blockSize - 1;
    const collision = inUse.some(u => !(cEnd < u.start || candidate > u.end));
    if (collision) continue;
    const net = numToIp(candidate);
    // Bei /30: nur 1 Host (.1=gw, .2=DHCP, .3=Broadcast). Bei /29: 6 Hosts. Bei /28: 14.
    return {
      cidr: `${net}/${requestedMask}`,
      gateway: numToIp(candidate + 1),
      dhcp_from: numToIp(candidate + 2),
      dhcp_to: numToIp(candidate + blockSize - 2),
      mask: requestedMask,
      broadcast: numToIp(cEnd),
      usable_hosts: Math.max(0, blockSize - 3), // minus net + bcast + gw
    };
  }
  throw new Error(`Kein freier /${requestedMask}-Block im Pool ${poolCidr}`);
}

// Endpoint: Auto-Vorbefuellung fuers Approve-Modal.
app.get('/api/isp/vlan-requests/:id/allocation-preview', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const id = parseInt(req.params.id, 10);
    const ex = await pool.query('SELECT * FROM isp_vlan_requests WHERE id = $1', [id]);
    if (ex.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = ex.rows[0];
    const out = { request_id: id, kind: v.kind || 'vlan', with_wlan: !!v.with_wlan };

    // VLAN-ID vorschlagen
    try {
      const sR = await fetch(`http://127.0.0.1:${PORT}/api/isp/vlan-requests/${id}/suggest`, {
        headers: { 'Authorization': req.headers.authorization || '' },
      }).catch(() => null);
      if (sR && sR.ok) {
        const s = await sR.json();
        out.suggested_vlan_id = s.suggested_vlan_id;
        out.haus = s.haus;
      }
    } catch {}

    // Router auto-vorschlagen: per Haus -> Client-VLAN aus VPN_RW_TO_VLAN
    let routerId = v.assigned_router_id;
    if (!routerId) {
      let homeBezeichnung = null;
      if (v.wohnung_id) {
        const wq = await pool.query('SELECT bezeichnung FROM wohnungen WHERE id = $1', [v.wohnung_id]);
        homeBezeichnung = wq.rows[0]?.bezeichnung || null;
      }
      if (!homeBezeichnung) {
        const opts = await getUserVlanOptions(v.antragsteller_email);
        homeBezeichnung = opts[0]?.bezeichnung || null;
      }
      const haus = vpnRwFromBezeichnung(homeBezeichnung);
      const cvlan = haus && VPN_RW_TO_VLAN[haus];
      if (cvlan) {
        const rr = await pool.query('SELECT id, client_vlan_id, lxc_id, bezeichnung FROM isp_client_vlan_routers WHERE client_vlan_id = $1 AND active = true', [cvlan]);
        if (rr.rows.length > 0) { routerId = rr.rows[0].id; out.suggested_router = rr.rows[0]; }
      }
    } else {
      const rr = await pool.query('SELECT id, client_vlan_id, lxc_id, bezeichnung FROM isp_client_vlan_routers WHERE id = $1', [routerId]);
      if (rr.rows.length > 0) out.suggested_router = rr.rows[0];
    }
    out.assigned_router_id = routerId;

    // Subnet allokieren (nur für kind=subnet)
    if ((v.kind || 'vlan') === 'subnet' && routerId) {
      const mask = parseRequestedMask(v.gewuenschte_groesse);
      try {
        out.allocation = await allocateUserSubnet(routerId, mask, id);
      } catch (e) { out.allocation_error = e.message; }
    }
    res.json(out);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Zufaelliges Passwort für PPSK (12 chars, alphanum)
function generatePpskPassword() {
  const a = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  const l = 'abcdefghjkmnpqrstuvwxyz';
  const n = '23456789';
  const all = a + l + n;
  let out = a[Math.floor(Math.random() * a.length)] + l[Math.floor(Math.random() * l.length)] + n[Math.floor(Math.random() * n.length)];
  for (let i = 0; i < 9; i++) out += all[Math.floor(Math.random() * all.length)];
  return out.split('').sort(() => Math.random() - 0.5).join('');
}

// UniFi Network-Conf für User-VLAN anlegen. purpose='vlan-only' = reine
// VLAN-Tag-Propagation auf APs/Switches, KEIN UDM-Gateway, KEIN DHCP.
// Routing+DHCP macht die Router-LXC auf VLAN <id> via eth0.<vlan>.
async function unifiCreateUserNetwork(v) {
  const body = {
    name: v.gewuenschter_name || `vlan-${v.vlan_id}`,
    purpose: 'vlan-only',
    enabled: true,
    vlan_enabled: true,
    vlan: v.vlan_id,
  };
  const r = await unifiCall('POST', 'rest/networkconf', body);
  const created = (r.data || [])[0] || r;
  return created;
}

// PPSK zur Rosenweg-WLAN hinzufügen, networkconf_id zeigt auf User-Netz.
async function unifiAddPpskToRosenwegWlan(networkconf_id, password) {
  const wl = await unifiGet('rest/wlanconf');
  const rosenweg = (wl.data || []).find(w => w.name === 'Rosenweg');
  if (!rosenweg) throw new Error('WLAN "Rosenweg" nicht in UniFi gefunden');
  const psks = Array.isArray(rosenweg.private_preshared_keys) ? rosenweg.private_preshared_keys.slice() : [];
  psks.push({ password, networkconf_id });
  const body = {
    private_preshared_keys: psks,
    private_preshared_keys_enabled: true,
  };
  await unifiCall('PUT', `rest/wlanconf/${rosenweg._id}`, body);
  return { wlan_id: rosenweg._id, ppsk_count: psks.length };
}

// Router-LXC Mgmt-IP: pro CT eine IP in VLAN 3 (RK-Technik), Schema 100.64.3.<lxc-400>.
function routerLxcMgmtIp(lxcId) { return `100.64.3.${lxcId - 400}`; }
// Shared Bearer-Token aus Docker-Secret /run/secrets/router_api_token.
function routerApiToken() {
  try { return require('fs').readFileSync('/run/secrets/router_api_token', 'utf8').trim(); }
  catch { return process.env.ROUTER_API_TOKEN || ''; }
}
// HTTP-Call gegen die Router-LXC-API (lauscht auf eth1 in VLAN 3, Port 8080).
async function routerApiCall(lxcId, method, path, body) {
  const ip = routerLxcMgmtIp(lxcId);
  const token = routerApiToken();
  if (!token) throw new Error('ROUTER_API_TOKEN/Secret nicht konfiguriert');
  // Router-API antwortet jetzt async: POST /vlans gibt sofort {job_id}
  // zurueck statt synchron auf dnsmasq+nft-Reload zu warten. 8s reichen
  // dicke fuer den Sync-Teil (Idempotenz-Check + Job-Spawn).
  const opts = {
    method,
    headers: { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' },
    signal: AbortSignal.timeout(8000),
  };
  if (body !== undefined) opts.body = JSON.stringify(body);
  const r = await fetch(`http://${ip}:8080${path}`, opts);
  const text = await r.text();
  let json;
  try { json = JSON.parse(text); } catch { json = { raw: text }; }
  if (!r.ok) throw new Error(`router-api ${ip} ${method} ${path} -> ${r.status} ${text.slice(0, 200)}`);
  return json;
}

// PPSK für eine bestimmte networkconf_id wieder aus der Rosenweg-WLAN raus.
async function unifiRemovePpskForNetwork(networkconf_id) {
  const wl = await unifiGet('rest/wlanconf');
  const rosenweg = (wl.data || []).find(w => w.name === 'Rosenweg');
  if (!rosenweg) return { skipped: 'wlan_not_found' };
  const before = Array.isArray(rosenweg.private_preshared_keys) ? rosenweg.private_preshared_keys : [];
  const after = before.filter(p => p.networkconf_id !== networkconf_id);
  if (after.length === before.length) return { skipped: 'no_ppsk_for_network' };
  await unifiCall('PUT', `rest/wlanconf/${rosenweg._id}`, {
    private_preshared_keys: after,
    private_preshared_keys_enabled: after.length > 0,
  });
  return { removed: before.length - after.length };
}

// UniFi-Network löschen
async function unifiDeleteNetwork(networkconf_id) {
  return await unifiCall('DELETE', `rest/networkconf/${networkconf_id}`);
}

// VLAN aus net0.trunks der Router-LXC entfernen
async function pveRemoveTrunkFromRouter(router, userVlan) {
  const resources = await pveAPI('GET', '/cluster/resources?type=vm');
  const ct = (resources || []).find(x => x.type === 'lxc' && x.vmid === router.lxc_id);
  if (!ct) return { skipped: 'ct_not_found' };
  const cfg = await pveAPI('GET', `/nodes/${ct.node}/lxc/${router.lxc_id}/config`);
  const parts = String(cfg.net0 || '').split(',');
  const idx = parts.findIndex(p => p.startsWith('trunks='));
  if (idx === -1) return { skipped: 'no_trunks' };
  const cur = parts[idx].slice('trunks='.length).split(';').filter(Boolean).map(Number);
  const after = cur.filter(v => v !== Number(userVlan));
  if (after.length === cur.length) return { skipped: 'vlan_not_in_trunks' };
  if (after.length === 0) parts.splice(idx, 1);
  else parts[idx] = `trunks=${after.join(';')}`;
  await pveAPI('PUT', `/nodes/${ct.node}/lxc/${router.lxc_id}/config`, { net0: parts.join(',') });
  return { removed: userVlan, remaining: after.length };
}

// Vollstaendiges Deprovisioning: Router-LXC API + Trunk + PPSK + UniFi-Network
async function runDeprovisioning(v, router) {
  const result = { steps: [], errors: [] };
  // 1) Router-LXC-API: DELETE /vlans/<id>
  if (router && v.vlan_id) {
    try {
      const r = await routerApiCall(router.lxc_id, 'DELETE', `/vlans/${v.vlan_id}`);
      result.steps.push({ step: 'router_lxc', ok: true, lxc_id: router.lxc_id, detail: r });
    } catch (err) {
      result.errors.push({ step: 'router_lxc', error: err.message });
    }
  }
  // 2) Trunks im pct.conf raus
  if (router && v.vlan_id) {
    try {
      const r = await pveRemoveTrunkFromRouter(router, v.vlan_id);
      result.steps.push({ step: 'pve_trunks', ok: true, detail: r });
    } catch (err) {
      result.errors.push({ step: 'pve_trunks', error: err.message });
    }
  }
  // 3) PPSK raus
  if (v.unifi_network_id) {
    try {
      const r = await unifiRemovePpskForNetwork(v.unifi_network_id);
      result.steps.push({ step: 'ppsk', ok: true, detail: r });
    } catch (err) {
      result.errors.push({ step: 'ppsk', error: err.message });
    }
  }
  // 4) UniFi-Network löschen
  if (v.unifi_network_id) {
    try {
      await unifiDeleteNetwork(v.unifi_network_id);
      result.steps.push({ step: 'unifi_network', ok: true });
    } catch (err) {
      result.errors.push({ step: 'unifi_network', error: err.message });
    }
  }
  return result;
}

// Router-LXC live-provisionieren via HTTP-API (laeuft im LXC auf eth1:8080).
// Setzt voraus dass net0.trunks die User-VLAN-ID enthaelt — sonst kommt der
// Tag nicht durch eth0. Trunks-Update via PVE-API (hot-apply via PUT /config).
async function pveProvisionRouterLxc(v, router) {
  // Welcher Node hostet den CT? Brauchen wir für die Trunk-Config.
  const resources = await pveAPI('GET', '/cluster/resources?type=vm');
  const ct = (resources || []).find(x => x.type === 'lxc' && x.vmid === router.lxc_id);
  if (!ct) throw new Error(`CT ${router.lxc_id} nicht im Cluster gefunden`);
  if (ct.status !== 'running') throw new Error(`CT ${router.lxc_id} ist ${ct.status}`);

  const userVlan = Number(v.vlan_id);
  const cidr = parseCidr(v.subnet_v4);
  if (!cidr) throw new Error('subnet_v4 ungueltig');

  // 1) Trunks im net0 sicherstellen (PVE-API PUT /config). Änderungen am bridge
  //    werden vom Kernel meist hot-applied; falls nicht, hat es spaetestens beim
  //    nächsten CT-Reboot Wirkung. Idempotent: nur PUT wenn was zu ändern.
  const cfg = await pveAPI('GET', `/nodes/${ct.node}/lxc/${router.lxc_id}/config`);
  const net0Parts = String(cfg.net0 || '').split(',');
  const trunksIdx = net0Parts.findIndex(p => p.startsWith('trunks='));
  let trunks = trunksIdx === -1 ? [] : net0Parts[trunksIdx].slice('trunks='.length).split(';').filter(Boolean).map(Number);
  if (!trunks.includes(userVlan)) {
    trunks.push(userVlan);
    if (trunksIdx === -1) net0Parts.push(`trunks=${trunks.join(';')}`);
    else net0Parts[trunksIdx] = `trunks=${trunks.join(';')}`;
    await pveAPI('PUT', `/nodes/${ct.node}/lxc/${router.lxc_id}/config`, { net0: net0Parts.join(',') });
  }

  // 2) Router-LXC API anfunken: legt ip-link / dnsmasq.d / nft-Regeln idempotent an.
  //    Router-API antwortet entweder mit applied:false (Idempotenz-Hit) oder
  //    {job_id, status:'pending'}. In letzterem Fall pollen wir bis done/failed.
  const initial = await routerApiCall(router.lxc_id, 'POST', '/vlans', {
    vlan: userVlan,
    gateway: v.dhcp_gateway,
    mask: cidr.mask,
    dhcp_from: v.dhcp_range_from,
    dhcp_to: v.dhcp_range_to,
  });
  let result = initial;
  if (initial.job_id) {
    result = await pollRouterJob(router.lxc_id, initial.job_id);
  }
  return { node: ct.node, lxc_id: router.lxc_id, user_vlan: userVlan, router_api: result };
}

// Poll Router-LXC job until done/failed. Default-Timeout 90s: jeder einzelne
// HTTP-Aufruf bleibt schnell (8s), wir koennen also viele Polls in einem
// 90-s-Fenster machen ohne dass ein einzelner Read den ganzen Provisioner
// blockt.
async function pollRouterJob(lxcId, jobId, { timeoutMs = 90_000, intervalMs = 1500 } = {}) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    await new Promise(r => setTimeout(r, intervalMs));
    let r;
    try { r = await routerApiCall(lxcId, 'GET', `/jobs/${jobId}`); }
    catch (e) { continue; } // transient — bis Timeout weiterprobieren
    if (r.status === 'done') return r.result;
    if (r.status === 'failed') throw new Error(`router-job ${jobId} failed: ${r.error || 'unknown'}`);
  }
  throw new Error(`router-job ${jobId} timeout nach ${timeoutMs}ms`);
}

// Bash-Skript für manuelles Provisioning auf dem Router-LXC.
// Wird vom Admin auf einem PVE-Host ausgefuehrt (er hat root + pct).
function buildRouterLxcProvisionScript(v, router) {
  const cidr = parseCidr(v.subnet_v4);
  const mask = cidr ? cidr.mask : 28;
  const gw = v.dhcp_gateway || (cidr ? cidr.first_host : '');
  const dhcpFrom = v.dhcp_range_from || '';
  const dhcpTo = v.dhcp_range_to || '';
  const lxcId = router?.lxc_id || '<LXC>';
  const userVlan = v.vlan_id || '<VLAN>';
  const clientVlan = router?.client_vlan_id || '<CLIENT_VLAN>';
  const clientIf = `eth0.${clientVlan}`;
  const userIf = `eth0.${userVlan}`;
  return `#!/usr/bin/env bash
# Provisioning für Netzwerk-Antrag #${v.id} (${v.gewuenschter_name || ''})
#   User-VLAN:    ${userVlan}
#   Subnet:       ${v.subnet_v4}
#   Gateway:      ${gw}/${mask}
#   DHCP-Range:   ${dhcpFrom} - ${dhcpTo}
#   Router-LXC:   ${lxcId}  (Client-VLAN ${clientVlan})
#
# Auf einem PVE-Host ausführen wo CT ${lxcId} laeuft:
#   ssh root@pveN  bash <(curl -s ...)   oder copy/paste.

set -euo pipefail
LXC=${lxcId}
USER_VLAN=${userVlan}
USER_IF=${userIf}
USER_NET=${v.subnet_v4}
USER_GW=${gw}
MASK=${mask}
DHCP_FROM=${dhcpFrom}
DHCP_TO=${dhcpTo}
CLIENT_VLAN=${clientVlan}
CLIENT_IF=${clientIf}

# 1. VLAN-Subinterface auf eth0 (sollte VLAN-aware sein)
pct exec $LXC -- bash -c "
  ip link show $USER_IF >/dev/null 2>&1 || ip link add link eth0 name $USER_IF type vlan id $USER_VLAN
  ip link set $USER_IF up
  ip addr replace \\\$USER_GW/$MASK dev $USER_IF
" 2>&1 | sed 's/^/  /'

# 2. dnsmasq-Config für dieses User-VLAN
pct exec $LXC -- bash -c "
  mkdir -p /etc/dnsmasq.d
  cat > /etc/dnsmasq.d/vlan-$USER_VLAN.conf <<EOF
interface=$USER_IF
bind-interfaces
dhcp-range=$DHCP_FROM,$DHCP_TO,12h
dhcp-option=tag:$USER_IF,3,$USER_GW
dhcp-option=tag:$USER_IF,6,1.1.1.1,1.0.0.1
EOF
  systemctl restart dnsmasq
" 2>&1 | sed 's/^/  /'

# 3. nftables: Isolation + Internet via Client-VLAN
pct exec $LXC -- bash -c "
  nft add table inet rosenweg 2>/dev/null || true
  nft add chain inet rosenweg forward '{ type filter hook forward priority 0; policy drop; }' 2>/dev/null || true
  nft add chain inet rosenweg nat_post '{ type nat hook postrouting priority 100; }' 2>/dev/null || true

  # Forward: User-VLAN <-> Client-VLAN (Richtung Uplink) erlauben
  nft add rule inet rosenweg forward iifname \\\"$USER_IF\\\" oifname \\\"$CLIENT_IF\\\" accept
  nft add rule inet rosenweg forward iifname \\\"$CLIENT_IF\\\" oifname \\\"$USER_IF\\\" ct state established,related accept

  # MASQUERADE Richtung Client-VLAN
  nft add rule inet rosenweg nat_post oifname \\\"$CLIENT_IF\\\" masquerade
" 2>&1 | sed 's/^/  /'

echo
echo \"[OK] VLAN $USER_VLAN auf CT \$LXC eingerichtet.\"
echo \"     Teste DHCP von einem Gerät im VLAN $USER_VLAN.\"
`;
}

// Vorschau ohne tatsaechlich zu provisionieren.
app.get('/api/isp/vlan-requests/:id/provision-plan', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const id = parseInt(req.params.id, 10);
    const ex = await pool.query(`
      SELECT v.*, cr.client_vlan_id AS router_client_vlan_id, cr.lxc_id AS router_lxc_id,
             cr.bezeichnung AS router_bezeichnung, cr.mgmt_ip AS router_mgmt_ip
        FROM isp_vlan_requests v
        LEFT JOIN isp_client_vlan_routers cr ON cr.id = v.assigned_router_id
        WHERE v.id = $1`, [id]);
    if (ex.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = ex.rows[0];
    const router = v.assigned_router_id ? {
      lxc_id: v.router_lxc_id,
      client_vlan_id: v.router_client_vlan_id,
      bezeichnung: v.router_bezeichnung,
      mgmt_ip: v.router_mgmt_ip,
    } : null;
    const issues = [];
    if (!v.vlan_id) issues.push('vlan_id fehlt (Antrag noch nicht approved?)');
    if (v.kind === 'subnet' && !v.subnet_v4) issues.push('subnet_v4 fehlt (CIDR z.B. 100.64.99.16/28)');
    if (v.kind === 'subnet' && !v.dhcp_range_from) issues.push('dhcp_range_from fehlt');
    if (v.kind === 'subnet' && !v.dhcp_range_to) issues.push('dhcp_range_to fehlt');
    if (v.kind === 'subnet' && !v.dhcp_gateway) issues.push('dhcp_gateway fehlt');
    if (v.kind === 'subnet' && !v.assigned_router_id) issues.push('assigned_router_id fehlt (Tab "Router zuweisen")');
    const script = (v.kind === 'subnet' && router) ? buildRouterLxcProvisionScript(v, router) : null;
    res.json({
      request: v,
      router,
      issues,
      unifi_network_will_be_created: !v.unifi_network_id,
      ppsk_will_be_added: v.with_wlan && !v.wlan_password,
      router_lxc_script: script,
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Provisioning-Kern, wiederverwendbar von POST /provision und vom PUT auto-deploy.
async function runProvisioning(id) {
  const ex = await pool.query(`
    SELECT v.*, cr.client_vlan_id AS router_client_vlan_id, cr.lxc_id AS router_lxc_id,
           cr.bezeichnung AS router_bezeichnung
      FROM isp_vlan_requests v
      LEFT JOIN isp_client_vlan_routers cr ON cr.id = v.assigned_router_id
      WHERE v.id = $1`, [id]);
  if (ex.rows.length === 0) throw new Error('Nicht gefunden');
  const v = ex.rows[0];
  if (v.status !== 'approved' && v.status !== 'deployed') {
    throw new Error(`Status "${v.status}" — Antrag muss zuerst approved sein`);
  }
  if (!v.vlan_id) throw new Error('vlan_id fehlt');
  const router = v.assigned_router_id ? {
    lxc_id: v.router_lxc_id, client_vlan_id: v.router_client_vlan_id, bezeichnung: v.router_bezeichnung,
  } : null;
  const result = { steps: [], errors: [] };

  // 1) UniFi Network anlegen (falls noch nicht passiert)
  let unifiNetId = v.unifi_network_id;
  if (!unifiNetId) {
    try {
      const created = await unifiCreateUserNetwork(v);
      unifiNetId = created._id || created.id || null;
      if (!unifiNetId) throw new Error('UniFi Response ohne _id: ' + JSON.stringify(created).slice(0, 200));
      result.steps.push({ step: 'unifi_network', ok: true, unifi_network_id: unifiNetId });
    } catch (err) {
      result.errors.push({ step: 'unifi_network', error: err.message });
    }
  } else {
    result.steps.push({ step: 'unifi_network', ok: true, skipped: 'already_exists', unifi_network_id: unifiNetId });
  }

  // 2) PPSK auf Rosenweg-WLAN (wenn with_wlan und noch kein Passwort)
  let wlanPw = v.wlan_password;
  if (v.with_wlan && !wlanPw && unifiNetId) {
    try {
      wlanPw = generatePpskPassword();
      await unifiAddPpskToRosenwegWlan(unifiNetId, wlanPw);
      result.steps.push({ step: 'ppsk', ok: true });
    } catch (err) {
      wlanPw = null;
      result.errors.push({ step: 'ppsk', error: err.message });
    }
  } else if (v.with_wlan && wlanPw) {
    result.steps.push({ step: 'ppsk', ok: true, skipped: 'already_set' });
  }

  // 3) Router-LXC live-provisionieren via dessen HTTP-API (eth1 in VLAN 3).
  //    Fallback: wenn API nicht erreichbar, Script generieren das der Admin
  //    auf dem passenden PVE-Host laufen lassen kann.
  let script = null;
  if (v.kind === 'subnet' && router && unifiNetId) {
    try {
      const rlxc = await pveProvisionRouterLxc(v, router);
      result.steps.push({ step: 'router_lxc', ok: true, node: rlxc.node, lxc_id: rlxc.lxc_id });
    } catch (err) {
      result.errors.push({ step: 'router_lxc', error: err.message });
      // Fallback-Script für manuelle Ausführung
      script = buildRouterLxcProvisionScript(v, router);
    }
  } else if (v.kind === 'subnet' && router) {
    script = buildRouterLxcProvisionScript(v, router);
  }

  // 4) DB updaten
  const updates = []; const params = [];
  const push = (col, val) => { params.push(val); updates.push(`${col} = $${params.length}`); };
  if (unifiNetId && unifiNetId !== v.unifi_network_id) push('unifi_network_id', unifiNetId);
  if (wlanPw && wlanPw !== v.wlan_password) push('wlan_password', wlanPw);
  if (result.errors.length === 0 && v.status === 'approved') {
    push('status', 'deployed');
    push('deployed_at', new Date());
  }
  if (updates.length > 0) {
    push('updated_at', new Date());
    params.push(id);
    await pool.query(`UPDATE isp_vlan_requests SET ${updates.join(', ')} WHERE id = $${params.length}`, params);
  }

  return {
    ok: result.errors.length === 0,
    unifi_network_id: unifiNetId,
    wlan_password: wlanPw,
    router_lxc_script: script,
    ...result,
  };
}

// Tatsaechliches Provisioning: UniFi + PPSK live anlegen, Router-LXC-Script generieren.
app.post('/api/isp/vlan-requests/:id/provision', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const id = parseInt(req.params.id, 10);
    const r = await runProvisioning(id);
    res.json(r);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// === Router-LXC pro Client-VLAN (Phase 2) ===
// Admin-only Verwaltung der LXCs die als Default-Gateway + DHCP für
// Netzwerk-Subnet-Anträge dienen. Auto-Provisioning ist Phase 3.
app.get('/api/isp/client-vlan-routers', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const r = await pool.query(`
      SELECT cr.*,
             (SELECT COUNT(*)::int FROM isp_vlan_requests v
                WHERE v.assigned_router_id = cr.id AND v.status IN ('approved','deployed')) AS assigned_count
        FROM isp_client_vlan_routers cr
        ORDER BY cr.client_vlan_id`);

    // Live-PVE-Lookup: pve_host + status werden aus dem Cluster gezogen, nicht
    // aus der DB (HA-Failover macht stored Host sofort stale). Wenn PVE-API
    // nicht erreichbar ist, bleibt live_node leer und das UI zeigt "—".
    let live = {};
    let pveError = null;
    try {
      const resources = await pveAPI('GET', '/cluster/resources?type=vm');
      for (const x of resources || []) {
        if (x.type === 'lxc' && Number.isInteger(x.vmid)) {
          live[x.vmid] = { node: x.node, status: x.status, name: x.name, uptime: x.uptime };
        }
      }
    } catch (err) { pveError = err.message; }

    const rows = r.rows.map(row => ({
      ...row,
      live_node: live[row.lxc_id]?.node || null,
      live_status: live[row.lxc_id]?.status || (Object.keys(live).length > 0 ? 'missing' : null),
      live_name: live[row.lxc_id]?.name || null,
    }));
    res.json({ client_vlan_routers: rows, pve_error: pveError });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

app.post('/api/isp/client-vlan-routers', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const b = req.body || {};
    if (b.client_vlan_id == null || !b.lxc_id) {
      return res.status(400).json({ error: 'client_vlan_id und lxc_id sind Pflicht' });
    }
    const cvi = parseInt(b.client_vlan_id, 10);
    const lxc = parseInt(b.lxc_id, 10);
    if (!Number.isInteger(cvi) || cvi < 1 || cvi > 4094) return res.status(400).json({ error: 'client_vlan_id muss 1-4094 sein' });
    if (!Number.isInteger(lxc) || lxc < 100 || lxc > 99999) return res.status(400).json({ error: 'lxc_id muss eine valide CT-ID sein' });
    const pool_default = b.user_vlan_subnet_pool || `192.168.${cvi}.0/24`;
    const r = await pool.query(
      `INSERT INTO isp_client_vlan_routers
         (client_vlan_id, bezeichnung, lxc_id, pve_host, mgmt_ip, upstream_gateway, active, notizen, user_vlan_subnet_pool)
       VALUES ($1,$2,$3,$4,$5,$6,COALESCE($7,true),$8,$9)
       RETURNING *`,
      [cvi, b.bezeichnung || null, lxc, b.pve_host || null,
       b.mgmt_ip || null, b.upstream_gateway || null, b.active, b.notizen || null, pool_default],
    );
    res.json(r.rows[0]);
  } catch (err) {
    if (err.code === '23505') return res.status(409).json({ error: 'Client-VLAN bereits vergeben' });
    res.status(500).json({ error: err.message });
  }
});

app.put('/api/isp/client-vlan-routers/:id', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const id = parseInt(req.params.id, 10);
    const ex = await pool.query('SELECT * FROM isp_client_vlan_routers WHERE id = $1', [id]);
    if (ex.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const b = req.body || {};
    const allowed = ['client_vlan_id','bezeichnung','lxc_id','pve_host','mgmt_ip','upstream_gateway','active','notizen','user_vlan_subnet_pool'];
    const updates = []; const params = [];
    const push = (col, val) => { params.push(val); updates.push(`${col} = $${params.length}`); };
    for (const col of allowed) if (b[col] !== undefined) push(col, b[col] === '' ? null : b[col]);
    if (updates.length === 0) return res.status(400).json({ error: 'Keine Änderungen' });
    push('updated_at', new Date());
    params.push(id);
    const r = await pool.query(`UPDATE isp_client_vlan_routers SET ${updates.join(', ')} WHERE id = $${params.length} RETURNING *`, params);
    res.json(r.rows[0]);
  } catch (err) {
    if (err.code === '23505') return res.status(409).json({ error: 'Client-VLAN bereits vergeben' });
    res.status(500).json({ error: err.message });
  }
});

// ── Phase 3a: CT-Bootstrap via PVE-API ────────────────────────────────
const PVE_LXC_DEFAULTS = {
  ostemplate: 'local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst',
  storage: 'lxcs',
  rootfs_gb: 4,
  cores: 1,
  memory: 256,
  swap: 256,
  bridge: 'vmbr1',
};

// Liste der PVE-Nodes aus /nodes (für Round-Robin).
async function pveNodes() {
  const data = await pveAPI('GET', '/nodes');
  return (data || []).filter(n => n.status === 'online').map(n => n.node);
}

// Existiert CT bereits irgendwo im Cluster?
async function pveCtExists(vmid) {
  const data = await pveAPI('GET', '/cluster/resources?type=vm');
  return (data || []).some(x => x.type === 'lxc' && x.vmid === vmid);
}

// Auf PVE-Task warten (UPID), poll status.
async function pveWaitForTask(node, upid, timeoutMs = 120000) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    const s = await pveAPI('GET', `/nodes/${node}/tasks/${encodeURIComponent(upid)}/status`);
    if (s && s.status === 'stopped') {
      if (s.exitstatus && s.exitstatus !== 'OK') throw new Error(`PVE-Task fehlgeschlagen: ${s.exitstatus}`);
      return s;
    }
    await new Promise(r => setTimeout(r, 1500));
  }
  throw new Error(`PVE-Task ${upid} timeout`);
}

// Eine Router-LXC anlegen + starten. Inner-Setup folgt per Script.
async function bootstrapOneRouterLxc(router, targetNode) {
  if (await pveCtExists(router.lxc_id)) return { vmid: router.lxc_id, skipped: 'already_exists' };
  const cvlan = router.client_vlan_id;
  // Hostname: VLAN 9 ist Rosenweg-Kooperation (RK), >9 ist pro Haus (HausNr = cvlan/10).
  const hostname = cvlan === 9
    ? 'rk-usernetze-router'
    : `rw${Math.floor(cvlan / 10)}-usernetze-router`;
  // mgmt_ip in /24 (Client-VLAN-Subnet 100.64.<vlan>.0/24 ist konventional)
  const ip = router.mgmt_ip ? router.mgmt_ip.split('/')[0] : `100.64.${cvlan}.9`;
  const gw = router.upstream_gateway ? router.upstream_gateway.split('/')[0] : `100.64.${cvlan}.1`;
  const body = {
    vmid: router.lxc_id,
    ostemplate: PVE_LXC_DEFAULTS.ostemplate,
    hostname,
    storage: PVE_LXC_DEFAULTS.storage,
    rootfs: `${PVE_LXC_DEFAULTS.storage}:${PVE_LXC_DEFAULTS.rootfs_gb}`,
    cores: PVE_LXC_DEFAULTS.cores,
    memory: PVE_LXC_DEFAULTS.memory,
    swap: PVE_LXC_DEFAULTS.swap,
    net0: `name=eth0,bridge=${PVE_LXC_DEFAULTS.bridge},ip=${ip}/24,gw=${gw},tag=${cvlan}`,
    unprivileged: 1,
    features: 'nesting=1',
    onboot: 1,
    start: 1,
    description: `Auto-erstellt vom isp-admin für Client-VLAN ${cvlan} (${router.bezeichnung || ''})`,
    // password: zufaellig, wir können via pct enter rein wenn nötig
    password: Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2),
  };
  const upid = await pveAPI('POST', `/nodes/${targetNode}/lxc`, body);
  await pveWaitForTask(targetNode, upid, 180000);
  return { vmid: router.lxc_id, node: targetNode, hostname, ip: `${ip}/24`, gw, upid };
}

// Bash-Skript für Inner-Install: apt + dnsmasq + nftables-Grundgeruest.
// Wird einmal pro neuer LXC vom Admin via "pct exec" ausgefuehrt.
function buildRouterLxcInitScript(router) {
  return `#!/usr/bin/env bash
# Inner-Setup für Router-LXC ${router.lxc_id} (Client-VLAN ${router.client_vlan_id})
# Ausfuehren auf dem PVE-Host wo CT laeuft:  bash <(curl -s ...)  oder copy/paste.
set -euo pipefail
LXC=${router.lxc_id}

pct exec $LXC -- bash -c '
  set -e
  export DEBIAN_FRONTEND=noninteractive
  apt-get update -q
  apt-get install -y -q dnsmasq nftables iproute2
  mkdir -p /etc/dnsmasq.d
  # leere dnsmasq.d-Configs: dnsmasq nur für User-VLANs (je nach Antrag)
  > /etc/dnsmasq.conf  # vorhandene globale Defaults raus
  echo "conf-dir=/etc/dnsmasq.d,*.conf" > /etc/dnsmasq.conf
  systemctl enable dnsmasq nftables
  # nftables-Grundgeruest: Tabelle + leere Chains (Regeln pro User-VLAN später)
  cat > /etc/nftables.conf <<EOF
flush ruleset
table inet rosenweg {
  chain forward { type filter hook forward priority 0; policy drop; }
  chain nat_post { type nat hook postrouting priority 100; policy accept; }
  chain input { type filter hook input priority 0; policy accept; }
}
EOF
  systemctl restart nftables dnsmasq
  echo "[OK] Router-LXC $LXC fertig: dnsmasq + nftables aktiv"
'

# HA-Resource registrieren (falls nicht schon)
if ! ha-manager status | grep -q "ct:$LXC"; then
  ha-manager add ct:$LXC --max_relocate 2 --max_restart 1 --state started
  echo "[OK] HA-Resource ct:$LXC registriert"
fi
`;
}

// Einen einzelnen Router-LXC bootstrappen.
app.post('/api/isp/client-vlan-routers/:id/bootstrap', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const id = parseInt(req.params.id, 10);
    const rr = await pool.query('SELECT * FROM isp_client_vlan_routers WHERE id = $1', [id]);
    if (rr.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const router = rr.rows[0];
    if (!router.lxc_id || router.lxc_id < 100) return res.status(400).json({ error: 'lxc_id ungueltig' });
    const nodes = await pveNodes();
    if (nodes.length === 0) return res.status(500).json({ error: 'Keine PVE-Nodes online' });
    // Round-robin via lxc_id modulo Node-Anzahl
    const targetNode = nodes[router.lxc_id % nodes.length];
    const result = await bootstrapOneRouterLxc(router, targetNode);
    const initScript = buildRouterLxcInitScript(router);
    res.json({ ok: true, ...result, init_script: initScript });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Alle fehlenden Router-LXCs bootstrappen.
app.post('/api/isp/client-vlan-routers/bootstrap-all', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const rr = await pool.query('SELECT * FROM isp_client_vlan_routers WHERE active = true ORDER BY client_vlan_id');
    const nodes = await pveNodes();
    if (nodes.length === 0) return res.status(500).json({ error: 'Keine PVE-Nodes online' });
    const results = [];
    for (const router of rr.rows) {
      try {
        const targetNode = nodes[router.lxc_id % nodes.length];
        const r = await bootstrapOneRouterLxc(router, targetNode);
        results.push({ router_id: router.id, lxc_id: router.lxc_id, ok: true, ...r });
      } catch (err) {
        results.push({ router_id: router.id, lxc_id: router.lxc_id, ok: false, error: err.message });
      }
    }
    // Globales Init-Script für ALLE auf einmal
    const initScript = `#!/usr/bin/env bash
# Inner-Setup für ALLE Router-LXCs in einem Rutsch.
# Auf jedem PVE-Host ausführen wo CTs liegen — pct exec funktioniert nur lokal.
set -euo pipefail
for LXC in ${rr.rows.map(r => r.lxc_id).join(' ')}; do
  pct status $LXC >/dev/null 2>&1 || { echo "[skip] CT $LXC nicht hier"; continue; }
  echo "=== Init CT $LXC ==="
  pct exec $LXC -- bash -c '
    set -e
    export DEBIAN_FRONTEND=noninteractive
    apt-get update -q
    apt-get install -y -q dnsmasq nftables iproute2
    mkdir -p /etc/dnsmasq.d
    echo "conf-dir=/etc/dnsmasq.d,*.conf" > /etc/dnsmasq.conf
    cat > /etc/nftables.conf <<EOF
flush ruleset
table inet rosenweg {
  chain forward { type filter hook forward priority 0; policy drop; }
  chain nat_post { type nat hook postrouting priority 100; policy accept; }
  chain input { type filter hook input priority 0; policy accept; }
}
EOF
    systemctl enable nftables dnsmasq
    systemctl restart nftables dnsmasq
  '
  ha-manager status 2>/dev/null | grep -q "ct:$LXC" || ha-manager add ct:$LXC --max_relocate 2 --max_restart 1 --state started || true
done
echo "[OK] Alle CTs initialisiert"
`;
    res.json({ results, init_script: initScript });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

app.delete('/api/isp/client-vlan-routers/:id', authMiddleware, async (req, res) => {
  try {
    if (!ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Admin' });
    const id = parseInt(req.params.id, 10);
    const used = await pool.query(
      "SELECT COUNT(*)::int AS n FROM isp_vlan_requests WHERE assigned_router_id = $1 AND status IN ('approved','deployed')",
      [id]);
    if (used.rows[0].n > 0) {
      return res.status(409).json({ error: `Router wird noch von ${used.rows[0].n} aktiven Antraegen benutzt — erst neu zuweisen` });
    }
    await pool.query('DELETE FROM isp_client_vlan_routers WHERE id = $1', [id]);
    res.json({ ok: true });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// === ISP-Wartungen / Stoerungen / Auto-Updates ===

// Permission: Technik OR Ausschuss (analog requireAusschussOrTechnik).
function ispMaintCanWrite(req) {
  const groups = (req.user?.groups || []).map(g => String(g || '').toLowerCase());
  return groups.some(g => g === 'technik' || g === 'ausschuss');
}

// Aus Geraete-Name HausNr extrahieren (z.B. "PoE-Switch1 R9 Heizungsraum" -> 9)
function hausFromDeviceName(name) {
  const m = String(name || '').match(/\bR(\d{1,2})\b/i);
  if (!m) return null;
  const h = parseInt(m[1], 10);
  return (h >= 1 && h <= 18) ? h : null;
}

// Email-Verteiler-Adresse des Ausschusses (statisch). Bekommt jede Wartungs-
// Mail mit, damit das Gremium informiert bleibt.
const MAINT_AUSSCHUSS_EMAIL = 'ausschuss@rosenweg4303.ch';
// Nur Technik darf die Wartungsmail als direkter (sichtbarer) To-Empfaenger
// bekommen. Alle anderen — inkl. Ausschuss — laufen verdeckt per BCC und
// damit ueber die Freigabe-Outbox.
const MAINT_TECHNIK_EMAIL = 'technik@rosenweg4303.ch';

// Per-Empfaenger-Throttle mit Combine-Puffer: max 1 Maintenance-Notification
// pro MAINT_NOTIFY_THROTTLE_MIN (default 30 Min). Was waehrend des Fensters
// reinkommt wird gepuffert und am Ende als Sammelmeldung verschickt.
// Gilt fuer alle Empfaenger inkl. Ausschuss-Verteiler.
const _MAINT_THROTTLE_RAW = parseInt(process.env.MAINT_NOTIFY_THROTTLE_MIN || '30', 10);
const MAINT_NOTIFY_THROTTLE_MIN = Number.isFinite(_MAINT_THROTTLE_RAW) ? _MAINT_THROTTLE_RAW : 30;

// Kernroutine: liefert eine Maintenance-Notification an alle Empfaenger.
//   - direkt-Sender bekommen sofort `body` (via `sendFn(directList, body)`)
//   - gethrottelte Empfaenger werden mit `body` in pending_lines gepuffert,
//     subject in pending_subjects. Spaeter flusht maintFlushNotifyPending.
// Rueckgabe: { sent, throttled }.
async function deliverMaintNotify({ channel, recipients, body, subject, sendFn }) {
  if (!Array.isArray(recipients) || recipients.length === 0) return { sent: 0, throttled: 0 };
  const list = recipients.filter(Boolean).map(r => String(r));
  if (MAINT_NOTIFY_THROTTLE_MIN <= 0) {
    try {
      const n = await sendFn(list, body);
      return { sent: typeof n === 'number' ? n : list.length, throttled: 0 };
    } catch (e) {
      console.warn('[maint-notify] sendFn error (no-throttle):', e.message);
      return { sent: 0, throttled: 0, error: e.message };
    }
  }
  const loweredList = list.map(c => c.toLowerCase());
  let blocked = new Set();
  {
    const r = await pool.query(
      `SELECT recipient FROM isp_maint_notify_throttle
        WHERE channel = $1
          AND recipient = ANY($2::text[])
          AND last_at > NOW() - ($3 || ' minutes')::interval`,
      [channel, loweredList, String(MAINT_NOTIFY_THROTTLE_MIN)],
    );
    blocked = new Set(r.rows.map(x => x.recipient));
  }
  const direct = [];
  const throttled = [];
  for (const c of list) {
    if (blocked.has(c.toLowerCase())) throttled.push(c);
    else direct.push(c);
  }
  let sent = 0;
  let sendFailed = false;
  if (direct.length) {
    try {
      const n = await sendFn(direct, body);
      sent = typeof n === 'number' ? n : direct.length;
    } catch (e) {
      console.warn('[maint-notify] sendFn error:', e.message);
      sendFailed = true;
    }
    // Throttle-Fenster nur starten wenn der Send wirklich erfolgreich war —
    // sonst wuerden wir Empfaenger 30 Min stilllegen die nichts bekommen haben.
    if (!sendFailed && sent > 0) {
      const lowered = direct.map(r => r.toLowerCase());
      await pool.query(
        `INSERT INTO isp_maint_notify_throttle (recipient, channel, last_at, pending_lines, pending_subjects)
         SELECT u, $1, NOW(), '{}'::text[], '{}'::text[] FROM unnest($2::text[]) AS u
         ON CONFLICT (recipient, channel) DO UPDATE SET last_at = NOW()`,
        [channel, lowered],
      );
    }
  }
  if (throttled.length) {
    const lowered = throttled.map(r => r.toLowerCase());
    // Append (body, subject) zu pending_lines/pending_subjects pro Empfaenger.
    // WICHTIG: last_at NICHT auf NOW()-interval seeden — der Empfaenger MUSS
    // bereits eine bestehende Throttle-Row haben (wurde ja als "blocked"
    // erkannt). Eine neue Row mit alten last_at zu erzeugen wuerde das
    // Combine-Fenster auf den naechsten Cron-Tick (60s) kollabieren statt
    // bis Ende des 30-Min-Fensters zu warten. Falls (race-condition) doch
    // keine Row da war, starten wir mit NOW() — der Combine-Window-Start.
    // Duplikate (gleicher body/subject) werden ignoriert.
    await pool.query(
      `INSERT INTO isp_maint_notify_throttle (recipient, channel, last_at, pending_lines, pending_subjects)
       SELECT u, $1, NOW(), ARRAY[$2::text], ARRAY[$3::text]
         FROM unnest($4::text[]) AS u
       ON CONFLICT (recipient, channel) DO UPDATE SET
         pending_lines = CASE
           WHEN $2::text = ANY(isp_maint_notify_throttle.pending_lines)
             THEN isp_maint_notify_throttle.pending_lines
           ELSE array_append(isp_maint_notify_throttle.pending_lines, $2::text)
         END,
         pending_subjects = CASE
           WHEN $3::text = ANY(isp_maint_notify_throttle.pending_subjects)
             THEN isp_maint_notify_throttle.pending_subjects
           ELSE array_append(isp_maint_notify_throttle.pending_subjects, $3::text)
         END`,
      [channel, body, subject || '', lowered],
    );
  }
  return { sent, throttled: throttled.length, sendFailed };
}

// Cron: flusht gebufferte pending_lines fuer Empfaenger deren Throttle
// abgelaufen ist. Kombiniert mehrere bodies zu einer Sammelmeldung.
//
// Race-safe via Postgres advisory lock — verhindert dass zwei ueberlappende
// Cron-Ticks dieselben Zeilen doppelt senden (passiert wenn ein Flush
// laenger als 60s dauert und der naechste Tick startet).
const MAINT_FLUSH_LOCK_KEY = 0x4D41494E54464C53n; // 'MAINTFLS' in hex
async function maintFlushNotifyPending() {
  let gotLock = false;
  try {
    const lockR = await pool.query('SELECT pg_try_advisory_lock($1) AS ok', [MAINT_FLUSH_LOCK_KEY.toString()]);
    gotLock = !!lockR.rows[0]?.ok;
    if (!gotLock) return; // anderer Tick laeuft noch
    const r = await pool.query(
      `SELECT recipient, channel, pending_lines, pending_subjects
         FROM isp_maint_notify_throttle
        WHERE array_length(pending_lines, 1) > 0
          AND last_at < NOW() - ($1 || ' minutes')::interval
        FOR UPDATE SKIP LOCKED`,
      [String(MAINT_NOTIFY_THROTTLE_MIN)],
    );
    for (const row of r.rows) {
      const lines = row.pending_lines || [];
      const subjects = row.pending_subjects || [];
      if (!lines.length) continue;
      let sendOk = false;
      try {
        if (row.channel === 'whatsapp') {
          const header = lines.length > 1
            ? `🔔 *Rosenweg ISP — Sammelmeldung* (${lines.length} Wartungen)\n\n`
            : '';
          const body = header + lines.join('\n\n— — —\n\n');
          const n = await pushWhatsappBroadcast({
            emails: [row.recipient], body,
            // sourceId muss numerisch sein (whatsapp_messages.source_id ist
            // INTEGER) — fuer Flush-Aggregate keine spezifische maint-id.
            sourceType: 'isp_maintenance_flush', sourceId: null,
          });
          sendOk = n > 0;
        } else if (row.channel === 'email') {
          const subj = subjects.length > 1
            ? `[Rosenweg ISP] Sammelmeldung: ${subjects.length} Wartungen`
            : (subjects[0] || '[Rosenweg ISP] Wartungs-Update');
          const text = (lines.length > 1
            ? `Hallo,\n\nmehrere Wartungs-Ereignisse wurden im selben Zeitraum gemeldet — hier die Sammelmeldung:\n\n`
            : '')
            + lines.join('\n\n------------------------------\n\n');
          await sendTemplated('maint-notify-flush', {
            mehrere: lines.length > 1, einzel: lines.length <= 1, anzahl: subjects.length,
            einzel_subject: subjects[0] || '[Rosenweg ISP] Wartungs-Update',
            lines_joined: lines.join('\n\n------------------------------\n\n'),
          }, {
            from: MAIL_FROM, to: row.recipient, subject: subj, text,
          });
          sendOk = true;
        }
      } catch (e) {
        console.warn(`[maint-notify-flush] ${row.channel} ${row.recipient}:`, e.message);
      }
      // pending_lines NUR leeren wenn Sendung wirklich raus ist — sonst
      // wuerden gepufferte Sammelmeldungen lautlos verschwinden bei einem
      // Transport-Fehler. Bei Erfolg: Throttle-Fenster reset auf NOW().
      if (sendOk) {
        await pool.query(
          `UPDATE isp_maint_notify_throttle
              SET pending_lines = '{}'::text[], pending_subjects = '{}'::text[], last_at = NOW()
            WHERE recipient = $1 AND channel = $2`,
          [row.recipient, row.channel],
        );
      }
    }
  } catch (e) {
    console.warn('[maint-notify-flush] error:', e.message);
  } finally {
    if (gotLock) {
      try { await pool.query('SELECT pg_advisory_unlock($1)', [MAINT_FLUSH_LOCK_KEY.toString()]); } catch {}
    }
  }
}

// Email-Recipients: Subscriber-Bewohner im scope + Ausschuss-Verteiler.
async function maintRecipientsForScope(scope) {
  const subs = await maintSubscriberRecipientsForScope(scope);
  return Array.from(new Set([...subs, MAINT_AUSSCHUSS_EMAIL]));
}

// Wie maintRecipientsForScope, aber nur Personen deren Wohnung auch einen
// isp_subscribers-Eintrag hat (= aktive Anschluss-Kunden). Fuer WhatsApp-Broadcast.
async function maintSubscriberRecipientsForScope(scope) {
  const allBewohner = !!scope?.all;
  const houses = Array.isArray(scope?.houses) ? scope.houses.map(Number).filter(Number.isFinite) : [];
  const vlans = Array.isArray(scope?.vlans) ? scope.vlans.map(Number).filter(Number.isFinite) : [];
  const reverseMap = Object.fromEntries(Object.entries(VPN_RW_TO_VLAN).map(([h, v]) => [v, parseInt(h, 10)]));
  for (const v of vlans) { const h = reverseMap[v]; if (h) houses.push(h); }
  const unique = Array.from(new Set(houses));
  let q, params;
  if (allBewohner || unique.length === 0) {
    q = `SELECT DISTINCT LOWER(p.email) AS email
           FROM personen p
           JOIN wohnungen_kontakte k ON k.person_id = p.id
           JOIN isp_subscribers s ON s.wohnung_id = k.wohnung_id
          WHERE k.archiviert_am IS NULL AND p.email IS NOT NULL AND p.email <> ''
            AND s.status IN ('aktiv','geplant')`;
    params = [];
  } else {
    q = `SELECT DISTINCT LOWER(p.email) AS email
           FROM personen p
           JOIN wohnungen_kontakte k ON k.person_id = p.id
           JOIN wohnungen w ON w.id = k.wohnung_id
           JOIN isp_subscribers s ON s.wohnung_id = w.id
          WHERE k.archiviert_am IS NULL
            AND p.email IS NOT NULL AND p.email <> ''
            AND s.status IN ('aktiv','geplant')
            AND (
              w.bezeichnung ~ ('^(' || $1::text || ')[\\.\\-]')
              OR w.bezeichnung ~* ('^RW(' || $1::text || ')-')
            )`;
    params = [unique.join('|')];
  }
  const r = await pool.query(q, params);
  return r.rows.map(x => x.email).filter(Boolean);
}

// Wartungs-WhatsApp geht NUR an die Technik-Gruppe (direkt, ohne Review) —
// gemaess ISP-Benachrichtigungs-Regel. KEIN Broadcast mehr an Subscriber-Kunden;
// die werden ausschliesslich ueber die freigegebene Outbox-Mail erreicht.
async function sendMaintenanceWhatsApp(maint, kind) {
  const sev = maint.severity === 'critical' ? '⚠⚠' : (maint.severity === 'warning' ? '⚠' : 'ℹ');
  const fmt = d => d ? new Date(d).toLocaleString('de-CH', { timeZone: 'Europe/Zurich', hour: '2-digit', minute: '2-digit', day: '2-digit', month: '2-digit' }) : '?';
  const body = kind === 'pre'
    ? `${sev} *Rosenweg ISP*\n*${maint.title}*\n\nGeplante Wartung: ${fmt(maint.start_at)} - ${fmt(maint.end_at)}\n\n${maint.description || ''}`
    : kind === 'start'
    ? `${sev} *Rosenweg ISP*\n*${maint.title}* beginnt JETZT.\n\nVoraussichtl. Ende: ${fmt(maint.end_at)}\n\n${maint.description || ''}`
    : `✓ *Rosenweg ISP*\n*${maint.title}* — Wartung abgeschlossen, Dienste wieder verfuegbar.`;
  try {
    const groupId = await resolveTechnikWhatsappGroupId();
    if (!groupId) return { sent: 0, skipped: 'no_technik_group' };
    await queueWhatsappMessage({
      chatId: groupId, body,
      sourceType: 'isp_maintenance', sourceId: maint.id || null,
    });
    return { sent: 1, target: 'technik-group' };
  } catch (e) {
    console.warn('[Maint-WhatsApp] error:', e.message);
    return { sent: 0, error: e.message };
  }
}

// ISP-Benachrichtigungs-Regel (vom User 2026-06-15):
//  - NUR Technik darf die Wartungsmeldung DIREKT (ohne Review) bekommen.
//  - ALLE anderen (Ausschuss + Subscriber-Kunden) werden ueber die Mail-Outbox
//    abgefangen: ihre Mail landet als 'pending' in verwaltung_mail_queue und
//    geht erst nach Freigabe durch Technik/Präsident per BCC raus.
async function sendMaintenanceMail(maint, kind /* 'pre'|'start'|'end' */) {
  const recipients = await maintRecipientsForScope(maint.scope || {});
  if (recipients.length === 0) return { sent: 0, queued: 0, skipped: 'no_recipients' };
  const sevPrefix = maint.severity === 'critical' ? '⚠ DRINGEND' : (maint.severity === 'warning' ? '⚠' : 'ℹ');
  const kindLabel = kind === 'pre' ? 'Erinnerung' : (kind === 'start' ? 'beginnt jetzt' : 'beendet');
  const subject = `${sevPrefix} [Rosenweg ISP] ${maint.title} — ${kindLabel}`;
  const fmt = d => d ? new Date(d).toLocaleString('de-CH', { timeZone: 'Europe/Zurich' }) : '?';
  const body = [
    `Hallo,`,
    ``,
    kind === 'pre' ? `eine Wartung ist in Kuerze geplant:` :
    kind === 'start' ? `eine Wartung beginnt JETZT:` :
    `die Wartung ist abgeschlossen:`,
    ``,
    `Titel: ${maint.title}`,
    `Zeitraum: ${fmt(maint.start_at)} - ${fmt(maint.end_at)}`,
    maint.description ? `\nBeschreibung:\n${maint.description}` : '',
    maint.auto_source === 'unifi_device_update' ? '\n(Diese Meldung wurde automatisch durch ein UniFi-Geraete-Update ausgeloest.)' : '',
    `\nFuer Rueckfragen: technik@rosenweg4303.ch`,
    `\nRosenweg ISP`,
  ].filter(Boolean).join('\n');
  // "Alle anderen" = alle Empfaenger ausser Technik (Ausschuss + Kunden).
  const others = recipients.filter(e => e.toLowerCase() !== MAINT_TECHNIK_EMAIL.toLowerCase());
  let directSent = 0, queueId = null, directErr = null, queueErr = null;
  // 1) DIREKT an Technik — ohne Review.
  try {
    await loggedSendMail({ from: MAIL_FROM, to: MAINT_TECHNIK_EMAIL, subject, text: body }, 'maint-notify-technik');
    directSent = 1;
  } catch (e) {
    directErr = e.message;
    console.warn('[Maint-Mail] Technik-Direktversand fehlgeschlagen:', e.message);
  }
  // 2) Alle anderen -> Mail-Outbox (pending, Freigabe noetig). To=noreply (self),
  //    BCC=Kunden+Ausschuss (verdeckt). Technik ist hier NICHT dabei (hat oben
  //    schon direkt bekommen).
  if (others.length > 0) {
    try {
      queueId = await enqueueVerwaltungMail({
        source_type: 'isp_maintenance',
        source_id: maint.id || null,
        mailTo: MAIL_FROM,
        mailBcc: others,
        subject,
        bodyText: body,
        createdBy: maint.auto_source ? `isp-maintenance-auto (${maint.auto_source})` : 'isp-maintenance',
      });
    } catch (e) {
      queueErr = e.message;
      console.warn('[Maint-Mail] enqueue error:', e.message);
    }
  }
  return { sent: directSent, queued: others.length, queue_id: queueId, direct_error: directErr, queue_error: queueErr };
}

// SCHEMA: jeder Endpoint joint die Counts der zu sendenden Notifs nicht — wir
