// === Traefik-Provider-Endpoint ===
// Liefert die dynamic-config für Traefik (http-provider). Kein authMiddleware
// nötig — der Endpoint laeuft nur über das interne Docker-Netz, Traefik
// pollt im 30s-Takt. Output: JSON (Traefik akzeptiert YAML+JSON).
app.get('/api/isp/traefik-config', async (req, res) => {
  // Gleiche Leak-Klasse wie /api/traefik/dynamic: exponiert Backend-URLs/IPs.
  // Konsument ist der Swarm-Traefik HTTP-Provider (sendet X-Traefik-Secret via
  // --providers.http.headers). Fail-closed: ohne korrektes Secret 403 — der
  // HTTP-Provider behaelt bei Fehler seine letzte Config.
  const expected = process.env.TRAEFIK_CONFIG_SECRET || '';
  if (!expected || req.headers['x-traefik-secret'] !== expected) {
    return res.status(403).json({ error: 'forbidden' });
  }
  try {
    const routes = (await pool.query(`SELECT * FROM isp_reverse_proxy_routes WHERE active = true`)).rows;
    const redirects = (await pool.query(`SELECT * FROM isp_redirects WHERE active = true`)).rows;
    const mailRelays = (await pool.query(`SELECT * FROM isp_mail_relays WHERE active = true`)).rows;
    const config = { http: { routers: {}, services: {}, middlewares: {} }, tcp: { routers: {}, services: {} } };

    // Dieser Endpoint wird vom Swarm-Traefik gepollt (HTTP-Provider).
    // Edge-Traefik nutzt /api/traefik/dynamic. Routen deren Backend auf
    // die Swarm-Traefik-VIP (100.64.2.27) zeigen sind "Edge -> Swarm"-
    // Routes; fuer Swarm-Traefik selbst waeren das Self-Loops (TLS-
    // Cert-Error 500, weil die VIP nicht im Cert-SAN ist). Diese Hosts
    // (isp, noc, test) werden Swarm-intern via Docker-Service-Labels
    // gerouted, daher hier rausfiltern.
    const SWARM_VIP_RE = /^(?:https?:\/\/)?100\.64\.2\.27(?:[:\/]|$)/i;

    // Reverse-Proxy-Routen
    routes.forEach((r, i) => {
      if (SWARM_VIP_RE.test(r.backend_url || '')) return;
      const id = 'rp_' + r.id;
      const middlewares = [];
      if (r.auth_required) {
        // Authentik-Forward-Auth Middleware (intern, expects auth.rosenweg4303.ch)
        config.http.middlewares['auth_' + r.id] = {
          forwardAuth: {
            address: 'https://auth.rosenweg4303.ch/outpost.goauthentik.io/auth/traefik',
            trustForwardHeader: true,
            authResponseHeaders: ['X-authentik-username','X-authentik-groups','X-authentik-email','X-authentik-name','X-authentik-uid'],
          },
        };
        middlewares.push('auth_' + r.id);
      }
      if (r.rate_limit_per_min) {
        config.http.middlewares['rl_' + r.id] = {
          rateLimit: { average: r.rate_limit_per_min, period: '1m', burst: r.rate_limit_per_min * 2 },
        };
        middlewares.push('rl_' + r.id);
      }
      config.http.routers[id] = {
        rule: `Host(\`${r.hostname}\`)`,
        service: id,
        entryPoints: ['websecure'],
        middlewares,
        ...(r.ssl ? { tls: r.ssl_method === 'letsencrypt' ? { certResolver: 'cf' } : (r.ssl_method === 'cloudflare-origin' ? {} : { certResolver: 'cf' }) } : {}),
      };
      config.http.services[id] = { loadBalancer: { servers: [{ url: r.backend_url }] } };
    });

    // Redirects (HTTP code 301/302) als Middleware + Router pattern
    redirects.forEach(rd => {
      const id = 'rd_' + rd.id;
      const ruleParts = [`Host(\`${rd.source_host}\`)`];
      if (rd.source_path && rd.source_path !== '/') ruleParts.push(`PathPrefix(\`${rd.source_path}\`)`);
      // Redirect-Middleware
      const regex = rd.preserve_path
        ? `^https?://${rd.source_host.replace(/\./g, '\\.')}/(.*)$`
        : `^https?://${rd.source_host.replace(/\./g, '\\.')}.*$`;
      const replacement = rd.preserve_path
        ? `${rd.target_url}/\${1}`
        : rd.target_url;
      config.http.middlewares[id] = {
        redirectRegex: { regex, replacement, permanent: rd.http_code === 301 || rd.http_code === 308 },
      };
      config.http.routers[id] = {
        rule: ruleParts.join(' && '),
        service: 'noop@internal', // dummy, der wird wegen redirect nie aufgerufen
        entryPoints: ['websecure'],
        middlewares: [id],
        tls: { certResolver: 'cf' },
      };
      // Auch HTTP (port 80) Router für redirect (ohne TLS)
      config.http.routers[id + '_http'] = {
        rule: ruleParts.join(' && '),
        service: 'noop@internal',
        entryPoints: ['web'],
        middlewares: [id],
      };
    });

    // TCP-Router: Multi-Tenant IMAPS/SMTPS via SNI-Passthrough
    // Pro Mail-Relay mit konfiguriertem imap_host bzw. smtps_host wird ein
    // TCP-Router angelegt, der TLS NICHT terminiert (passthrough). Der Client
    // sieht das End-Zertifikat des Backend-Servers direkt.
    mailRelays.forEach(mr => {
      // IMAPS (port 993)
      if (mr.imap_host && mr.imap_sni_hostname) {
        const id = 'imaps_' + mr.id;
        config.tcp.routers[id] = {
          entryPoints: ['imaps'],
          rule: `HostSNI(\`${mr.imap_sni_hostname}\`)`,
          service: id,
          tls: { passthrough: true },
        };
        config.tcp.services[id] = {
          loadBalancer: {
            servers: [{ address: `${mr.imap_host}:${mr.imap_port || 993}` }],
          },
        };
      }
      // SMTPS (port 465)
      if (mr.smtps_host && mr.smtps_sni_hostname) {
        const id = 'smtps_' + mr.id;
        config.tcp.routers[id] = {
          entryPoints: ['smtps'],
          rule: `HostSNI(\`${mr.smtps_sni_hostname}\`)`,
          service: id,
          tls: { passthrough: true },
        };
        config.tcp.services[id] = {
          loadBalancer: {
            servers: [{ address: `${mr.smtps_host}:${mr.smtps_port || 465}` }],
          },
        };
      }
    });

    // PVE-Cluster Reverse-Proxy mit sticky-cookie:
    //   pve-cluster1.rosenweg4303.ch -> sticky pve1/2/3:8006
    // Sticky garantiert dass nach Auth bzw. innerhalb einer noVNC-Konsolen-
    // Session der Client immer an denselben Node gerouted wird (PVE-Auth-
    // Token gilt zwar cluster-weit, aber Live-VM-Konsolen-Tunnel sind
    // node-bound). Backends sind PVE pveproxy auf 8006 mit Self-Signed —
    // pveSkipVerify Transport erlaubt re-encryption ohne Cert-Verify.
    config.http.serversTransports = config.http.serversTransports || {};
    config.http.serversTransports.pveSkipVerify = { insecureSkipVerify: true };
    config.http.routers.pve_cluster = {
      rule: 'Host(`pve-cluster1.rosenweg4303.ch`)',
      service: 'pve_cluster',
      entryPoints: ['websecure'],
      // Default-Cert (Self-Signed) statt LE — letsencrypt-Resolver ist rate-
      // limited fuer www/noc/isp. Sobald User pve-cluster1 als public CNAME
      // anlegt UND der Rate-Limit-Cooldown vorbei ist, kann auf
      // {certResolver:'letsencrypt'} umgestellt werden.
      tls: {},
    };
    config.http.services.pve_cluster = {
      loadBalancer: {
        sticky: {
          cookie: { name: 'pve_sticky', secure: false, httpOnly: true, sameSite: 'lax' },
        },
        // @http suffix erzwingt: serversTransports vom HTTP-Provider (statt
        // Docker/File/Swarm). Ohne suffix kann Traefik die Referenz nicht
        // aufloesen und kippt den ganzen Service still.
        serversTransport: 'pveSkipVerify@http',
        servers: [
          { url: 'https://100.64.2.20:8006' },
          { url: 'https://100.64.2.21:8006' },
          { url: 'https://100.64.2.22:8006' },
        ],
      },
    };

    // Leere Sub-Maps entfernen — Traefik weigert sich sonst beim Parsen
    // ("middlewares cannot be a standalone element").
    for (const top of ['http', 'tcp']) {
      if (!config[top]) continue;
      for (const sub of ['routers','services','middlewares']) {
        if (config[top][sub] && Object.keys(config[top][sub]).length === 0) delete config[top][sub];
      }
      if (Object.keys(config[top]).length === 0) delete config[top];
    }
    res.json(config);
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// ─── SMTP2GO-API Client ────────────────────────────────────────────────
// Sender-Domain-Verifikation (DKIM + Return-Path-CNAMEs) damit Outbound
// über unseren Smarthost mit DMARC-Alignment rausgeht.
// API-Doku: https://developers.smtp2go.com/llms.txt
async function smtp2goApi(path, body) {
  const key = process.env.SMTP2GO_API_KEY;
  if (!key) throw new Error('SMTP2GO_API_KEY nicht konfiguriert');
  const r = await fetch(`https://api.smtp2go.com/v3${path}`, {
    method: 'POST',
    headers: { 'X-Smtp2go-Api-Key': key, 'Content-Type': 'application/json' },
    body: JSON.stringify(body || {}),
    signal: AbortSignal.timeout(15000),
  });
  const text = await r.text();
  if (!r.ok) throw new Error(`SMTP2GO ${r.status}: ${text.slice(0,300)}`);
  const j = JSON.parse(text);
  if (j.data?.error) throw new Error(`SMTP2GO: ${j.data.error}`);
  return j.data;
}

// Holt aktuellen Verifikationsstatus + erwartete DNS-Records für eine Domain.
// Nutzt /v3/domain/verify (forciert sofortigen Recheck) statt /v3/domain/view.
async function smtp2goGetDomainStatus(domain) {
  const data = await smtp2goApi('/domain/verify', { domain });
  const entry = (data.domains || [])[0];
  if (!entry) return null;
  const d = entry.domain;
  const dkim_fqdn = `${d.dkim_selector}._domainkey.${d.fulldomain}`;
  const rpath_fqdn = `${d.rpath_selector}.${d.fulldomain}`;
  return {
    domain: d.fulldomain,
    dkim_verified: d.dkim_verified,
    rpath_verified: d.rpath_verified,
    records: [
      { type: 'CNAME', name: dkim_fqdn,  value: d.dkim_expected,  purpose: 'DKIM' },
      { type: 'CNAME', name: rpath_fqdn, value: d.rpath_expected, purpose: 'Return-Path' },
    ],
  };
}

// Domain bei SMTP2GO als Sender-Domain registrieren. Idempotent — ein
// "already exists" wird erfolgreich behandelt + per /verify nachgezogen.
async function smtp2goEnsureDomain(domain) {
  try {
    await smtp2goApi('/domain/add', { domain, returnpath_subdomain: 'em' });
  } catch (e) {
    if (!/already exists/i.test(e.message)) throw e;
  }
  return smtp2goGetDomainStatus(domain);
}

// ─── Mailcow-API Client ────────────────────────────────────────────────
// Ruft die Mailcow REST-API (https://mailcow.docs.apiary.io/) über den
// per /etc/default/asterisk-env oder docker-service-env gesetzten Key auf.
async function mailcowApi(method, path, body) {
  const base = process.env.MAILCOW_API_BASE;
  const key  = process.env.MAILCOW_API_KEY;
  if (!base || !key) throw new Error('MAILCOW_API_BASE/KEY nicht konfiguriert');
  const r = await fetch(`${base}/api/v1${path}`, {
    method,
    headers: { 'X-API-Key': key, 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
    // self-signed cert auf mailcow tolerieren
    signal: AbortSignal.timeout(15000),
  });
  const text = await r.text();
  if (!r.ok) throw new Error(`Mailcow ${r.status}: ${text.slice(0,300)}`);
  try { return JSON.parse(text); } catch { return text; }
}

// ─── Mailbox-Onboarding-Workflow ──────────────────────────────────────
// User auf isp-mein-zugang sieht/beantragt Mailboxes für eigene Mail-Relays
// mit mailcow_managed=true. Admin auf isp-admin approved + provisioniert.

// Notification an die WA-Gruppe "Rosenweg Technik" bei allen Mailbox-Vorgaengen.
// Wirft nicht — Notify-Fehler darf den eigentlichen Vorgang nicht blockieren.
async function notifyTechnik(text, sourceType = 'technik-event') {
  try {
    const groupId = await resolveTechnikWhatsappGroupId();
    if (!groupId) { console.warn(`[${sourceType}-notify] keine Technik-Group gefunden`); return; }
    await queueWhatsappMessage({
      chatId: groupId,
      body: text.slice(0, 3500),
      sourceType,
    });
  } catch (e) { console.warn(`[${sourceType}-notify]`, e.message); }
}
const notifyTechnikMailbox = (text) => notifyTechnik(text, 'mailbox-event');

// Generiert ein zufaelliges, sprechbares Initial-Passwort (16 Zeichen, alnum).
function generateMailboxPassword() {
  return crypto.randomBytes(12).toString('base64').replace(/[^a-zA-Z0-9]/g, '').slice(0, 16);
}

// Standard-Antrag = darf auto-approved werden (kein Custom-Quota, keine Notiz).
function isStandardMailboxRequest(b) {
  const q = b.quota_mb == null ? 1024 : parseInt(b.quota_mb, 10);
  const note = (b.notizen || '').trim();
  return q === 1024 && note.length === 0;
}

// Provisioniert Mailbox in Mailcow. Wirft bei Fehler.
async function provisionMailcowMailbox({ local_part, domain, full_name, quota_mb, password }) {
  await mailcowApi('POST', '/add/mailbox', {
    local_part,
    domain,
    name: full_name || local_part,
    quota: quota_mb || 1024,
    password,
    password2: password,
    active: '1',
    // force_pw_update=1 blockt unter SOGo+manchen IMAP-Backends den ersten
    // Login bis ein PW-Wechsel im UI passiert — für Auto-Approve nicht
    // praktikabel (User loggt sich direkt im Mail-Client an, nicht in SOGo).
    // Stattdessen den User im UI auffordern, das Initial-PW zu ändern.
    force_pw_update: '0',
    tls_enforce_in: '1',
    tls_enforce_out: '1',
  });
}

// GET: Liste der Domains für die der User Mailboxes beantragen darf
// (mailcow_managed + allowed_groups matchen User-Gruppen)
app.get('/api/isp/mailbox-eligible-relays', authMiddleware, async (req, res) => {
  try {
    const r = await pool.query(
      `SELECT id, domain, allowed_groups FROM isp_mail_relays
        WHERE active = true AND mailcow_managed = true
        ORDER BY domain`,
    );
    const eligible = r.rows.filter(rel => ispIsAdmin(req) || isAllowedForRelay(req.user, rel));
    res.json({ relays: eligible.map(r => ({ id: r.id, domain: r.domain })) });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET: Liste der Anträge/Mailboxen.
// initial_password wird NUR ausgeliefert wenn der Caller berechtigt ist:
//   - Shared-Mailbox (keinem User zugeordnet) -> Admin sieht PW
//   - persoenliche Mailbox -> NUR der zugeordnete User sieht PW (Admin nicht)
app.get('/api/isp/mailbox-requests', authMiddleware, async (req, res) => {
  try {
    const admin = ispIsAdmin(req);
    const email = (req.user.email || '').toLowerCase();
    const r = admin
      ? await pool.query(
          `SELECT mr.*, r.domain, r.mailcow_managed
             FROM mailbox_requests mr
             LEFT JOIN isp_mail_relays r ON r.id = mr.relay_id
            ORDER BY CASE mr.status WHEN 'pending' THEN 0 ELSE 1 END, mr.created_at DESC`,
        )
      : await pool.query(
          `SELECT mr.*, r.domain, r.mailcow_managed
             FROM mailbox_requests mr
             LEFT JOIN isp_mail_relays r ON r.id = mr.relay_id
            WHERE LOWER(mr.antragsteller_email) = $1
               OR LOWER(COALESCE(mr.assigned_user_email,'')) = $1
            ORDER BY mr.created_at DESC`,
          [email],
        );
    const rows = r.rows.map(row => {
      const ownerEmail = (row.assigned_user_email || row.antragsteller_email || '').toLowerCase();
      const isOwner = email === ownerEmail;
      const shared = !row.assigned_user_email;
      // PW sichtbar für: Owner immer; Admin nur bei Shared-Mailboxen.
      const canSeePw = isOwner || (admin && shared);
      if (!canSeePw) return { ...row, initial_password: null, has_initial_password: !!row.initial_password };
      return { ...row, has_initial_password: !!row.initial_password };
    });
    res.json({ requests: rows, is_admin: admin });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Prueft ob der User berechtigt ist Mailboxes für das Relay zu beantragen.
// allowed_groups = NULL -> jeder. Sonst muss min. eine Gruppe matchen
// (Authentik-Hierarchie: r9-eigentuemer impliziert eigentuemer etc.).
function isAllowedForRelay(user, relay) {
  if (!relay.allowed_groups || relay.allowed_groups.length === 0) return true;
  const userGroups = (user.groups || []).map(g => g.toLowerCase());
  return relay.allowed_groups.some(g => userGroups.includes(g.toLowerCase()));
}

// POST: neuer Antrag.
// Standardantrag (quota=1024, keine Notiz) -> Auto-Approve + sofortige
// Provisionierung in Mailcow. PW wird in initial_password gespeichert,
// damit der User es im UI sehen kann. assigned_user_email = User selbst
// (= persoenliche Zuordnung -> Admin sieht das PW NICHT).
app.post('/api/isp/mailbox-requests', authMiddleware, async (req, res) => {
  try {
    const b = req.body || {};
    if (!b.relay_id || !b.local_part) return res.status(400).json({ error: 'relay_id + local_part Pflicht' });
    const lp = String(b.local_part).toLowerCase().replace(/[^a-z0-9._-]/g, '');
    if (!lp) return res.status(400).json({ error: 'local_part ungueltig (nur a-z0-9._-)' });
    const rel = await pool.query('SELECT id, domain, owner_email, mailcow_managed, allowed_groups FROM isp_mail_relays WHERE id = $1', [b.relay_id]);
    if (rel.rows.length === 0) return res.status(404).json({ error: 'Mail-Relay nicht gefunden' });
    if (!rel.rows[0].mailcow_managed && !ispIsAdmin(req)) {
      return res.status(400).json({ error: 'Diese Domain wird nicht von Rosenweg verwaltet — Mailbox-Provisionierung beim Domain-Owner' });
    }
    if (!ispIsAdmin(req) && !isAllowedForRelay(req.user, rel.rows[0])) {
      return res.status(403).json({ error: `Mailboxen für ${rel.rows[0].domain} sind nur für berechtigte STWEG-Mitglieder verfuegbar` });
    }
    const standard = isStandardMailboxRequest(b);
    const username = `${lp}@${rel.rows[0].domain}`;

    if (standard) {
      // Auto-Approve: PW generieren, in Mailcow anlegen, in DB mit
      // status=approved + initial_password speichern.
      const password = generateMailboxPassword();
      try {
        await provisionMailcowMailbox({
          local_part: lp,
          domain: rel.rows[0].domain,
          full_name: b.full_name || null,
          quota_mb: 1024,
          password,
        });
      } catch (mcErr) {
        return res.status(502).json({ error: 'Mailcow-Provisionierung fehlgeschlagen: ' + mcErr.message });
      }
      const ins = await pool.query(
        `INSERT INTO mailbox_requests
           (relay_id, antragsteller_email, assigned_user_email, local_part, full_name, quota_mb,
            status, auto_approved, approved_by, approved_at, mailcow_synced_at, initial_password)
         VALUES ($1,$2,$2,$3,$4,1024,'approved',true,'auto',NOW(),NOW(),$5) RETURNING *`,
        [b.relay_id, req.user.email, lp, b.full_name || null, password],
      );
      notifyTechnikMailbox(
        `📬 *Mailbox auto-erstellt*\n${username}\nfuer ${req.user.email}${b.full_name ? ` (${b.full_name})` : ''}`,
      );
      // PW IM Response: persoenliche Mailbox -> User darf es sehen.
      return res.json({
        ...ins.rows[0],
        auto_approved: true,
        initial_password: password,
        username,
      });
    }

    // Custom-Antrag -> pending; Admin muss approven.
    const ins = await pool.query(
      `INSERT INTO mailbox_requests
         (relay_id, antragsteller_email, assigned_user_email, local_part, full_name, quota_mb, notizen)
       VALUES ($1,$2,$2,$3,$4,COALESCE($5,1024),$6) RETURNING *`,
      [b.relay_id, req.user.email, lp, b.full_name || null, b.quota_mb || null, b.notizen || null],
    );
    notifyTechnikMailbox(
      `📧 *Neuer Mailbox-Antrag* (pending)\n${username}\nvon ${req.user.email}` +
      `\nQuota: ${b.quota_mb || 1024} MB${b.notizen ? `\nNotiz: ${b.notizen}` : ''}` +
      `\n${SITE_URL}/isp-admin.html#mail`,
    );
    res.json(ins.rows[0]);
  } catch (err) {
    if (err.code === '23505') return res.status(409).json({ error: 'Diese Mailbox existiert bereits oder ist beantragt' });
    res.status(500).json({ error: err.message });
  }
});

// GET: User-Autocomplete für Admin-UI (Mailbox-Zuweisung). Liefert
// max. 20 Treffer aus users (active=true), gesucht in name + email.
app.get('/api/isp/user-search', authMiddleware, requireTechnikOrPraesident, async (req, res) => {
  try {
    const q = String(req.query.q || '').trim().toLowerCase();
    if (q.length < 2) return res.json({ users: [] });
    const r = await pool.query(
      `SELECT email, name FROM users
        WHERE active = true AND email IS NOT NULL
          AND (LOWER(email) LIKE $1 OR LOWER(COALESCE(name,'')) LIKE $1)
        ORDER BY name NULLS LAST, email
        LIMIT 20`,
      [`%${q}%`],
    );
    res.json({ users: r.rows });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST: Admin legt direkt eine Mailbox an, optional einem User zugeordnet.
// Ohne assigned_user_email -> Shared-Mailbox (Admin sieht PW).
// Mit assigned_user_email -> persoenlich (PW nur für User sichtbar).
app.post('/api/isp/admin-create-mailbox', authMiddleware, requireTechnikOrPraesident, async (req, res) => {
  try {
    const b = req.body || {};
    if (!b.relay_id || !b.local_part) return res.status(400).json({ error: 'relay_id + local_part Pflicht' });
    const lp = String(b.local_part).toLowerCase().replace(/[^a-z0-9._-]/g, '');
    if (!lp) return res.status(400).json({ error: 'local_part ungueltig' });
    const rel = await pool.query('SELECT id, domain, mailcow_managed FROM isp_mail_relays WHERE id = $1', [b.relay_id]);
    if (rel.rows.length === 0) return res.status(404).json({ error: 'Mail-Relay nicht gefunden' });
    if (!rel.rows[0].mailcow_managed) return res.status(400).json({ error: 'Domain nicht von Rosenweg verwaltet' });
    const assigned = (b.assigned_user_email || '').trim().toLowerCase() || null;
    const username = `${lp}@${rel.rows[0].domain}`;
    const password = generateMailboxPassword();
    try {
      await provisionMailcowMailbox({
        local_part: lp,
        domain: rel.rows[0].domain,
        full_name: b.full_name || null,
        quota_mb: b.quota_mb || 1024,
        password,
      });
    } catch (mcErr) {
      return res.status(502).json({ error: 'Mailcow-Provisionierung fehlgeschlagen: ' + mcErr.message });
    }
    const ins = await pool.query(
      `INSERT INTO mailbox_requests
         (relay_id, antragsteller_email, assigned_user_email, local_part, full_name, quota_mb,
          status, approved_by, approved_at, mailcow_synced_at, initial_password, notizen)
       VALUES ($1,$2,$3,$4,$5,COALESCE($6,1024),'approved',$7,NOW(),NOW(),$8,$9) RETURNING *`,
      [b.relay_id, req.user.email, assigned, lp, b.full_name || null, b.quota_mb || null,
       req.user.email, password, b.notizen || null],
    );
    notifyTechnikMailbox(
      `🛠 *Mailbox angelegt (Admin)*\n${username}\n` +
      (assigned ? `zugeordnet: ${assigned}` : `Shared-Mailbox (keinem User zugeordnet)`) +
      `\ndurch ${req.user.email}`,
    );
    // PW NUR im Response wenn keinem User zugeordnet (Admin = Antragsteller = Owner).
    const showPw = !assigned;
    res.json({
      ...ins.rows[0],
      username,
      ...(showPw ? { initial_password: password } : {}),
    });
  } catch (err) {
    if (err.code === '23505') return res.status(409).json({ error: 'Diese Mailbox existiert bereits' });
    res.status(500).json({ error: err.message });
  }
});

// POST: User markiert PW als gesichert -> initial_password=NULL.
app.post('/api/isp/mailbox-requests/:id/clear-password', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query('SELECT * FROM mailbox_requests WHERE id = $1', [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const mr = e.rows[0];
    const isOwner = (mr.assigned_user_email || mr.antragsteller_email || '').toLowerCase() === (req.user.email || '').toLowerCase();
    if (!isOwner && !ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Owner oder Admin' });
    await pool.query('UPDATE mailbox_requests SET initial_password=NULL, updated_at=NOW() WHERE id=$1', [id]);
    res.json({ ok: true });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST: Approve + Mailcow-Provisionierung (Admin only).
// PW im Response NUR wenn keinem User zugeordnet (Shared-Mailbox); sonst
// landet das PW in initial_password und der User holt es sich im Self-Service.
app.post('/api/isp/mailbox-requests/:id/approve', authMiddleware, requireTechnikOrPraesident, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query(
      `SELECT mr.*, r.domain, r.mailcow_managed FROM mailbox_requests mr
         LEFT JOIN isp_mail_relays r ON r.id = mr.relay_id WHERE mr.id = $1`, [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const mr = e.rows[0];
    if (mr.status === 'approved') return res.status(400).json({ error: 'Bereits approved' });
    if (!mr.mailcow_managed) return res.status(400).json({ error: 'Domain nicht von Rosenweg verwaltet' });

    const password = generateMailboxPassword();
    const username = `${mr.local_part}@${mr.domain}`;
    try {
      await provisionMailcowMailbox({
        local_part: mr.local_part,
        domain: mr.domain,
        full_name: mr.full_name,
        quota_mb: mr.quota_mb || 1024,
        password,
      });
    } catch (mcErr) {
      return res.status(502).json({ error: 'Mailcow-Provisionierung fehlgeschlagen: ' + mcErr.message });
    }
    await pool.query(
      `UPDATE mailbox_requests
          SET status='approved', approved_by=$1, approved_at=NOW(),
              approval_reason=$2, mailcow_synced_at=NOW(),
              initial_password=$3, updated_at=NOW()
        WHERE id=$4`,
      [req.user.email, req.body?.reason || null, password, id]
    );
    notifyTechnikMailbox(
      `✅ *Mailbox-Antrag genehmigt*\n${username}\nfuer ${mr.assigned_user_email || mr.antragsteller_email}\ndurch ${req.user.email}`,
    );
    const isAssigned = !!mr.assigned_user_email;
    res.json({
      ok: true,
      username,
      assigned: isAssigned,
      // Shared (keinem User zugeordnet) -> Admin sieht PW. Sonst nur Hinweis.
      ...(isAssigned ? { msg: 'Initial-PW liegt für den User unter "Meine Mailboxen" bereit' } : { initial_password: password }),
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST: Reject
app.post('/api/isp/mailbox-requests/:id/reject', authMiddleware, requireTechnikOrPraesident, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query('SELECT mr.*, r.domain FROM mailbox_requests mr LEFT JOIN isp_mail_relays r ON r.id = mr.relay_id WHERE mr.id=$1', [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const mr = e.rows[0];
    await pool.query(
      `UPDATE mailbox_requests SET status='rejected', approved_by=$1, approved_at=NOW(), approval_reason=$2, updated_at=NOW() WHERE id=$3`,
      [req.user.email, req.body?.reason || null, id]
    );
    notifyTechnikMailbox(
      `❌ *Mailbox-Antrag abgelehnt*\n${mr.local_part}@${mr.domain}\nvon ${mr.antragsteller_email}` +
      `${req.body?.reason ? `\nGrund: ${req.body.reason}` : ''}\ndurch ${req.user.email}`,
    );
    res.json({ ok: true });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// POST: Passwort-Reset. User+Admin dürfen. Visibility wie bei Approve:
//   - Mailbox keinem User zugeordnet -> Caller sieht PW
//   - Mailbox einem User zugeordnet  -> PW landet in initial_password,
//                                       Admin bekommt KEIN PW im Response,
//                                       User (Owner) bekommt das PW direkt.
app.post('/api/isp/mailbox-requests/:id/reset-password', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query(
      `SELECT mr.*, r.domain, r.mailcow_managed FROM mailbox_requests mr
         LEFT JOIN isp_mail_relays r ON r.id = mr.relay_id WHERE mr.id = $1`, [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const mr = e.rows[0];
    if (mr.status !== 'approved') return res.status(400).json({ error: 'Mailbox ist nicht aktiv' });
    const callerEmail = (req.user.email || '').toLowerCase();
    const ownerEmail = (mr.assigned_user_email || mr.antragsteller_email || '').toLowerCase();
    const admin = ispIsAdmin(req);
    const isOwner = callerEmail === ownerEmail;
    if (!admin && !isOwner) return res.status(403).json({ error: 'Nur Owner oder Admin' });

    const password = generateMailboxPassword();
    const username = `${mr.local_part}@${mr.domain}`;
    await mailcowApi('POST', '/edit/mailbox', {
      items: [username],
      attr: { password, password2: password, force_pw_update: '0' },
    });
    await pool.query('UPDATE mailbox_requests SET initial_password=$1, updated_at=NOW() WHERE id=$2', [password, id]);
    notifyTechnikMailbox(
      `🔑 *Passwort zurueckgesetzt*\n${username}\ndurch ${req.user.email}` +
      (admin && !isOwner ? ` (Admin-Reset für ${ownerEmail || '—'})` : ''),
    );
    // Visibility-Regel: Shared-Mailbox ODER Owner selber -> PW im Response.
    // Admin-Reset einer persoenlichen Mailbox -> KEIN PW im Response.
    const showPw = !mr.assigned_user_email || isOwner;
    res.json({
      ok: true,
      ...(showPw ? { new_password: password } : { msg: 'Neues PW liegt für den User unter "Meine Mailboxen" bereit' }),
    });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// DELETE: Mailbox löschen. Owner darf pending zuruecknehmen, Admin darf
// alles. Approved -> Mailbox wird in Mailcow geloescht.
app.delete('/api/isp/mailbox-requests/:id', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query(
      `SELECT mr.*, r.domain FROM mailbox_requests mr LEFT JOIN isp_mail_relays r ON r.id = mr.relay_id WHERE mr.id = $1`, [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const mr = e.rows[0];
    const admin = ispIsAdmin(req);
    const callerEmail = (req.user.email || '').toLowerCase();
    const ownerEmail = (mr.assigned_user_email || mr.antragsteller_email || '').toLowerCase();
    const isOwner = callerEmail === ownerEmail;
    if (!admin && !(isOwner && mr.status === 'pending')) {
      return res.status(403).json({ error: 'Nur Admin (alle) bzw. Owner (nur pending)' });
    }
    if (mr.status === 'approved') {
      try { await mailcowApi('POST', '/delete/mailbox', [`${mr.local_part}@${mr.domain}`]); }
      catch (mcErr) { console.warn('[mailbox-delete] Mailcow:', mcErr.message); }
    }
    // Hard-delete: Zeile entfernen, damit der Local-Part wieder
    // verfuegbar ist (UNIQUE-Constraint blockiert sonst Neu-Anlage).
    // Audit-Trail laeuft über den WA-Notify-Eintrag.
    await pool.query(`DELETE FROM mailbox_requests WHERE id=$1`, [id]);
    notifyTechnikMailbox(
      `🗑 *Mailbox geloescht*\n${mr.local_part}@${mr.domain}\nvon ${ownerEmail || '—'}\ndurch ${req.user.email}`,
    );
    res.json({ ok: true });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

