// ─── Outbound-Usage-Tracking ───────────────────────────────────────────
// PMG-Postfix-Logs werden vom /usr/local/sbin/pmg-usage-tracker.py geparst
// und per POST hier hingeschickt. Wir aggregieren pro (sender_domain, monat).
function requireTrackerSecret(req, res, next) {
  const expected = process.env.TRACKER_SHARED_SECRET || '';
  if (!expected || req.headers['x-tracker-secret'] !== expected) {
    return res.status(403).json({ error: 'forbidden' });
  }
  next();
}

// SMTP2GO Free-Tier: 1000/Monat. Schwellen für WA-Alert: 80%, 100%
// und danach in 500er-Schritten (1500, 2000, ...) damit wir bei
// kostenpflichtiger Nutzung jeweils dokumentiert werden.
const SMTP2GO_FREE_LIMIT = 1000;
function quotaThresholdsCrossed(prevTotal, newTotal) {
  // Erstmal die "weichen" Schwellen 80% und 100% des Free-Tiers
  const fixed = [Math.floor(SMTP2GO_FREE_LIMIT * 0.8), SMTP2GO_FREE_LIMIT];
  // Dann alle 500er über dem Free-Tier
  const beyond = [];
  for (let t = SMTP2GO_FREE_LIMIT + 500; t <= 50000; t += 500) beyond.push(t);
  return [...fixed, ...beyond].filter(t => prevTotal < t && newTotal >= t);
}

app.post('/api/isp/outbound-usage/ingest', requireTrackerSecret, async (req, res) => {
  try {
    const events = Array.isArray(req.body?.events) ? req.body.events : [];
    if (events.length === 0) return res.json({ ok: true, processed: 0 });
    // Quota-Prüfung pro betroffenem Monat: zuerst Vorher-Total holen,
    // dann nach UPSERT Nachher-Total und Schwellen vergleichen.
    const monthsTouched = new Set();
    let processed = 0;
    for (const ev of events) {
      const d = String(ev.sender_domain || '').toLowerCase().trim();
      const ym = String(ev.year_month || '').trim();
      const delta = parseInt(ev.count_delta, 10) || 0;
      if (!d || !/^\d{4}-\d{2}$/.test(ym) || delta <= 0) continue;
      await pool.query(
        `INSERT INTO isp_outbound_usage (sender_domain, year_month, count)
         VALUES ($1, $2, $3)
         ON CONFLICT (sender_domain, year_month) DO UPDATE
           SET count = isp_outbound_usage.count + EXCLUDED.count,
               last_updated_at = NOW()`,
        [d, ym, delta],
      );
      processed++;
      monthsTouched.add(ym);
    }

    // Quota-Alerts prüfen + ggf. WA-Notify
    for (const ym of monthsTouched) {
      try {
        const totalRow = await pool.query(
          `SELECT COALESCE(SUM(count),0)::int AS total FROM isp_outbound_usage WHERE year_month=$1`, [ym]);
        const newTotal = totalRow.rows[0].total;
        // Schwellen die VOR diesem Ingest noch nicht ueberschritten waren
        // (wir kennen das exakte Delta nicht — schaetzen über sum(delta) über alle Events)
        const deltaSum = events
          .filter(e => e.year_month === ym && parseInt(e.count_delta,10) > 0)
          .reduce((a, e) => a + parseInt(e.count_delta, 10), 0);
        const prevTotal = Math.max(0, newTotal - deltaSum);
        const crossed = quotaThresholdsCrossed(prevTotal, newTotal);
        for (const threshold of crossed) {
          // Nur einmal pro Schwelle pro Monat alerten
          const ins = await pool.query(
            `INSERT INTO isp_outbound_quota_alerts (year_month, threshold)
             VALUES ($1, $2) ON CONFLICT DO NOTHING RETURNING id`,
            [ym, threshold]);
          if (ins.rows.length === 0) continue;
          // Top 5 Sender-Domains anhängen damit man sieht wer's verbraucht
          const top = (await pool.query(
            `SELECT sender_domain, count FROM isp_outbound_usage
              WHERE year_month=$1 ORDER BY count DESC LIMIT 5`, [ym])).rows;
          const topList = top.map(t => `  • ${t.sender_domain}: ${t.count}`).join('\n');
          const pct = Math.round(newTotal / SMTP2GO_FREE_LIMIT * 100);
          const emoji = threshold >= SMTP2GO_FREE_LIMIT ? '🚨' : '⚠';
          notifyTechnikMailbox(
            `${emoji} *SMTP2GO Quota-Schwelle erreicht*\n` +
            `Monat ${ym}: ${newTotal} Mails (${pct}% des Free-Tiers)\n` +
            `Schwelle: ${threshold}${threshold >= SMTP2GO_FREE_LIMIT ? ' ⇒ ab jetzt kostenpflichtig' : ''}\n` +
            `\nTop-Sender:\n${topList}\n\n` +
            `Stand: ${SITE_URL}/isp-admin.html#mail`,
          );
        }
      } catch (qe) { console.warn('[outbound-usage] quota-alert:', qe.message); }
    }

    res.json({ ok: true, processed });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// GET: Monatsverlauf für eine Sender-Domain (Owner + Admin).
app.get('/api/isp/outbound-usage/:domain', authMiddleware, async (req, res) => {
  try {
    const domain = String(req.params.domain || '').toLowerCase();
    const months = Math.min(Math.max(parseInt(req.query.months, 10) || 12, 1), 36);
    // Authz: Owner (gegen isp_mail_relays) oder Admin
    const rel = await pool.query('SELECT owner_email FROM isp_mail_relays WHERE LOWER(domain)=$1', [domain]);
    const ownerEmail = rel.rows[0]?.owner_email?.toLowerCase() || '';
    if (!ispIsAdmin(req) && ownerEmail !== (req.user.email || '').toLowerCase()) {
      return res.status(403).json({ error: 'Nur Owner oder Admin' });
    }
    const r = await pool.query(
      `SELECT year_month, count FROM isp_outbound_usage
        WHERE sender_domain = $1
        ORDER BY year_month DESC LIMIT $2`,
      [domain, months],
    );
    res.json({ domain, months: r.rows });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// ─── Outbound-Smarthost (PMG → SMTP2GO) pro Mail-Relay ─────────────────
// Admin aktiviert "Outbound via Smarthost" pro Domain → wir registrieren
// die Domain bei SMTP2GO + liefern die noetigen CNAMEs (DKIM + Return-Path).
app.post('/api/isp/mail-relays/:id/smarthost', authMiddleware, requireTechnikOrPraesident, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const enable = !!req.body?.enable;
    const e = await pool.query('SELECT * FROM isp_mail_relays WHERE id = $1', [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = e.rows[0];

    if (!enable) {
      // Disable: Domain in SMTP2GO bleibt, wird nur entkoppelt. Wenn ganz raus
      // gewuenscht, kann Admin /domain/remove separat machen.
      await pool.query(
        `UPDATE isp_mail_relays SET outbound_via_smarthost=false, updated_at=NOW() WHERE id=$1`,
        [id]);
      return res.json({ ok: true, outbound_via_smarthost: false });
    }

    // Enable: bei SMTP2GO registrieren + Status holen
    let status;
    try { status = await smtp2goEnsureDomain(v.domain); }
    catch (err) { return res.status(502).json({ error: 'SMTP2GO: ' + err.message }); }
    await pool.query(
      `UPDATE isp_mail_relays SET
         outbound_via_smarthost=true,
         smtp2go_dkim_verified=$1, smtp2go_rpath_verified=$2,
         smtp2go_dns_records=$3, smtp2go_last_verify_at=NOW(), updated_at=NOW()
       WHERE id=$4`,
      [status.dkim_verified, status.rpath_verified, JSON.stringify(status.records), id]);
    res.json({ ok: true, outbound_via_smarthost: true, status });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

// Recheck-Status via SMTP2GO. Owner + Admin dürfen.
app.post('/api/isp/mail-relays/:id/smarthost/recheck', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query('SELECT * FROM isp_mail_relays WHERE id = $1', [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = e.rows[0];
    const isOwner = (v.owner_email || '').toLowerCase() === (req.user.email || '').toLowerCase();
    if (!isOwner && !ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Owner oder Admin' });
    if (!v.outbound_via_smarthost) return res.status(400).json({ error: 'Smarthost ist für diese Domain nicht aktiviert' });
    let status;
    try { status = await smtp2goGetDomainStatus(v.domain); }
    catch (err) { return res.status(502).json({ error: 'SMTP2GO: ' + err.message }); }
    if (!status) return res.status(404).json({ error: 'Domain nicht in SMTP2GO gefunden' });
    await pool.query(
      `UPDATE isp_mail_relays SET smtp2go_dkim_verified=$1, smtp2go_rpath_verified=$2,
         smtp2go_dns_records=$3, smtp2go_last_verify_at=NOW(), updated_at=NOW()
       WHERE id=$4`,
      [status.dkim_verified, status.rpath_verified, JSON.stringify(status.records), id]);
    res.json({ status });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

app.post('/api/isp/mail-relays/:id/recheck-dns', authMiddleware, async (req, res) => {
  try {
    const id = parseInt(req.params.id, 10);
    const e = await pool.query('SELECT * FROM isp_mail_relays WHERE id = $1', [id]);
    if (e.rows.length === 0) return res.status(404).json({ error: 'Nicht gefunden' });
    const v = e.rows[0];
    const isOwner = (v.owner_email || '').toLowerCase() === (req.user.email || '').toLowerCase();
    if (!isOwner && !ispIsAdmin(req)) return res.status(403).json({ error: 'Nur Owner oder Admin' });
    // Bei Mail-Relays prüfen wir MX statt A/AAAA
    const dns = (await import('node:dns/promises')).default;
    let mx = null;
    try { mx = await dns.resolveMx(v.domain).catch(() => null); } catch {}
    const target = ispResolveTarget();
    const matches = Array.isArray(mx) && mx.some(m => m.exchange?.toLowerCase().includes(target.cname_target.toLowerCase()) || m.exchange?.toLowerCase() === 'pmg.rosenweg4303.ch');
    const upd = matches
      ? { approval_status: 'approved', dns_verified_at: new Date(), last_dns_check_at: new Date(), active: true, approval_reason: 'MX zeigt auf PMG' }
      : { last_dns_check_at: new Date() };
    await pool.query(
      `UPDATE isp_mail_relays SET approval_status=COALESCE($1,approval_status), dns_verified_at=COALESCE($2,dns_verified_at),
         last_dns_check_at=$3, active=COALESCE($4,active), approval_reason=COALESCE($5,approval_reason) WHERE id=$6`,
      [upd.approval_status, upd.dns_verified_at, upd.last_dns_check_at, upd.active, upd.approval_reason, id],
    );
    res.json({ mx, target, matches, updated: upd });
  } catch (err) { res.status(500).json({ error: err.message }); }
});

